window.ATLAS_PREVIEW_POSTERS = [{"id":"confirmation","name":"Bias di conferma","english":"Confirmation bias","animal":"Pappagallo","animals":["Pappagallo"],"family":"Informazione","slogan":"La relazione ascolta anche ciò che disturba. Il limite ripete ciò che vuole sentire.","description":"Cerchiamo o interpretiamo informazioni in modo favorevole a un’ipotesi già presente. Le prove contrarie possono ricevere meno attenzione o essere reinterpretate in modo da non mettere in discussione l’ipotesi iniziale.","example":"Una prima ipotesi guida tutte le domande successive e rende invisibili le alternative.","question":"Quale osservazione mi farebbe rivedere questa ipotesi?","status":"definitive","note":"Poster definitivo fornito dall’autore nel primo gruppo di dieci immagini, 3 ottobre 2026. Abbinamento e slogan trascritti dal poster.","aliases":["conferma","ipotesi"],"order":0,"references":[{"label":"Raymond S. Nickerson (1998)","citation":"Confirmation bias: A ubiquitous phenomenon in many guises. Review of General Psychology, 2(2), 175–220.","url":"https://doi.org/10.1037/1089-2680.2.2.175"}],"authors":["Raymond S. Nickerson"],"referenceOrigin":"Inquadramento bibliografico aggiunto all’atlante; non implica una precedente approvazione della scheda.","image":"assets/definitivi/confirmation-original.png","thumb":"assets/definitivi/confirmation-thumb.webp","sourceName":"80885.png","variants":[],"closing":"Anteprima selettivamente loquace del prossimo libro.","original":"assets/definitivi/confirmation-original.png","approvalBatch":1,"seriesNumber":1,"section":"Bias cognitivi","topic":"Informazione"},{"id":"status-quo","name":"Bias dello status quo","english":"Status quo bias","animal":"Tartaruga","animals":["Tartaruga"],"family":"Decisione","slogan":"La relazione può chiedere cambiamento. Il limite, a volte, preferisce restare nel guscio.","description":"Preferire ciò che è già in uso può far sembrare il cambiamento più costoso delle alternative. La decisione tende a gravitare intorno all’opzione attuale.","example":"Continuare con una procedura familiare senza confrontarla con una nuova possibilità.","question":"Quali ragioni sostengono la scelta, oltre al fatto che è già quella attuale?","status":"definitive","note":"Poster definitivo fornito dall’autore nel primo gruppo di dieci immagini, 3 ottobre 2026. Abbinamento e slogan trascritti dal poster.","aliases":["cambiamento","the clash"],"order":1,"references":[{"label":"William Samuelson & Richard Zeckhauser (1988)","citation":"Status quo bias in decision making. Journal of Risk and Uncertainty, 1, 7–59.","url":"https://doi.org/10.1007/BF00055564"}],"authors":["William Samuelson","Richard Zeckhauser"],"referenceOrigin":"Inquadramento bibliografico aggiunto all’atlante; non implica una precedente approvazione della scheda.","image":"assets/definitivi/status-quo-original.png","thumb":"assets/definitivi/status-quo-thumb.webp","sourceName":"80887.png","variants":[],"closing":"Anteprima prudentemente conservativa del prossimo libro.","original":"assets/definitivi/status-quo-original.png","approvalBatch":1,"seriesNumber":2,"section":"Bias cognitivi","topic":"Decisione"},{"id":"blind-spot","name":"Punto cieco dei bias","english":"Blind spot bias","animal":"Camaleonte","animals":["Camaleonte"],"family":"Identità","slogan":"Il limite riconosce i bias degli altri. La relazione aiuta a vedere i propri.","description":"Possiamo riconoscere più facilmente le distorsioni nel giudizio degli altri che nel nostro. L’impressione di essere obiettivi non garantisce che lo siamo.","example":"Individuare l’ancoraggio di un collega e non riconoscere la propria prima impressione.","question":"Che cosa vedrebbe un osservatore esterno nel mio ragionamento?","status":"definitive","note":"Poster definitivo fornito dall’autore nel primo gruppo di dieci immagini, 3 ottobre 2026. Abbinamento e slogan trascritti dal poster.","aliases":["blind spot","punto cieco","bias blind spot"],"order":2,"references":[{"label":"Emily Pronin, Daniel Y. Lin & Lee Ross (2002)","citation":"The bias blind spot: Perceptions of bias in self versus others. Personality and Social Psychology Bulletin, 28(3), 369–381.","url":"https://doi.org/10.1177/0146167202286008"}],"authors":["Emily Pronin","Daniel Y. Lin","Lee Ross"],"referenceOrigin":"Inquadramento bibliografico aggiunto all’atlante; non implica una precedente approvazione della scheda.","image":"assets/definitivi/blind-spot-original.png","thumb":"assets/definitivi/blind-spot-thumb.webp","sourceName":"80888.png","variants":[],"closing":"Anteprima mimeticamente riflessiva del prossimo libro.","original":"assets/definitivi/blind-spot-original.png","approvalBatch":1,"seriesNumber":3,"section":"Bias cognitivi","topic":"Identità"},{"status":"definitive","note":"Poster definitivo fornito dall’autore nel primo gruppo di dieci immagini, 3 ottobre 2026. Abbinamento e slogan trascritti dal poster. L’immagine chiarisce che lo scoiattolo appartiene allo sconto iperbolico; la precedente associazione incerta con l’ancoraggio è stata corretta.","referenceOrigin":"Inquadramento bibliografico aggiunto all’atlante; non implica una precedente approvazione della scheda.","variants":[],"id":"hyperbolic-discounting","name":"Sconto iperbolico","english":"Hyperbolic discounting","animal":"Scoiattolo","animals":["Scoiattolo"],"family":"Decisione","description":"Una ricompensa disponibile subito può pesare molto più di una ricompensa futura, anche più grande. Con l’avvicinarsi del momento della scelta, le preferenze possono cambiare rispetto ai piani fatti in precedenza.","example":"Lo scoiattolo sceglie la ghianda immediata e trascura la scorta prevista per l’inverno. La scena rappresenta il peso del presente nella scelta.","question":"Sceglierei allo stesso modo se entrambe le ricompense fossero più lontane nel tempo?","authors":["David Laibson"],"references":[{"label":"David Laibson (1997)","citation":"Golden Eggs and Hyperbolic Discounting. The Quarterly Journal of Economics, 112(2), 443–478.","url":"https://doi.org/10.1162/003355397555253"}],"aliases":["sconto temporale","ricompensa immediata","present bias"],"legacyIds":["anchoring-squirrel"],"slogan":"La relazione tiene conto anche di domani. Il limite preferisce la ghianda subito.","closing":"Anteprima irresistibilmente immediata del prossimo libro.","sourceName":"80890.png","image":"assets/definitivi/hyperbolic-discounting-original.png","thumb":"assets/definitivi/hyperbolic-discounting-thumb.webp","original":"assets/definitivi/hyperbolic-discounting-original.png","approvalBatch":1,"seriesNumber":4,"order":3,"section":"Bias cognitivi","topic":"Decisione"},{"id":"anchoring-mussel","name":"Ancoraggio","english":"Anchoring bias","animal":"Cozza","animals":["Cozza"],"family":"Informazione","slogan":"La relazione aggiorna ciò che sa. Il limite resta attaccato alla prima impressione.","description":"Una prima informazione può fare da punto di riferimento e pesare troppo sui giudizi successivi. I dati nuovi vengono aggiustati intorno a quell’ancora invece di essere valutati con sufficiente apertura.","example":"Una prima valutazione negativa continua a orientare la lettura del caso, anche dopo l’arrivo di elementi favorevoli.","question":"Se iniziassi dai dati di oggi, arriverei alla stessa conclusione?","status":"definitive","note":"Poster definitivo fornito dall’autore nel primo gruppo di dieci immagini, 3 ottobre 2026. Abbinamento e slogan trascritti dal poster.","aliases":["prima impressione","ancora"],"order":4,"references":[{"label":"Amos Tversky & Daniel Kahneman (1974)","citation":"Judgment under Uncertainty: Heuristics and Biases. Science, 185, 1124–1131.","url":"https://doi.org/10.1126/science.185.4157.1124"}],"authors":["Amos Tversky","Daniel Kahneman"],"referenceOrigin":"Inquadramento bibliografico aggiunto all’atlante; non implica una precedente approvazione della scheda.","image":"assets/definitivi/anchoring-mussel-original.png","thumb":"assets/definitivi/anchoring-mussel-thumb.webp","sourceName":"80891.png","variants":[],"closing":"Anteprima ostinatamente ancorata del prossimo libro.","original":"assets/definitivi/anchoring-mussel-original.png","approvalBatch":1,"seriesNumber":5,"section":"Bias cognitivi","topic":"Informazione"},{"id":"negativity","name":"Bias della negatività","english":"Negativity bias","animal":"Riccio","animals":["Riccio"],"family":"Informazione","slogan":"La relazione tiene insieme tutto. Il limite dà più peso a ciò che punge.","description":"Le informazioni negative possono avere un impatto maggiore di quelle positive. Un dettaglio sfavorevole rischia di dominare il ricordo e la valutazione complessiva.","example":"Una critica isolata rimane più presente di molti riscontri positivi.","question":"Sto dando alle informazioni positive e negative un peso proporzionato?","status":"definitive","note":"Poster definitivo fornito dall’autore nel primo gruppo di dieci immagini, 3 ottobre 2026. Abbinamento e slogan trascritti dal poster.","aliases":["negativita","negativo"],"order":5,"references":[{"label":"Roy F. Baumeister, Ellen Bratslavsky, Catrin Finkenauer & Kathleen D. Vohs (2001)","citation":"Bad is stronger than good. Review of General Psychology, 5(4), 323–370.","url":"https://doi.org/10.1037/1089-2680.5.4.323"}],"authors":["Roy F. Baumeister","Ellen Bratslavsky","Catrin Finkenauer","Kathleen D. Vohs"],"referenceOrigin":"Inquadramento bibliografico aggiunto all’atlante; non implica una precedente approvazione della scheda.","image":"assets/definitivi/negativity-original.png","thumb":"assets/definitivi/negativity-thumb.webp","sourceName":"81747.png","variants":[],"closing":"Anteprima pungentemente selettiva del prossimo libro.","original":"assets/definitivi/negativity-original.png","approvalBatch":1,"seriesNumber":6,"section":"Bias cognitivi","topic":"Informazione"},{"id":"groupthink","name":"Pensiero di gruppo","english":"Groupthink","animal":"Pinguini","animals":["Pinguini"],"family":"Relazione","slogan":"La relazione accoglie anche il dissenso. Il limite comincia quando tutti smettono di contraddirsi.","description":"Il desiderio di accordo può ostacolare l’esame critico di alternative, rischi e obiezioni. La coesione diventa fragile quando il dissenso non trova più spazio.","example":"Il gruppo di pinguini procede nella stessa direzione; un pinguino in primo piano prende la parola. La scena invita a lasciare spazio alle obiezioni prima di decidere.","question":"Quale obiezione non è ancora stata ascoltata?","status":"definitive","note":"Poster definitivo fornito dall’autore nel primo gruppo di dieci immagini, 3 ottobre 2026. Abbinamento e slogan trascritti dal poster.","aliases":["gregge","gruppo","dissenso"],"order":6,"references":[{"label":"Irving L. Janis (1972)","citation":"Victims of groupthink: A psychological study of foreign-policy decisions and fiascoes. Houghton Mifflin.","url":"https://books.google.com/books?id=FB13AAAAMAAJ"}],"authors":["Irving L. Janis"],"referenceOrigin":"Inquadramento bibliografico aggiunto all’atlante; non implica una precedente approvazione della scheda.","image":"assets/definitivi/groupthink-original.png","thumb":"assets/definitivi/groupthink-thumb.webp","sourceName":"81819.png","variants":[],"closing":"Anteprima sospettosamente unanime del prossimo libro.","original":"assets/definitivi/groupthink-original.png","approvalBatch":1,"seriesNumber":7,"section":"Bias cognitivi","topic":"Relazione"},{"id":"peacock","name":"Effetto pavone","english":"Peacock effect","animal":"Pavone","animals":["Pavone"],"family":"Identità","slogan":"La relazione non ha bisogno della ruota. Il limite, ogni tanto, la apre tutta.","description":"Il pavone rappresenta la messa in mostra di un’immagine favorevole di sé. La ricerca di riconoscimento può spostare l’attenzione dall’incontro alla propria esibizione.","example":"In un gruppo, raccontare ciò che si sa diventa una gara a mostrare quanto si è speciali, riducendo lo spazio per ascoltare.","question":"Sto contribuendo alla relazione o cercando soprattutto conferme su di me?","status":"definitive","note":"Poster definitivo fornito dall’autore nel primo gruppo di dieci immagini, 3 ottobre 2026. Abbinamento e slogan trascritti dal poster.","aliases":["auto valorizzazione","self enhancement"],"order":7,"references":[{"label":"Constantine Sedikides & Aiden P. Gregg (2008)","citation":"Self-Enhancement: Food for Thought. Perspectives on Psychological Science, 3(2), 102–116.","url":"https://doi.org/10.1111/j.1745-6916.2008.00068.x"}],"authors":["Constantine Sedikides","Aiden P. Gregg"],"referenceOrigin":"Inquadramento bibliografico dell’auto-valorizzazione (self-enhancement), concetto collegato alla metafora del pavone. Non presenta “Peacock effect” come un sinonimo scientifico esatto.","image":"assets/definitivi/peacock-original.png","thumb":"assets/definitivi/peacock-thumb.webp","sourceName":"81817.png","variants":[],"closing":"Anteprima pavoneggiante del prossimo libro.","original":"assets/definitivi/peacock-original.png","approvalBatch":1,"seriesNumber":8,"section":"Bias cognitivi","topic":"Identità"},{"status":"definitive","note":"Poster definitivo fornito dall’autore nel primo gruppo di dieci immagini, 3 ottobre 2026. Abbinamento e slogan trascritti dal poster.","referenceOrigin":"Inquadramento bibliografico aggiunto all’atlante; non implica una precedente approvazione della scheda.","variants":[],"id":"ikea-effect","name":"Effetto IKEA","english":"IKEA effect","animal":"Castoro","animals":["Castoro"],"family":"Decisione","description":"Attribuiamo più valore a qualcosa che abbiamo contribuito a costruire. Negli studi sull’effetto IKEA questo aumento di valore dipende anche dal completamento riuscito del lavoro.","example":"Il castoro considera migliore la propria diga perché l’ha costruita lui, mentre una valutazione esterna può mettere alla prova il risultato.","question":"Quanto valuterei questo risultato se fosse stato costruito da qualcun altro?","authors":["Michael I. Norton","Daniel Mochon","Dan Ariely"],"references":[{"label":"Michael I. Norton, Daniel Mochon & Dan Ariely (2012)","citation":"The IKEA effect: When labor leads to love. Journal of Consumer Psychology, 22(3), 453–460.","url":"https://doi.org/10.1016/j.jcps.2011.08.002"}],"aliases":["lavoro","costruire","valore","fatto da me"],"slogan":"La relazione mette alla prova ciò che costruisce. Il limite lo considera migliore perché l’ha costruito lui.","closing":"Anteprima laboriosamente parziale del prossimo libro.","sourceName":"81816.png","image":"assets/definitivi/ikea-effect-original.png","thumb":"assets/definitivi/ikea-effect-thumb.webp","original":"assets/definitivi/ikea-effect-original.png","approvalBatch":1,"seriesNumber":9,"order":8,"section":"Bias cognitivi","topic":"Decisione"},{"status":"definitive","note":"Poster definitivo fornito dall’autore nel primo gruppo di dieci immagini, 3 ottobre 2026. Abbinamento e slogan trascritti dal poster.","referenceOrigin":"Inquadramento bibliografico aggiunto all’atlante; non implica una precedente approvazione della scheda.","variants":[],"id":"ostrich-bias","name":"Bias dello struzzo","english":"Ostrich bias","animal":"Struzzo","animals":["Struzzo"],"family":"Informazione","description":"Possiamo evitare informazioni che prevediamo spiacevoli, ritardando il confronto con ciò che accade. L’ostrich effect descrive questa attenzione selettiva, studiata anche nel monitoraggio delle proprie finanze.","example":"Rimandare l’apertura di un resoconto perché si teme una notizia sfavorevole. Lo struzzo del poster è una metafora dell’evitamento.","question":"Quale informazione sto evitando, e che cosa cambierebbe se la affrontassi?","authors":["Niklas Karlsson","George Loewenstein","Duane Seppi"],"references":[{"label":"Niklas Karlsson, George Loewenstein & Duane Seppi (2009)","citation":"The ostrich effect: Selective attention to information. Journal of Risk and Uncertainty, 38, 95–115.","url":"https://doi.org/10.1007/s11166-009-9060-6"}],"aliases":["ostrich effect","evitamento","informazione spiacevole"],"slogan":"La relazione affronta ciò che c’è. Il limite, a volte, mette la testa sotto la sabbia.","closing":"Anteprima elegantemente evitante del prossimo libro.","sourceName":"81800.png","image":"assets/definitivi/ostrich-bias-original.png","thumb":"assets/definitivi/ostrich-bias-thumb.webp","original":"assets/definitivi/ostrich-bias-original.png","approvalBatch":1,"seriesNumber":10,"order":9,"section":"Bias cognitivi","topic":"Informazione"},{"id":"survivorship","name":"Bias del sopravvissuto","english":"Survivorship bias","animal":"Salmone","animals":["Salmone"],"family":"Informazione","description":"Giudicare dai soli casi visibili o riusciti può farci ignorare quelli esclusi dall’osservazione. Il campione dei sopravvissuti non rappresenta necessariamente tutte le persone o le possibilità di partenza.","example":"Il salmone che supera il salto è visibile. Per valutare la difficoltà del percorso occorre considerare anche chi non è arrivato, invece di dedurre il successo di tutti dal caso riuscito.","question":"Quali casi mancano dal campione che sto osservando?","aliases":["sopravvivenza","sopravvissuti","selezione","pesce","wald"],"references":[{"label":"Abraham Wald (1943; ristampa 1980)","citation":"A Method of Estimating Plane Vulnerability Based on Damage of Survivors. Memoranda del Statistical Research Group, Columbia University; ristampa Center for Naval Analyses, CRC 432 (1980).","url":"https://www.cna.org/analyses/1980/a-method-of-estimating-plane-vulnerability"}],"authors":["Abraham Wald"],"referenceOrigin":"Inquadramento bibliografico aggiunto all’atlante; non implica una precedente approvazione della scheda.","variants":[],"status":"definitive","note":"Poster definitivo fornito dall’autore nel secondo gruppo di dieci immagini, 3 ottobre 2026. Abbinamento e slogan trascritti dal poster.","slogan":"La relazione considera anche chi manca. Il limite giudica guardando solo chi è arrivato.","closing":"Anteprima selettivamente sopravvissuta del prossimo libro.","approvalBatch":2,"seriesNumber":11,"sourceName":"81821.png","image":"assets/definitivi/survivorship-original.png","original":"assets/definitivi/survivorship-original.png","thumb":"assets/definitivi/survivorship-thumb.webp","order":10,"section":"Bias cognitivi","topic":"Informazione"},{"id":"sour-grapes","name":"Effetto dell’uva acerba","english":"Sour grapes effect","animal":"Volpe","animals":["Volpe"],"family":"Identità","slogan":"La relazione ammette che non tutto è facile. Il limite dice che l’uva, in fondo, era acerba.","description":"Quando qualcosa è difficile da ottenere, possiamo ridurne il valore per rendere più sopportabile la rinuncia. La metafora della volpe illustra una possibile razionalizzazione, collegata alla riduzione della dissonanza.","example":"La volpe non raggiunge il grappolo e conclude che non valeva la pena desiderarlo.","question":"Ho cambiato valutazione perché ho nuovi elementi o perché non posso ottenerlo?","status":"definitive","note":"Poster definitivo fornito dall’autore nel secondo gruppo di dieci immagini, 3 ottobre 2026. Abbinamento e slogan trascritti dal poster.","aliases":["uva acerba","razionalizzazione"],"order":11,"references":[{"label":"Leon Festinger (1957)","citation":"A Theory of Cognitive Dissonance. Stanford University Press.","url":"https://www.sup.org/books/sociology/theory-cognitive-dissonance"}],"authors":["Leon Festinger"],"referenceOrigin":"Inquadramento bibliografico aggiunto all’atlante; non implica una precedente approvazione della scheda.","image":"assets/definitivi/sour-grapes-original.png","thumb":"assets/definitivi/sour-grapes-thumb.webp","sourceName":"81823.png","variants":[],"closing":"Anteprima ironicamente autoassolutoria del prossimo libro.","approvalBatch":2,"seriesNumber":12,"original":"assets/definitivi/sour-grapes-original.png","section":"Bias cognitivi","topic":"Identità"},{"id":"hindsight","name":"Bias del senno di poi","english":"Hindsight bias","animal":"Gufo","animals":["Gufo"],"family":"Informazione","slogan":"La relazione ammette che capire prima non è sempre facile. Il limite dice che, dopo, era tutto perfettamente ovvio.","description":"Conoscere l’esito cambia il modo in cui ricostruiamo ciò che era prevedibile. Le incertezze originarie si attenuano e il risultato sembra più scontato di quanto fosse.","example":"Dopo una decisione sbagliata qualcuno dice “Lo sapevo già”, dimenticando le alternative e i dubbi presenti prima.","question":"Che cosa potevo sapere davvero prima di conoscere l’esito?","status":"definitive","note":"Poster definitivo fornito dall’autore nel secondo gruppo di dieci immagini, 3 ottobre 2026. Abbinamento e slogan trascritti dal poster.","aliases":[],"order":12,"references":[{"label":"Baruch Fischhoff (1975)","citation":"Hindsight ≠ foresight: The effect of outcome knowledge on judgment under uncertainty. Ristampa del lavoro originale del 1975, BMJ Quality & Safety (2003).","url":"https://qualitysafety.bmj.com/content/12/4/304"}],"authors":["Baruch Fischhoff"],"referenceOrigin":"Inquadramento bibliografico aggiunto all’atlante; non implica una precedente approvazione della scheda.","image":"assets/definitivi/hindsight-original.png","thumb":"assets/definitivi/hindsight-thumb.webp","sourceName":"81846.png","variants":[],"closing":"Anteprima ironicamente retrospettiva del prossimo libro.","approvalBatch":2,"seriesNumber":13,"original":"assets/definitivi/hindsight-original.png","section":"Bias cognitivi","topic":"Informazione"},{"id":"false-consensus","name":"Effetto del falso consenso","english":"False consensus effect","animal":"Gallo","animals":["Gallo"],"family":"Relazione","slogan":"La relazione ascolta anche ciò che l’altro pensa davvero. Il limite presume che, se lo penso io, allora lo pensano tutti.","description":"Le nostre scelte e opinioni possono sembrarci più condivise di quanto siano. Il consenso percepito va distinto dalle posizioni effettivamente espresse dagli altri.","example":"Il gallo presume che tutti condividano il suo pensiero, mentre gli altri animali mostrano reazioni diverse. Il consenso immaginato sostituisce l’ascolto di ciò che gli altri pensano davvero.","question":"Ho ascoltato gli altri o sto proiettando la mia posizione?","status":"definitive","note":"Poster definitivo fornito dall’autore nel secondo gruppo di dieci immagini, 3 ottobre 2026. Abbinamento e slogan trascritti dal poster.","aliases":["consenso","opinioni","galline"],"order":13,"references":[{"label":"Lee Ross, David Greene & Pamela House (1977)","citation":"The “false consensus effect”: An egocentric bias in social perception and attribution processes. Journal of Experimental Social Psychology, 13(3), 279–301.","url":"https://www.sciencedirect.com/science/article/pii/002210317790049X"}],"authors":["Lee Ross","David Greene","Pamela House"],"referenceOrigin":"Inquadramento bibliografico aggiunto all’atlante; non implica una precedente approvazione della scheda.","image":"assets/definitivi/false-consensus-original.png","thumb":"assets/definitivi/false-consensus-thumb.webp","sourceName":"81855.png","variants":[],"closing":"Anteprima ironicamente unanime del prossimo libro.","approvalBatch":2,"seriesNumber":14,"original":"assets/definitivi/false-consensus-original.png","section":"Bias cognitivi","topic":"Relazione"},{"id":"sunk-cost","name":"Bias dei costi affondati","english":"Sunk cost bias","animal":"Asino","animals":["Asino"],"family":"Decisione","slogan":"La relazione sa fermarsi. Il limite dice: ormai ho già investito troppo.","description":"Il tempo, il denaro o l’impegno già spesi possono spingerci a continuare una scelta, anche quando le prospettive future non la sostengono.","example":"L’asino continua a portare un carico sempre più pesante perché ha già investito troppo. Le risorse già spese prendono il posto della valutazione dei costi e benefici futuri.","question":"Se non avessi già investito, sceglierei ancora di continuare?","status":"definitive","note":"Poster definitivo fornito dall’autore nel secondo gruppo di dieci immagini, 3 ottobre 2026. Abbinamento e slogan trascritti dal poster.","aliases":["sunk cost","costi sommersi","investimento"],"order":14,"references":[{"label":"Hal R. Arkes & Catherine Blumer (1985)","citation":"The psychology of sunk cost. Organizational Behavior and Human Decision Processes, 35(1), 124–140.","url":"https://www.sciencedirect.com/science/article/pii/0749597885900494"}],"authors":["Hal R. Arkes","Catherine Blumer"],"referenceOrigin":"Inquadramento bibliografico aggiunto all’atlante; non implica una precedente approvazione della scheda.","image":"assets/definitivi/sunk-cost-original.png","thumb":"assets/definitivi/sunk-cost-thumb.webp","sourceName":"81856.png","variants":[],"closing":"Anteprima ostinatamente irrecuperabile del prossimo libro.","approvalBatch":2,"seriesNumber":15,"original":"assets/definitivi/sunk-cost-original.png","section":"Bias cognitivi","topic":"Decisione"},{"id":"halo-cat","name":"Effetto alone","english":"Halo effect","animal":"Gatto","animals":["Gatto"],"family":"Identità","slogan":"La relazione prova a distinguere un tratto dal giudizio complessivo. Il limite vede una qualità brillante e la estende a tutto il resto.","description":"Un’impressione globale favorevole influenza la valutazione di tratti che non abbiamo osservato. Eleganza, simpatia o carisma possono diventare una scorciatoia verso il giudizio di competenza.","example":"Il gatto sul trono è elegante e affascinante. Gli altri personaggi gli danno ragione prima di valutare ciò che dice.","question":"Quale caratteristica ho osservato davvero, e quali sto aggiungendo?","status":"definitive","note":"Poster definitivo fornito dall’autore nel secondo gruppo di dieci immagini, 3 ottobre 2026. Abbinamento e slogan trascritti dal poster.","aliases":["alone","carisma","cult of personality"],"order":15,"references":[{"label":"Richard E. Nisbett & Timothy D. Wilson (1977)","citation":"The halo effect: Evidence for unconscious alteration of judgments. Journal of Personality and Social Psychology, 35(4), 250–256.","url":"https://doi.org/10.1037/0022-3514.35.4.250"}],"authors":["Richard E. Nisbett","Timothy D. Wilson"],"referenceOrigin":"Inquadramento bibliografico aggiunto all’atlante; non implica una precedente approvazione della scheda.","image":"assets/definitivi/halo-cat-original.png","thumb":"assets/definitivi/halo-cat-thumb.webp","sourceName":"81910.png","variants":[],"closing":"Anteprima ironicamente abbagliata del prossimo libro.","approvalBatch":2,"seriesNumber":16,"original":"assets/definitivi/halo-cat-original.png","section":"Bias cognitivi","topic":"Identità"},{"id":"unrealistic-optimism","name":"Ottimismo irrealistico","english":"Unrealistic optimism bias","animal":"Cicala","animals":["Cicala"],"family":"Decisione","slogan":"La relazione considera anche i rischi. Il limite pensa: a me non succederà.","description":"La possibilità di esiti favorevoli può essere sopravvalutata, mentre la vulnerabilità personale ai rischi viene sottostimata. Il giudizio va valutato rispetto a dati e criteri espliciti.","example":"La cicala rimanda ogni precauzione e continua a cantare, mentre si avvicina il temporale: riconosce il rischio, ma lo considera poco probabile per sé.","question":"Quali dati rendono la mia previsione diversa da quella degli altri?","status":"definitive","note":"Poster definitivo fornito dall’autore nel secondo gruppo di dieci immagini, 3 ottobre 2026. Abbinamento e slogan trascritti dal poster.","aliases":["ottimismo","rischio","Weinstein"],"order":16,"references":[{"label":"James A. Shepperd, Erika A. Waters, Neil D. Weinstein & William M. P. Klein (2015)","citation":"A Primer on Unrealistic Optimism. Current Directions in Psychological Science, 24(3), 232–237.","url":"https://doi.org/10.1177/0963721414568341"}],"authors":["James A. Shepperd","Erika A. Waters","Neil D. Weinstein","William M. P. Klein"],"referenceOrigin":"Inquadramento bibliografico aggiunto all’atlante; non implica una precedente approvazione della scheda.","image":"assets/definitivi/unrealistic-optimism-original.png","thumb":"assets/definitivi/unrealistic-optimism-thumb.webp","sourceName":"81912.png","variants":[],"closing":"Anteprima spensieratamente imprudente del prossimo libro.","approvalBatch":2,"seriesNumber":17,"original":"assets/definitivi/unrealistic-optimism-original.png","section":"Bias cognitivi","topic":"Decisione"},{"id":"illusory-superiority","name":"Superiorità illusoria","english":"Illusory superiority","animal":"Aquila","animals":["Aquila"],"family":"Identità","slogan":"La relazione riconosce il proprio valore senza mettersi sopra gli altri. Il limite si guarda dall’alto e si scopre migliore della media.","description":"Il confronto con gli altri può diventare troppo favorevole a noi stessi, specialmente per qualità desiderabili e criteri lasciati vaghi.","example":"L’aquila si proclama decisamente migliore della media perché osserva gli altri dall’alto. La posizione nella scena richiama un confronto troppo favorevole a sé stessa.","question":"Quali criteri e riscontri sostengono il mio confronto?","status":"definitive","note":"Poster definitivo fornito dall’autore nel secondo gruppo di dieci immagini, 3 ottobre 2026. Abbinamento e slogan trascritti dal poster.","aliases":["superiorita","better than average"],"order":17,"references":[{"label":"Mark D. Alicke (1985)","citation":"Global self-evaluation as determined by the desirability and controllability of trait adjectives. Journal of Personality and Social Psychology, 49(6), 1621–1630.","url":"https://doi.org/10.1037/0022-3514.49.6.1621"}],"authors":["Mark D. Alicke"],"referenceOrigin":"Inquadramento bibliografico aggiunto all’atlante; non implica una precedente approvazione della scheda.","image":"assets/definitivi/illusory-superiority-original.png","thumb":"assets/definitivi/illusory-superiority-thumb.webp","sourceName":"81927.png","variants":[],"closing":"Anteprima orgogliosamente sopra la media del prossimo libro.","approvalBatch":2,"seriesNumber":18,"original":"assets/definitivi/illusory-superiority-original.png","section":"Bias cognitivi","topic":"Identità"},{"id":"reactive-devaluation","name":"Svalutazione reattiva","english":"Reactive devaluation bias","animal":"Avvoltoio","animals":["Avvoltoio"],"family":"Relazione","slogan":"La relazione prova a valutare la proposta per ciò che vale. Il limite la svaluta appena vede da chi proviene.","description":"Una proposta perde valore perché è attribuita a un rivale o a una fonte sfavorita. Il giudizio sulla provenienza prende il posto del giudizio sul contenuto.","example":"Gli altri animali svalutano la proposta appena vedono che a presentarla è un avvoltoio. La provenienza diventa un motivo per respingerla prima di valutarne il contenuto.","question":"Valuterei diversamente la stessa proposta se arrivasse da qualcuno di cui mi fido?","status":"definitive","note":"Poster definitivo fornito dall’autore nel secondo gruppo di dieci immagini, 3 ottobre 2026. Abbinamento e slogan trascritti dal poster.","aliases":[],"order":18,"references":[{"label":"Lee Ross & Constance Stillinger (1991)","citation":"Barriers to conflict resolution. Negotiation Journal, 7, 389–404.","url":"https://doi.org/10.1111/j.1571-9979.1991.tb00634.x"}],"authors":["Lee Ross","Constance Stillinger"],"referenceOrigin":"Inquadramento bibliografico aggiunto all’atlante; non implica una precedente approvazione della scheda.","image":"assets/definitivi/reactive-devaluation-original.png","thumb":"assets/definitivi/reactive-devaluation-thumb.webp","sourceName":"81928.png","variants":[],"closing":"Anteprima ironicamente diffidente del prossimo libro.","approvalBatch":2,"seriesNumber":19,"original":"assets/definitivi/reactive-devaluation-original.png","section":"Bias cognitivi","topic":"Relazione"},{"id":"loss-aversion","name":"Avversione alla perdita","english":"Loss aversion","animal":"Polpo","animals":["Polpo"],"family":"Decisione","slogan":"La relazione valuta anche ciò che potrebbe ottenere. Il limite sente molto di più ciò che potrebbe perdere.","description":"Rispetto a un punto di riferimento, una perdita può pesare più di un guadagno di pari entità. Il timore di lasciare qualcosa può così dominare la valutazione delle possibilità.","example":"Il polpo stringe il suo tesoro e guarda soprattutto il rischio di perderne una parte, mentre sullo sfondo ci sono nuove opportunità.","question":"Sto confrontando entrambe le possibilità o guardo soltanto ciò che rischio di perdere?","status":"definitive","note":"Poster definitivo fornito dall’autore nel secondo gruppo di dieci immagini, 3 ottobre 2026. Abbinamento e slogan trascritti dal poster.","aliases":[],"order":19,"references":[{"label":"Daniel Kahneman & Amos Tversky (1979)","citation":"Prospect Theory: An Analysis of Decision under Risk. Econometrica, 47(2), 263–291.","url":"https://doi.org/10.2307/1914185"}],"authors":["Daniel Kahneman","Amos Tversky"],"referenceOrigin":"Inquadramento bibliografico aggiunto all’atlante; non implica una precedente approvazione della scheda.","image":"assets/definitivi/loss-aversion-original.png","thumb":"assets/definitivi/loss-aversion-thumb.webp","sourceName":"81930.png","variants":[],"closing":"Anteprima prudentemente aggrappata del prossimo libro.","approvalBatch":2,"seriesNumber":20,"original":"assets/definitivi/loss-aversion-original.png","section":"Bias cognitivi","topic":"Decisione"},{"id":"probability-neglect","name":"Trascuratezza della probabilità","english":"Probability neglect","animal":"Elefante","animals":["Elefante"],"family":"Decisione","description":"Quando uno scenario evoca una forte emozione, possiamo concentrarci sulla gravità del possibile esito e dare troppo poco peso alla sua probabilità. Il rischio viene valutato soprattutto attraverso l’immagine temuta.","example":"L’elefante si rifugia sull’albero accanto al cartello “Evacuazione immediata”, mentre in basso compare “Pericolo possibile”. La scena mette a confronto possibilità e probabilità.","question":"Sto considerando quanto è probabile l’evento, oltre a quanto sarebbe grave?","authors":["Cass R. Sunstein"],"references":[{"label":"Cass R. Sunstein (2002)","citation":"Probability Neglect: Emotions, Worst Cases, and Law. The Yale Law Journal, 112(1), 61–107.","url":"https://yalelawjournal.org/essay/probability-neglect-emotions-worst-cases-and-law"}],"referenceOrigin":"Inquadramento bibliografico aggiunto all’atlante; non implica una precedente approvazione della scheda.","aliases":["probabilita","rischio","possibile","probabile"],"variants":[],"status":"definitive","note":"Poster definitivo fornito dall’autore nel terzo gruppo di dieci immagini, 4 ottobre 2026. Abbinamento e slogan trascritti dal poster.","slogan":"La relazione distingue tra possibile e probabile. Il limite sente \"potrebbe\" e capisce \"succederà\".","closing":"Anteprima sproporzionatamente allarmata del prossimo libro.","approvalBatch":3,"seriesNumber":21,"sourceName":"81933.png","image":"assets/definitivi/probability-neglect-original.png","original":"assets/definitivi/probability-neglect-original.png","thumb":"assets/definitivi/probability-neglect-thumb.webp","order":20,"section":"Bias cognitivi","topic":"Decisione"},{"id":"attribution","name":"Errore fondamentale di attribuzione","english":"Fundamental attribution error","animal":"Suricato","animals":["Suricato"],"family":"Relazione","slogan":"La relazione prova a capire anche la situazione. Il limite guarda ciò che fai e decide chi sei.","description":"Spiegare un comportamento soprattutto con le qualità della persona può oscurare il peso della situazione. La lettura del contesto resta necessaria.","example":"Un animale cade; il suricato conclude che sia incapace senza esplorare le condizioni del terreno e della situazione.","question":"Quali condizioni della situazione potrebbero contribuire al comportamento?","status":"definitive","note":"Poster definitivo fornito dall’autore nel terzo gruppo di dieci immagini, 4 ottobre 2026. Abbinamento e slogan trascritti dal poster.","aliases":["attribuzione","situazione","meerkat"],"order":21,"references":[{"label":"Lee Ross (1977)","citation":"The intuitive psychologist and his shortcomings: Distortions in the attribution process. Advances in Experimental Social Psychology, 10, 173–220.","url":"https://www.sciencedirect.com/science/chapter/bookseries/pii/S0065260108603573"}],"authors":["Lee Ross"],"referenceOrigin":"Inquadramento bibliografico aggiunto all’atlante; non implica una precedente approvazione della scheda.","image":"assets/definitivi/attribution-original.png","thumb":"assets/definitivi/attribution-thumb.webp","sourceName":"81935.png","variants":[],"closing":"Anteprima caratterialmente precipitosa del prossimo libro.","approvalBatch":3,"seriesNumber":22,"original":"assets/definitivi/attribution-original.png","section":"Bias cognitivi","topic":"Relazione"},{"id":"backfire","name":"Effetto boomerang","english":"Backfire effect","animal":"Armadillo","animals":["Armadillo"],"family":"Relazione","slogan":"La relazione propone. Il limite sente pressione e si convince ancora di più del contrario.","description":"Una contestazione può essere vissuta come minaccia e attivare una difesa delle proprie idee. Va distinto il rifiuto del messaggio dall’aumento misurabile della credenza errata: il backfire non è un esito generale e inevitabile delle correzioni.","example":"L’armadillo si chiude nella corazza mentre gli altri gli chiedono di cambiare idea. La pressione relazionale diventa il centro dell’interazione.","question":"Sto aiutando a valutare un’informazione o sto aumentando la difesa dell’identità?","status":"definitive","note":"Poster definitivo fornito dall’autore nel terzo gruppo di dieci immagini, 4 ottobre 2026. Abbinamento e slogan trascritti dal poster.","aliases":["reattanza","boomerang","correzione"],"order":22,"references":[{"label":"Thomas Wood & Ethan Porter (2019)","citation":"The Elusive Backfire Effect: Mass Attitudes’ Steadfast Factual Adherence. Political Behavior, 41, 135–163.","url":"https://doi.org/10.1007/s11109-018-9443-y"}],"authors":["Thomas Wood","Ethan Porter"],"referenceOrigin":"Inquadramento bibliografico aggiunto all’atlante; non implica una precedente approvazione della scheda.","image":"assets/definitivi/backfire-original.png","thumb":"assets/definitivi/backfire-thumb.webp","sourceName":"82257.png","variants":[],"closing":"Anteprima ostinatamente controcorrente del prossimo libro.","approvalBatch":3,"seriesNumber":23,"original":"assets/definitivi/backfire-original.png","section":"Bias cognitivi","topic":"Relazione"},{"id":"illusory-truth","name":"Effetto illusorio della verità","english":"Illusory truth effect","animal":"Picchio","animals":["Picchio"],"family":"Informazione","slogan":"La relazione verifica. Il limite confonde la ripetizione con la verità.","description":"La ripetizione rende una frase familiare e più facile da elaborare. Questa facilità può essere scambiata per un segnale di verità, anche quando non aggiunge alcuna prova.","example":"Un’affermazione ritorna in conversazioni, titoli e post. Dopo averla sentita molte volte, comincia a sembrare un fatto acquisito.","question":"L’ho verificato, oppure l’ho soltanto sentito ripetere?","status":"definitive","note":"Poster definitivo fornito dall’autore nel terzo gruppo di dieci immagini, 4 ottobre 2026. Abbinamento e slogan trascritti dal poster.","aliases":["ripetizione","verita illusoria"],"order":23,"references":[{"label":"Lynn Hasher, David Goldstein & Thomas Toppino (1977)","citation":"Frequency and the conference of referential validity. Journal of Verbal Learning and Verbal Behavior, 16(1), 107–112.","url":"https://doi.org/10.1016/S0022-5371(77)80012-1"}],"authors":["Lynn Hasher","David Goldstein","Thomas Toppino"],"referenceOrigin":"Inquadramento bibliografico aggiunto all’atlante; non implica una precedente approvazione della scheda.","image":"assets/definitivi/illusory-truth-original.png","thumb":"assets/definitivi/illusory-truth-thumb.webp","sourceName":"82258.png","variants":[],"closing":"Anteprima insistentemente credibile del prossimo libro.","approvalBatch":3,"seriesNumber":24,"original":"assets/definitivi/illusory-truth-original.png","section":"Bias cognitivi","topic":"Informazione"},{"id":"polarization","name":"Polarizzazione di gruppo","english":"Group polarization","animal":"Due gruppi di animali","animals":["Due gruppi di animali"],"family":"Relazione","slogan":"La relazione cerca un terreno comune. Il limite ascolta i propri e si allontana sempre di più dagli altri.","description":"La discussione fra persone con orientamenti simili può spostare le posizioni del gruppo verso una maggiore estremità nella direzione già prevalente. Il poster usa due gruppi contrapposti per rendere visibile l’irrigidimento delle posizioni.","example":"Gli animali con maglie Juventus e Inter ascoltano soprattutto i propri compagni e indicano gli altri come il problema. Il confronto si restringe, mentre le posizioni si rafforzano.","question":"Nel mio gruppo stiamo esaminando alternative o rendendo più estrema una posizione già condivisa?","status":"definitive","note":"Poster definitivo fornito dall’autore nel terzo gruppo di dieci immagini, 4 ottobre 2026. Abbinamento e slogan trascritti dal poster.","aliases":["juventus","inter","gruppi","polarizzazione","attitude polarization"],"order":24,"references":[{"label":"Serge Moscovici & Marisa Zavalloni (1969)","citation":"The group as a polarizer of attitudes. Journal of Personality and Social Psychology, 12(2), 125–135.","url":"https://doi.org/10.1037/h0027568"}],"authors":["Serge Moscovici","Marisa Zavalloni"],"referenceOrigin":"Inquadramento bibliografico aggiunto all’atlante; non implica una precedente approvazione della scheda.","image":"assets/definitivi/polarization-original.png","thumb":"assets/definitivi/polarization-thumb.webp","sourceName":"82262.png","variants":[],"closing":"Anteprima tifosamente divisiva del prossimo libro.","approvalBatch":3,"seriesNumber":25,"original":"assets/definitivi/polarization-original.png","section":"Bias cognitivi","topic":"Relazione"},{"id":"framing","name":"Effetto cornice","english":"Framing effect","animal":"Serpente","animals":["Serpente"],"family":"Decisione","description":"La formulazione di una scelta può cambiare il giudizio anche quando le informazioni restano equivalenti. Mettere in primo piano i guadagni o le perdite modifica il modo in cui interpretiamo le possibilità.","example":"Il serpente presenta lo stesso dato come 70% di possibilità di successo oppure 30% di possibilità di fallimento. Cambia la cornice, mentre l’informazione resta la stessa.","question":"Prenderei la stessa decisione se gli stessi dati fossero presentati nell’altra cornice?","authors":["Amos Tversky","Daniel Kahneman"],"references":[{"label":"Amos Tversky & Daniel Kahneman (1981)","citation":"The Framing of Decisions and the Psychology of Choice. Science, 211(4481), 453–458.","url":"https://doi.org/10.1126/science.7455683"}],"referenceOrigin":"Inquadramento bibliografico aggiunto all’atlante; non implica una precedente approvazione della scheda.","aliases":["cornice","presentazione","70%","30%"],"variants":[],"status":"definitive","note":"Poster definitivo fornito dall’autore nel terzo gruppo di dieci immagini, 4 ottobre 2026. Abbinamento e slogan trascritti dal poster.","slogan":"La relazione guarda il contenuto. Il limite si lascia guidare da come viene presentato.","closing":"Anteprima strategicamente incorniciata del prossimo libro.","approvalBatch":3,"seriesNumber":26,"sourceName":"82287.png","image":"assets/definitivi/framing-original.png","original":"assets/definitivi/framing-original.png","thumb":"assets/definitivi/framing-thumb.webp","order":25,"section":"Bias cognitivi","topic":"Decisione"},{"id":"affect","name":"Euristica dell’affetto","english":"Affect heuristic","animal":"Ragno","animals":["Ragno"],"family":"Decisione","slogan":"La relazione prova a distinguere ciò che sente da ciò che sa. Il limite sente paura e conclude: dev’essere pericoloso.","description":"Il sentimento associato a qualcosa entra nella valutazione di rischi e benefici. L’emozione offre un orientamento rapido, ma può sostituire l’esame delle informazioni pertinenti.","example":"Gli animali hanno paura del ragno e ne deducono la pericolosità, mentre il ragno offre un fiore.","question":"Che cosa mi dice l’emozione, e che cosa mi dicono i dati?","status":"definitive","note":"Poster definitivo fornito dall’autore nel terzo gruppo di dieci immagini, 4 ottobre 2026. Abbinamento e slogan trascritti dal poster.","aliases":["tarantola","emozione","paura"],"order":26,"references":[{"label":"Paul Slovic, Melissa L. Finucane, Ellen Peters & Donald G. MacGregor (2007)","citation":"The affect heuristic. European Journal of Operational Research, 177(3), 1333–1352.","url":"https://www.sciencedirect.com/science/article/pii/S0377221705003577"}],"authors":["Paul Slovic","Melissa L. Finucane","Ellen Peters","Donald G. MacGregor"],"referenceOrigin":"Inquadramento bibliografico aggiunto all’atlante; non implica una precedente approvazione della scheda.","image":"assets/definitivi/affect-original.png","thumb":"assets/definitivi/affect-thumb.webp","sourceName":"82337.png","variants":[],"closing":"Anteprima emotivamente sospetta del prossimo libro.","approvalBatch":3,"seriesNumber":27,"original":"assets/definitivi/affect-original.png","section":"Bias cognitivi","topic":"Decisione"},{"id":"self-serving","name":"Bias dell’auto-attribuzione","english":"Self-serving bias","animal":"Leone","animals":["Leone"],"family":"Identità","slogan":"La relazione riconosce meriti e responsabilità. Il limite si prende i successi e distribuisce le colpe.","description":"Successi e insuccessi possono essere spiegati in modi che proteggono l’immagine di sé: merito personale quando va bene, circostanze o altri quando va male. La revisione di Miller e Ross discute anche spiegazioni cognitive, non solo motivazionali.","example":"Il leone festeggia “Merito mio!”, ma dopo la sconfitta indica campo, fortuna e compagni.","question":"Sto usando lo stesso criterio per attribuire successi e fallimenti?","status":"definitive","note":"Poster definitivo fornito dall’autore nel terzo gruppo di dieci immagini, 4 ottobre 2026. Abbinamento e slogan trascritti dal poster.","aliases":["autoattribuzione","merito","colpa"],"order":27,"references":[{"label":"Dale T. Miller & Michael Ross (1975)","citation":"Self-serving biases in the attribution of causality: Fact or fiction? Psychological Bulletin, 82(2), 213–225.","url":"https://www.gsb.stanford.edu/faculty-research/publications/self-serving-biases-attribution-causality-fact-or-fiction"}],"authors":["Dale T. Miller","Michael Ross"],"referenceOrigin":"Inquadramento bibliografico aggiunto all’atlante; non implica una precedente approvazione della scheda.","image":"assets/definitivi/self-serving-original.png","thumb":"assets/definitivi/self-serving-thumb.webp","sourceName":"82357.png","variants":[],"closing":"Anteprima convenientemente autoassolutoria del prossimo libro.","approvalBatch":3,"seriesNumber":28,"original":"assets/definitivi/self-serving-original.png","section":"Bias cognitivi","topic":"Identità"},{"id":"affinity","name":"Bias di affinità","english":"Affinity bias","animal":"Fenicotteri","animals":["Fenicotteri"],"family":"Relazione","slogan":"La relazione prova a conoscere anche chi è diverso. Il limite si fida più facilmente di chi gli somiglia.","description":"La somiglianza percepita può facilitare fiducia e preferenza. Nella selezione di una persona, sentirla “una di noi” rischia di contare più dei criteri pertinenti.","example":"I fenicotteri condividono sciarpa dell’Inter e rituali. Nel colloquio questa familiarità si sovrappone alla valutazione di esperienza e competenza.","question":"Sto scegliendo per competenza o per familiarità?","status":"definitive","note":"Poster definitivo fornito dall’autore nel terzo gruppo di dieci immagini, 4 ottobre 2026. Abbinamento e slogan trascritti dal poster.","aliases":["affinita","inter","selezione"],"order":28,"references":[{"label":"Donn Byrne (1971)","citation":"The attraction paradigm. Academic Press. Riferimento generale per il rapporto fra somiglianza e attrazione, non un’origine unica del termine “affinity bias”.","url":"https://www.ncbi.nlm.nih.gov/nlmcatalog/1304120"}],"authors":["Donn Byrne"],"referenceOrigin":"Inquadramento bibliografico aggiunto all’atlante; non implica una precedente approvazione della scheda.","image":"assets/definitivi/affinity-original.png","thumb":"assets/definitivi/affinity-thumb.webp","sourceName":"82359.png","variants":[],"closing":"Anteprima sorprendentemente familiare del prossimo libro.","approvalBatch":3,"seriesNumber":29,"original":"assets/definitivi/affinity-original.png","section":"Bias cognitivi","topic":"Relazione"},{"id":"gamblers-fallacy","name":"Fallacia del giocatore","english":"Gambler’s fallacy","animal":"Coccinella","animals":["Coccinella"],"family":"Decisione","slogan":"La relazione sa che il caso non ha memoria. Il limite pensa: stavolta deve andare diversamente.","description":"In una sequenza di eventi indipendenti, i risultati passati possono far sembrare “dovuto” un esito opposto. La previsione viene guidata dall’idea di compensazione anziché dalla struttura delle probabilità.","example":"Dopo una serie di rossi alla roulette, la coccinella sostiene: “Adesso deve uscire nero!”. Una roulette regolare non corregge la sequenza precedente.","question":"Gli eventi sono indipendenti o c’è davvero un meccanismo di compensazione?","status":"definitive","note":"Poster definitivo fornito dall’autore nel terzo gruppo di dieci immagini, 4 ottobre 2026. Abbinamento e slogan trascritti dal poster.","aliases":["roulette","caso","probabilita"],"order":29,"references":[{"label":"Amos Tversky & Daniel Kahneman (1974)","citation":"Judgment under Uncertainty: Heuristics and Biases. Science, 185, 1124–1131.","url":"https://doi.org/10.1126/science.185.4157.1124"}],"authors":["Amos Tversky","Daniel Kahneman"],"referenceOrigin":"Inquadramento bibliografico aggiunto all’atlante; non implica una precedente approvazione della scheda.","image":"assets/definitivi/gamblers-fallacy-original.png","thumb":"assets/definitivi/gamblers-fallacy-thumb.webp","sourceName":"82825.png","variants":[],"closing":"Anteprima statisticamente fiduciosa del prossimo libro.","approvalBatch":3,"seriesNumber":30,"original":"assets/definitivi/gamblers-fallacy-original.png","section":"Bias cognitivi","topic":"Decisione"},{"id":"hostile-attribution","name":"Bias di attribuzione ostile","english":"Hostile attribution bias","animal":"Panda","animals":["Panda"],"family":"Relazione","slogan":"La relazione prova a capire l’intenzione. Il limite pensa subito: l’ha fatto apposta.","description":"Un comportamento ambiguo viene interpretato come intenzionalmente ostile. La lettura dell’intenzione può così orientare una risposta conflittuale prima di chiarire l’episodio.","example":"Il panda viene urtato in piazza e conclude che sia stato fatto apposta, senza chiedere che cosa sia accaduto.","question":"Quali altre intenzioni o circostanze potrebbero spiegare questo gesto?","status":"definitive","note":"Poster definitivo fornito dall’autore nel quarto gruppo di dieci immagini, 4 ottobre 2026. Abbinamento e slogan trascritti dal poster.","aliases":[],"order":30,"references":[{"label":"Kenneth A. Dodge (1980)","citation":"Social cognition and children’s aggressive behavior. Child Development, 51(1), 162–170.","url":"https://scholars.duke.edu/publication/658267"}],"authors":["Kenneth A. Dodge"],"referenceOrigin":"Inquadramento bibliografico aggiunto all’atlante; non implica una precedente approvazione della scheda.","image":"assets/definitivi/hostile-attribution-original.png","thumb":"assets/definitivi/hostile-attribution-thumb.webp","sourceName":"84867.png","variants":[],"closing":"Anteprima sospettosamente personale del prossimo libro.","approvalBatch":4,"seriesNumber":31,"original":"assets/definitivi/hostile-attribution-original.png","section":"Bias cognitivi","topic":"Relazione"},{"id":"attentional-bias","name":"Bias attentivo","english":"Attentional bias","animal":"Pipistrello","animals":["Pipistrello"],"family":"Informazione","description":"L’attenzione può concentrarsi su alcuni stimoli e lasciare in secondo piano informazioni concorrenti. Nella scena del poster, ciò che coinvolge il personaggio cattura lo sguardo e rende meno accessibile il messaggio di chi gli parla.","example":"Il pipistrello è assorbito dal videogioco, mentre la madre cerca di richiamarne l’attenzione. Le enormi orecchie non garantiscono che il messaggio venga davvero ascoltato.","question":"Quale informazione sto lasciando fuori mentre la mia attenzione è concentrata altrove?","authors":["Steven Yantis","John Jonides"],"references":[{"label":"Steven Yantis & John Jonides (1984)","citation":"Abrupt visual onsets and selective attention: Evidence from visual search. Journal of Experimental Psychology: Human Perception and Performance, 10(5), 601–621.","url":"https://doi.org/10.1037/0096-1523.10.5.601"}],"referenceOrigin":"Inquadramento bibliografico aggiunto all’atlante sulla cattura dell’attenzione; il riferimento accompagna la metafora del videogioco.","aliases":["attenzione","cattura attentiva","videogioco","orecchie"],"variants":[],"status":"definitive","note":"Poster definitivo fornito dall’autore nel quarto gruppo di dieci immagini, 4 ottobre 2026. Abbinamento e slogan trascritti dal poster.","slogan":"La relazione prova a distribuire l’attenzione. Il limite la lascia catturare da ciò che per lui conta di più.","closing":"Anteprima selettivamente sintonizzata del prossimo libro.","approvalBatch":4,"seriesNumber":32,"sourceName":"84956.png","image":"assets/definitivi/attentional-bias-original.png","original":"assets/definitivi/attentional-bias-original.png","thumb":"assets/definitivi/attentional-bias-thumb.webp","order":31,"section":"Bias cognitivi","topic":"Informazione"},{"id":"planning-fallacy","name":"Fallacia della pianificazione","english":"Planning fallacy","animal":"Pinguino","animals":["Pinguino"],"family":"Decisione","description":"Possiamo sottostimare il tempo necessario per completare un compito, concentrandoci sul piano ideale più che sulla durata di esperienze simili. L’ottimismo della previsione resiste anche quando in passato le attività hanno richiesto più tempo.","example":"Il pinguino prevede di finire in pochi minuti, ma l’orologio segna già le 02:17 e sul tavolo restano bozze, revisioni e appunti.","question":"Quanto hanno richiesto attività simili, comprese revisioni e imprevisti?","authors":["Roger Buehler","Dale Griffin","Michael Ross"],"references":[{"label":"Roger Buehler, Dale Griffin & Michael Ross (1994)","citation":"Exploring the “planning fallacy”: Why people underestimate their task completion times. Journal of Personality and Social Psychology, 67(3), 366–381.","url":"https://doi.org/10.1037/0022-3514.67.3.366"}],"referenceOrigin":"Inquadramento bibliografico aggiunto all’atlante; non implica una precedente approvazione della scheda.","aliases":["pianificazione","tempo","cinque minuti","pinguini"],"variants":[],"status":"definitive","note":"Poster definitivo fornito dall’autore nel quarto gruppo di dieci immagini, 4 ottobre 2026. Abbinamento e slogan trascritti dal poster.","slogan":"La relazione considera anche il tempo che serve davvero. Il limite pensa sempre: ci metto cinque minuti.","closing":"Anteprima prevedibilmente in ritardo del prossimo libro.","approvalBatch":4,"seriesNumber":33,"sourceName":"84988.png","image":"assets/definitivi/planning-fallacy-original.png","original":"assets/definitivi/planning-fallacy-original.png","thumb":"assets/definitivi/planning-fallacy-thumb.webp","order":32,"section":"Bias cognitivi","topic":"Decisione"},{"id":"prototype","name":"Euristica del prototipo","english":"Prototype heuristic","animal":"Ornitorinco · Orso","animals":["Ornitorinco","Orso"],"family":"Informazione","slogan":"La relazione riconosce che una categoria può avere molte forme. Il limite pensa: se non assomiglia al modello, allora non ne fa parte.","description":"Un esemplare tipico può diventare il modello con cui riconosciamo una categoria. Il rischio è confondere la somiglianza al prototipo con i criteri effettivi di appartenenza.","example":"All’ingresso del club dei mammiferi, l’orso dubita dell’ornitorinco perché ha il becco. L’aspetto insolito oscura la sua appartenenza alla categoria.","question":"Sto valutando i criteri o la somiglianza a un’immagine tipica?","status":"definitive","note":"Poster definitivo fornito dall’autore nel quarto gruppo di dieci immagini, 4 ottobre 2026. Abbinamento e slogan trascritti dal poster.","aliases":["rappresentatività","mammiferi"],"order":33,"references":[{"label":"Eleanor Rosch (1975)","citation":"Cognitive representations of semantic categories. Journal of Experimental Psychology: General, 104(3), 192–233.","url":"https://doi.org/10.1037/0096-3445.104.3.192"}],"authors":["Eleanor Rosch"],"referenceOrigin":"Inquadramento bibliografico aggiunto all’atlante; non implica una precedente approvazione della scheda.","image":"assets/definitivi/prototype-original.png","thumb":"assets/definitivi/prototype-thumb.webp","sourceName":"84995.png","variants":[],"closing":"Anteprima difficilmente classificabile del prossimo libro.","approvalBatch":4,"seriesNumber":34,"original":"assets/definitivi/prototype-original.png","section":"Bias cognitivi","topic":"Informazione"},{"id":"salience","name":"Bias di salienza","english":"Salience bias","animal":"Falena","animals":["Falena"],"family":"Informazione","slogan":"La relazione distingue ciò che attira da ciò che conta. Il limite dà più peso a ciò che spicca.","description":"Un elemento vistoso può dominare l’attenzione e pesare eccessivamente nel giudizio. Ciò che emerge con forza non coincide necessariamente con ciò che è più pertinente.","example":"La falena è attratta dalla luce intensa della lanterna, mentre gli elementi meno appariscenti restano sullo sfondo.","question":"Quanto pesa questa informazione perché è rilevante, e quanto perché è vistosa?","status":"definitive","note":"Poster definitivo fornito dall’autore nel quarto gruppo di dieci immagini, 4 ottobre 2026. Abbinamento e slogan trascritti dal poster.","aliases":["farfalla","attenzione"],"order":34,"references":[{"label":"Amos Tversky & Daniel Kahneman (1974)","citation":"Judgment under Uncertainty: Heuristics and Biases. Science, 185, 1124–1131.","url":"https://doi.org/10.1126/science.185.4157.1124"}],"authors":["Amos Tversky","Daniel Kahneman"],"referenceOrigin":"Inquadramento bibliografico aggiunto all’atlante; non implica una precedente approvazione della scheda.","image":"assets/definitivi/salience-original.png","thumb":"assets/definitivi/salience-thumb.webp","sourceName":"85083.png","variants":[],"closing":"Anteprima irresistibilmente luminosa del prossimo libro.","approvalBatch":4,"seriesNumber":35,"original":"assets/definitivi/salience-original.png","section":"Bias cognitivi","topic":"Informazione"},{"id":"bandwagon","name":"Effetto carrozzone","english":"Bandwagon effect","animal":"Pecore","animals":["Pecore"],"family":"Relazione","description":"La popolarità di una scelta può aumentare la propensione ad adottarla. La diffusione diventa una ragione per seguirla e può prendere il posto di una valutazione delle informazioni pertinenti.","example":"Il gregge prende la stessa direzione seguendo il cartello “Tutti qua”, senza riesaminare dove conduca il percorso.","question":"Quali ragioni sostengono questa scelta, oltre al fatto che molti la stanno facendo?","authors":["Harvey Leibenstein"],"references":[{"label":"Harvey Leibenstein (1950)","citation":"Bandwagon, Snob, and Veblen Effects in the Theory of Consumers’ Demand. The Quarterly Journal of Economics, 64(2), 183–207.","url":"https://doi.org/10.2307/1882692"}],"referenceOrigin":"Inquadramento bibliografico aggiunto all’atlante: Leibenstein studia il bandwagon nella domanda dei consumatori; il gregge ne offre una metafora divulgativa.","aliases":["gregge","pecora","conformismo","carro del vincitore","popolarita"],"variants":[],"status":"definitive","note":"Poster definitivo fornito dall’autore nel quarto gruppo di dieci immagini, 4 ottobre 2026. Abbinamento e slogan trascritti dal poster.","slogan":"La relazione valuta anche ciò che fanno gli altri. Il limite pensa: se ci vanno tutti, sarà la strada giusta.","closing":"Anteprima coralmente conformista del prossimo libro.","approvalBatch":4,"seriesNumber":36,"sourceName":"85107.png","image":"assets/definitivi/bandwagon-original.png","original":"assets/definitivi/bandwagon-original.png","thumb":"assets/definitivi/bandwagon-thumb.webp","order":35,"section":"Bias cognitivi","topic":"Relazione"},{"id":"ulterior-motives","name":"Sospetto di secondi fini","english":"Suspicion of ulterior motives","animal":"Maialino","animals":["Maialino"],"family":"Relazione","slogan":"La relazione ascolta ciò che l’altro dice. Il limite pensa: sì, ma cosa ci guadagna?","description":"Il sospetto di una motivazione nascosta cambia la lettura di un gesto e induce a cercare spiegazioni alternative. Può favorire un esame più attento, ma diventa una chiusura quando il secondo fine è dato per certo senza riscontri.","example":"La volpe offre aiuto; il maialino guarda il regalo e si chiede subito che cosa la volpe voglia ottenere.","question":"Ho elementi per questo sospetto oppure sto trasformando una possibilità in certezza?","status":"definitive","note":"Poster definitivo fornito dall’autore nel quarto gruppo di dieci immagini, 4 ottobre 2026. Abbinamento e slogan trascritti dal poster. Nello sviluppo sono stati richiamati anche Fein & Hilton (1994) e Kramer (1994); le rispettive voci bibliografiche complete restano da recuperare.","aliases":["secondi fini","sospetto"],"order":36,"references":[{"label":"Steven Fein, James L. Hilton & Dale T. Miller (1990)","citation":"Suspicion of ulterior motivation and the correspondence bias. Journal of Personality and Social Psychology, 58(5), 753–764.","url":"https://pubmed.ncbi.nlm.nih.gov/2348368/"}],"authors":["Steven Fein","James L. Hilton","Dale T. Miller"],"referenceOrigin":"Fein, Hilton & Miller (1990) era già associato al maialino nello sviluppo della serie.","image":"assets/definitivi/ulterior-motives-original.png","thumb":"assets/definitivi/ulterior-motives-thumb.webp","sourceName":"85413.png","variants":[],"closing":"Anteprima sospettosamente interessata del prossimo libro.","approvalBatch":4,"seriesNumber":37,"original":"assets/definitivi/ulterior-motives-original.png","section":"Bias cognitivi","topic":"Relazione"},{"id":"ambiguity","name":"Avversione all’ambiguità","english":"Ambiguity aversion / Ellsberg paradox","animal":"Pappagallo","animals":["Pappagallo"],"family":"Decisione","slogan":"La relazione sa stare anche nell’incertezza. Il limite sceglie ciò che conosce perché ciò che non sa lo spaventa.","description":"Possiamo preferire una scelta con probabilità note a una con probabilità sconosciute. Il paradosso di Ellsberg rende visibile la differenza fra rischio misurabile e ambiguità.","example":"Il pappagallo guarda due urne: una mostra probabilità note, l’altra un punto interrogativo. La familiarità può pesare più delle opportunità ancora da valutare.","question":"Che cosa so realmente delle due opzioni, e che cosa manca?","status":"definitive","note":"Poster definitivo fornito dall’autore nel quarto gruppo di dieci immagini, 4 ottobre 2026. Abbinamento e slogan trascritti dal poster.","aliases":["ellsberg","incertezza","ambiguita"],"order":37,"references":[{"label":"Daniel Ellsberg (1961)","citation":"Risk, Ambiguity, and the Savage Axioms. The Quarterly Journal of Economics, 75(4), 643–669.","url":"https://doi.org/10.2307/1884324"}],"authors":["Daniel Ellsberg"],"referenceOrigin":"Inquadramento bibliografico aggiunto all’atlante; non implica una precedente approvazione della scheda.","image":"assets/definitivi/ambiguity-original.png","thumb":"assets/definitivi/ambiguity-thumb.webp","sourceName":"85451.png","variants":[],"closing":"Anteprima prudentemente incerta del prossimo libro.","approvalBatch":4,"seriesNumber":38,"original":"assets/definitivi/ambiguity-original.png","section":"Bias cognitivi","topic":"Decisione"},{"id":"truth-bias","name":"Bias di veridicità","english":"Truth bias","animal":"Coccodrillo","animals":["Coccodrillo"],"family":"Informazione","slogan":"La relazione distingue l’emozione dalla verità. Il limite vede le lacrime e crede alla storia.","description":"Tendiamo a prendere per vere le comunicazioni altrui in assenza di motivi che attivino il dubbio. Un racconto emotivamente convincente può rafforzare questa fiducia: la sincerità percepita, però, non verifica i fatti.","example":"Una persona racconta un episodio con forte commozione. Il coinvolgimento fa sembrare la storia più credibile, anche prima di riscontri indipendenti.","question":"Quali elementi confermano il racconto, oltre all’emozione che suscita?","status":"definitive","note":"Poster definitivo fornito dall’autore nel quarto gruppo di dieci immagini, 4 ottobre 2026. Abbinamento e slogan trascritti dal poster. Le lacrime di coccodrillo sono una metafora narrativa: l’emozione non prova né la verità né la menzogna.","aliases":["truth default","verità","Levine"],"order":38,"references":[{"label":"Timothy R. Levine (2014)","citation":"Truth-Default Theory (TDT): A Theory of Human Deception and Deception Detection. Journal of Language and Social Psychology, 33(4), 378–392.","url":"https://doi.org/10.1177/0261927X14535916"}],"authors":["Timothy R. Levine"],"referenceOrigin":"Inquadramento bibliografico aggiunto all’atlante; non implica una precedente approvazione della scheda.","image":"assets/definitivi/truth-bias-original.png","thumb":"assets/definitivi/truth-bias-thumb.webp","sourceName":"86153.png","variants":[],"closing":"Anteprima commoventemente credibile del prossimo libro.","approvalBatch":4,"seriesNumber":39,"original":"assets/definitivi/truth-bias-original.png","section":"Bias cognitivi","topic":"Informazione"},{"id":"normalcy-bias","name":"Bias della normalità","english":"Normalcy bias","animal":"Bradipo","animals":["Bradipo"],"family":"Decisione","slogan":"La relazione riconosce quando ciò che accade non è più normale. Il limite pensa: finora non è successo niente, quindi andrà bene anche stavolta.","description":"L’aspettativa che la vita continui come sempre può portare a sottovalutare la probabilità o la gravità di una discontinuità. Il problema emerge quando i segnali nuovi vengono letti con il metro della routine.","example":"Arriva un’allerta maltempo, ma il bradipo resta in poltrona: “È solo un po’ di pioggia, succede sempre”. Il comportamento non si aggiorna alla nuova situazione.","question":"Che cosa è cambiato rispetto alle volte precedenti?","status":"definitive","note":"Poster definitivo fornito dall’autore nel quarto gruppo di dieci immagini, 4 ottobre 2026. Abbinamento e slogan trascritti dal poster. Nello sviluppo sono stati richiamati anche Drabek (1986) e Yamori (2009); le rispettive voci bibliografiche complete restano da recuperare.","aliases":[],"order":39,"references":[{"label":"Haim Omer & Nahman Alon (1994)","citation":"The continuity principle: A unified approach to disaster and trauma. American Journal of Community Psychology, 22, 273–287.","url":"https://doi.org/10.1007/BF02506866"}],"authors":["Haim Omer","Nahman Alon"],"referenceOrigin":"Omer & Alon (1994) era già richiamato nello sviluppo della serie; qui è collegato alla fonte.","image":"assets/definitivi/normalcy-bias-original.png","thumb":"assets/definitivi/normalcy-bias-thumb.webp","sourceName":"86154.png","variants":[],"closing":"Anteprima tranquillamente sottovalutata del prossimo libro.","approvalBatch":4,"seriesNumber":40,"original":"assets/definitivi/normalcy-bias-original.png","section":"Bias cognitivi","topic":"Decisione"},{"id":"contrast","name":"Effetto contrasto","english":"Contrast effect","animal":"Elefante · Serpente · Formica · Uccellino","animals":["Elefante","Serpente","Formica","Uccellino"],"family":"Decisione","slogan":"La relazione guarda la misura reale. Il limite decide se è grande o piccolo in base a ciò che mette accanto.","description":"Il termine di confronto influenza la valutazione di un oggetto o di una prestazione. Lo stesso elemento può sembrare grande o piccolo quando cambia ciò che lo circonda.","example":"Il serpente appare enorme vicino alla formica e modesto vicino all’elefante. La sua misura non cambia: cambia il confronto.","question":"Qual è il termine di confronto, e quanto è adatto?","status":"definitive","note":"Poster definitivo fornito dall’autore nel quinto gruppo di dieci immagini, 4 ottobre 2026. Abbinamento e slogan trascritti dal poster.","aliases":[],"order":40,"references":[{"label":"Harry Helson (1964)","citation":"Adaptation-level theory: An experimental and systematic approach to behavior. Harper & Row. Riferimento generale per il ruolo del contesto e del livello di confronto.","url":"https://books.google.com/books?id=wLR9AAAAMAAJ"}],"authors":["Harry Helson"],"referenceOrigin":"Inquadramento bibliografico aggiunto all’atlante; non implica una precedente approvazione della scheda.","image":"assets/definitivi/contrast-original.png","thumb":"assets/definitivi/contrast-thumb.webp","sourceName":"86275.png","variants":[],"closing":"Anteprima sproporzionatamente comparativa del prossimo libro.","approvalBatch":5,"seriesNumber":41,"original":"assets/definitivi/contrast-original.png","section":"Bias cognitivi","topic":"Decisione"},{"id":"dunning-kruger","name":"Effetto Dunning–Kruger","english":"Dunning–Kruger effect","animal":"Stambecco","animals":["Stambecco"],"family":"Identità","description":"In alcuni compiti, la difficoltà di riconoscere i propri errori può accompagnarsi a una sovrastima della prestazione. Le conoscenze necessarie per rispondere bene aiutano anche a valutare quanto si è preparati.","example":"Il giovane stambecco mostra il diploma “Corso intensivo – 2 settimane” e afferma di aver capito tutto, mentre gli altri studiano la mappa della montagna.","question":"Quali prove concrete mi aiutano a riconoscere ciò che ancora non so?","authors":["Justin Kruger","David Dunning"],"references":[{"label":"Justin Kruger & David Dunning (1999)","citation":"Unskilled and unaware of it: How difficulties in recognizing one’s own incompetence lead to inflated self-assessments. Journal of Personality and Social Psychology, 77(6), 1121–1134.","url":"https://doi.org/10.1037/0022-3514.77.6.1121"}],"referenceOrigin":"Inquadramento bibliografico aggiunto all’atlante; non implica una precedente approvazione della scheda.","aliases":["competenza","metacognizione","sovrastima","stambecco giovane"],"variants":[],"status":"definitive","note":"Poster definitivo fornito dall’autore nel quinto gruppo di dieci immagini, 4 ottobre 2026. Abbinamento e slogan trascritti dal poster.","slogan":"La relazione riconosce anche ciò che ancora non sa. Il limite sa così poco da non vedere quanto gli manca.","closing":"Anteprima prematuramente competente del prossimo libro.","approvalBatch":5,"seriesNumber":42,"sourceName":"86286.png","image":"assets/definitivi/dunning-kruger-original.png","original":"assets/definitivi/dunning-kruger-original.png","thumb":"assets/definitivi/dunning-kruger-thumb.webp","order":41,"section":"Bias cognitivi","topic":"Identità"},{"id":"lollapalooza","name":"Effetto Lollapalooza","english":"Lollapalooza effect","animal":"Cane · Pecore · Gufo · Pavone · Asino","animals":["Cane","Pecore","Gufo","Pavone","Asino"],"family":"Relazione","slogan":"La relazione riconosce le singole pressioni. Il limite cede quando tutte spingono nella stessa direzione.","description":"La scena mette insieme più spinte: prova sociale, autorità, affinità, scarsità, valorizzazione dell’ego e impegno già preso. È una metafora della loro possibile convergenza, non un’unica misura psicologica.","example":"Il cane è circondato da cartelli: “Lo fanno tutti”, “Scelta approvata dagli esperti”, “Ultimi 2 posti”, “Ormai hai iniziato”. Ogni cartello restringe un po’ lo spazio di valutazione.","question":"Quali pressioni sto sommando nella stessa decisione?","status":"definitive","note":"Poster definitivo fornito dall’autore nel quinto gruppo di dieci immagini, 4 ottobre 2026. Abbinamento e slogan trascritti dal poster. L’espressione divulgativa di Charlie Munger descrive la convergenza di più pressioni sulla stessa decisione.","aliases":["munger","scarsita","social proof","authority bias"],"order":42,"references":[{"label":"Charlie Munger · Poor Charlie’s Almanack","citation":"Poor Charlie’s Almanack: The Essential Wit and Wisdom of Charles T. Munger. A cura di Peter D. Kaufman. Stripe Press.","url":"https://www.stripe.press/poor-charlies-almanack"}],"authors":["Charlie Munger"],"referenceOrigin":"Inquadramento bibliografico aggiunto all’atlante; non implica una precedente approvazione della scheda.","image":"assets/definitivi/lollapalooza-original.png","thumb":"assets/definitivi/lollapalooza-thumb.webp","sourceName":"86288.png","variants":[],"closing":"Anteprima cumulativamente persuasiva del prossimo libro.","approvalBatch":5,"seriesNumber":43,"original":"assets/definitivi/lollapalooza-original.png","section":"Bias cognitivi","topic":"Relazione"},{"id":"twaddle-tendency","name":"Prolissità improduttiva","english":"Twaddle tendency","animal":"Ape","animals":["Ape"],"family":"Relazione","description":"La parola può continuare a occupare spazio anche quando non aggiunge informazioni utili. Nell’etichetta divulgativa di Munger, il parlare fine a se stesso disperde attenzione e tempo durante un lavoro che richiede chiarezza.","example":"L’ape prosegue con “In pratica”, “Come dicevo” e “Quindi”, mentre il gufo e la volpe aspettano un contributo concreto alla discussione.","question":"La prossima frase aggiunge un’informazione utile o prolunga soltanto il mio intervento?","authors":["Charlie Munger"],"references":[{"label":"Charlie Munger · Poor Charlie’s Almanack","citation":"Poor Charlie’s Almanack: The Essential Wit and Wisdom of Charles T. Munger. A cura di Peter D. Kaufman. Stripe Press.","url":"https://www.stripe.press/poor-charlies-almanack"}],"referenceOrigin":"Autore di riferimento recuperato dalle scelte della serie; voce bibliografica completata nell’atlante.","aliases":["prolissita","chiacchiere","silenzio","verbosita","parlare"],"variants":[],"status":"definitive","note":"Poster definitivo fornito dall’autore nel quinto gruppo di dieci immagini, 4 ottobre 2026. Abbinamento e slogan trascritti dal poster. Etichetta divulgativa di Charlie Munger per la prolissità improduttiva.","slogan":"La relazione sa anche quando fermarsi. Il limite riempie il silenzio anche quando non ha nulla da aggiungere.","closing":"Anteprima inutilmente prolissa del prossimo libro.","approvalBatch":5,"seriesNumber":44,"sourceName":"86290.png","image":"assets/definitivi/twaddle-tendency-original.png","original":"assets/definitivi/twaddle-tendency-original.png","thumb":"assets/definitivi/twaddle-tendency-thumb.webp","order":43,"section":"Bias cognitivi","topic":"Relazione"},{"id":"dissonance","name":"Dissonanza cognitiva","english":"Cognitive dissonance","animal":"Procione","animals":["Procione"],"family":"Identità","slogan":"La relazione tollera la distanza tra ciò che pensa e ciò che accade. Il limite la riduce scegliendo la spiegazione più facile da sopportare.","description":"Una discrepanza fra convinzioni, comportamento ed esperienza può creare tensione. Possiamo affrontarla rivedendo ciò che pensiamo oppure costruendo giustificazioni che mantengono intatta la nostra immagine.","example":"Il procione riceve 4/10. Può attribuirlo soltanto al professore oppure rivedere metodo, studio e pianificazione.","question":"Quale cambiamento nei fatti eviterei scegliendo questa spiegazione?","status":"definitive","note":"Poster definitivo fornito dall’autore nel quinto gruppo di dieci immagini, 4 ottobre 2026. Abbinamento e slogan trascritti dal poster. Scheda dedicata al processo psicologico della dissonanza cognitiva.","aliases":[],"order":44,"references":[{"label":"Leon Festinger (1957)","citation":"A Theory of Cognitive Dissonance. Stanford University Press.","url":"https://www.sup.org/books/sociology/theory-cognitive-dissonance"}],"authors":["Leon Festinger"],"referenceOrigin":"Inquadramento bibliografico aggiunto all’atlante; non implica una precedente approvazione della scheda.","image":"assets/definitivi/dissonance-original.png","thumb":"assets/definitivi/dissonance-thumb.webp","sourceName":"86316.png","variants":[],"closing":"Anteprima inutilmente coerente del prossimo libro.","approvalBatch":5,"seriesNumber":45,"original":"assets/definitivi/dissonance-original.png","section":"Bias cognitivi","topic":"Identità"},{"id":"noise","name":"Rumore nel giudizio","english":"Noise","animal":"Capibara","animals":["Capibara"],"family":"Decisione","description":"Quando lo stesso caso dovrebbe ricevere valutazioni coerenti, giudizi molto diversi segnalano una variabilità indesiderata. Confrontare i criteri e rendere espliciti i passaggi della valutazione aiuta a riconoscere questo rumore.","example":"Tre capibara valutano lo stesso “Caso A” assegnando 3/10, 6/10 e 9/10. Le informazioni del caso sono uguali; i giudizi cambiano.","question":"Stiamo applicando gli stessi criteri alle stesse informazioni?","authors":["Daniel Kahneman","Olivier Sibony","Cass R. Sunstein"],"references":[{"label":"Daniel Kahneman, Olivier Sibony & Cass R. Sunstein (2021)","citation":"Noise: A Flaw in Human Judgment. Little, Brown Spark.","url":"https://www.hachettebookgroup.com/titles/daniel-kahneman/noise/9780316451406/"}],"referenceOrigin":"Autore di riferimento recuperato dalle scelte della serie; voce bibliografica completata nell’atlante.","aliases":["rumore","variabilita","giudici","criteri","capibara"],"variants":[],"status":"definitive","note":"Poster definitivo fornito dall’autore nel quinto gruppo di dieci immagini, 4 ottobre 2026. Abbinamento e slogan trascritti dal poster.","slogan":"La relazione prova a rendere coerenti i criteri. Il limite produce giudizi diversi davanti allo stesso caso.","closing":"Anteprima imprevedibilmente variabile del prossimo libro.","approvalBatch":5,"seriesNumber":46,"sourceName":"86367.png","image":"assets/definitivi/noise-original.png","original":"assets/definitivi/noise-original.png","thumb":"assets/definitivi/noise-thumb.webp","order":45,"section":"Bias cognitivi","topic":"Decisione"},{"id":"occasion-noise","name":"Rumore occasionale","english":"Occasion noise","animal":"Capibara","animals":["Capibara"],"family":"Decisione","description":"Anche una stessa persona può valutare diversamente un caso in occasioni diverse. Stanchezza, umore o altri aspetti del momento possono entrare nel giudizio senza modificare le informazioni da valutare.","example":"Lo stesso capibara assegna 4/10 al “Caso A” il lunedì e 8/10 il venerdì. La scena mostra stanchezza, tensioni personali e un diverso umore.","question":"È cambiato il caso oppure è cambiato il mio stato mentre lo valuto?","authors":["Daniel Kahneman","Olivier Sibony","Cass R. Sunstein"],"references":[{"label":"Daniel Kahneman, Olivier Sibony & Cass R. Sunstein (2021)","citation":"Noise: A Flaw in Human Judgment. Little, Brown Spark.","url":"https://www.hachettebookgroup.com/titles/daniel-kahneman/noise/9780316451406/"}],"referenceOrigin":"Autore di riferimento recuperato dalle scelte della serie; voce bibliografica completata nell’atlante.","aliases":["rumore occasionale","stanchezza","umore","lunedi","venerdi","nervosismo"],"variants":[],"status":"definitive","note":"Poster definitivo fornito dall’autore nel quinto gruppo di dieci immagini, 4 ottobre 2026. Abbinamento e slogan trascritti dal poster.","slogan":"La relazione riconosce che anche lo stato personale può alterare il giudizio. Il limite valuta lo stesso caso in modo diverso quando cambiano stanchezza, nervosismo e umore.","closing":"Anteprima imprevedibilmente oscillante del prossimo libro.","approvalBatch":5,"seriesNumber":47,"sourceName":"86366.png","image":"assets/definitivi/occasion-noise-original.png","original":"assets/definitivi/occasion-noise-original.png","thumb":"assets/definitivi/occasion-noise-thumb.webp","order":46,"section":"Bias cognitivi","topic":"Decisione"},{"id":"wysiati","name":"Ciò che vedi è tutto ciò che c’è","english":"WYSIATI · What You See Is All There Is","animal":"Cavallo","animals":["Cavallo"],"family":"Informazione","description":"Possiamo costruire una storia convincente usando le informazioni disponibili e trascurare ciò che manca. La coerenza della storia aumenta la sicurezza del giudizio anche quando gli elementi considerati sono incompleti.","example":"Il cavallo con i paraocchi dichiara “Caso chiuso”, concentrato su impronta, testimone e sospettato. Intorno restano alibi, un secondo testimone, un video e dati mancanti.","question":"Quali informazioni potrebbero cambiare la storia che mi sto raccontando?","authors":["Daniel Kahneman"],"references":[{"label":"Daniel Kahneman · Thinking, Fast and Slow","citation":"Thinking, Fast and Slow. Farrar, Straus and Giroux. Riferimento per WYSIATI e il ruolo delle informazioni disponibili nel giudizio.","url":"https://us.macmillan.com/books/9780374533557/thinkingfastandslow/"}],"referenceOrigin":"Autore di riferimento recuperato dalle scelte della serie; voce bibliografica completata nell’atlante.","aliases":["paraocchi","informazioni mancanti","caso chiuso","what you see is all there is"],"variants":[],"status":"definitive","note":"Poster definitivo fornito dall’autore nel quinto gruppo di dieci immagini, 4 ottobre 2026. Abbinamento e slogan trascritti dal poster.","slogan":"La relazione si chiede anche cosa manca. Il limite pensa che ciò che vede sia tutto ciò che c’è.","closing":"Anteprima convincentemente incompleta del prossimo libro.","approvalBatch":5,"seriesNumber":48,"sourceName":"86449.png","image":"assets/definitivi/wysiati-original.png","original":"assets/definitivi/wysiati-original.png","thumb":"assets/definitivi/wysiati-thumb.webp","order":47,"section":"Bias cognitivi","topic":"Informazione"},{"id":"ethnocentrism","name":"Etnocentrismo","english":"Ethnocentrism","animal":"Lupi","animals":["Lupo"],"family":"Relazione","slogan":"La relazione prova a comprendere l’altro nei suoi riferimenti. Il limite misura ciò che è diverso con le regole di casa propria.","description":"Il proprio gruppo diventa il metro con cui valutare usi, valori e comportamenti altrui. Ciò che è familiare appare naturale; la differenza rischia di essere letta come errore.","example":"Nel poster i lupi ululano per salutare e condividono il cibo. Gli altri animali hanno rituali diversi: non comprenderli non li rende sbagliati.","question":"Sto cercando di capire le regole dell’altro o gli sto applicando le mie?","status":"definitive","note":"Poster definitivo fornito dall’autore nel quinto gruppo di dieci immagini, 4 ottobre 2026. Abbinamento e slogan trascritti dal poster.","aliases":["cultura","ethnocentrism","lupi","ululare"],"order":48,"references":[{"label":"William Graham Sumner (1906)","citation":"Folkways. Riferimento storico per il concetto di etnocentrismo.","url":"https://www.gutenberg.org/ebooks/24253"}],"authors":["William Graham Sumner"],"referenceOrigin":"Inquadramento bibliografico aggiunto all’atlante; non implica una precedente approvazione della scheda.","image":"assets/definitivi/ethnocentrism-original.png","thumb":"assets/definitivi/ethnocentrism-thumb.webp","sourceName":"86464.png","variants":[],"closing":"Anteprima perfettamente normale… secondo noi.","approvalBatch":5,"seriesNumber":49,"original":"assets/definitivi/ethnocentrism-original.png","section":"Bias cognitivi","topic":"Relazione"},{"id":"risk-compensation","name":"Compensazione del rischio","english":"Risk compensation · Peltzman effect","animal":"Cinghiale","animals":["Cinghiale"],"family":"Decisione","description":"Una maggiore sicurezza percepita può accompagnarsi a comportamenti più rischiosi, compensando una parte della protezione. Il riferimento di Peltzman riguarda la risposta dei guidatori alle misure di sicurezza automobilistica; il poster usa una scena sportiva.","example":"Il cinghiale affronta in mountain bike una discesa estrema e pensa “Tanto sono protetto”. Casco e protezioni diventano una ragione per aumentare il rischio.","question":"Sto usando la protezione per ridurre il rischio o per giustificare una condotta più rischiosa?","authors":["Sam Peltzman"],"references":[{"label":"Sam Peltzman (1975)","citation":"The Effects of Automobile Safety Regulation. Journal of Political Economy, 83(4), 677–725.","url":"https://doi.org/10.1086/260352"}],"referenceOrigin":"Autore di riferimento recuperato dalle scelte della serie; voce bibliografica completata nell’atlante.","aliases":["peltzman","sicurezza","protezione","mountain bike","casco"],"variants":[],"status":"definitive","note":"Poster definitivo fornito dall’autore nel quinto gruppo di dieci immagini, 4 ottobre 2026. Abbinamento e slogan trascritti dal poster.","slogan":"La relazione distingue sicurezza da invulnerabilità. Il limite pensa: se sono protetto, posso rischiare di più.","closing":"Anteprima prudentemente spericolata del prossimo libro.","approvalBatch":5,"seriesNumber":50,"sourceName":"86465.png","image":"assets/definitivi/risk-compensation-original.png","original":"assets/definitivi/risk-compensation-original.png","thumb":"assets/definitivi/risk-compensation-thumb.webp","order":49,"section":"Bias cognitivi","topic":"Decisione"},{"id":"naive-realism","name":"Realismo ingenuo","english":"Naïve realism","animal":"Ramirezi","animals":["Ramirezi"],"family":"Relazione","slogan":"La relazione riconosce che anche il proprio sguardo è un punto di vista. Il limite pensa: io vedo la realtà com’è; se tu la vedi diversamente, sbagli tu.","closing":"Anteprima oggettivamente soggettiva del prossimo libro.","description":"Possiamo considerare il nostro punto di vista come una lettura diretta e oggettiva della realtà. Quando gli altri dissentono, il disaccordo rischia di essere attribuito alla loro ignoranza o parzialità, senza esaminare come anche la nostra interpretazione dipenda da esperienze e prospettive.","example":"I due Ramirezi si fronteggiano: uno afferma “Io vedo le cose come stanno” e l’altro risponde “Anch’io”. Ciascuno riconosce il proprio sguardo come quello che rappresenta la realtà.","question":"Quale parte di ciò che considero evidente dipende dal punto da cui sto guardando?","aliases":["naive realism","oggettivita","punto di vista","ciclidi","prospettiva"],"authors":["Lee Ross","Andrew Ward"],"references":[{"label":"Lee Ross & Andrew Ward (1996)","citation":"Naive realism in everyday life: Implications for social conflict and misunderstanding. Capitolo di riferimento sul realismo ingenuo nei conflitti sociali.","url":"https://web.mit.edu/curhan/www/docs/Articles/15341_Readings/Negotiation_and_Conflict_Management/Ross_Ward_Naive_Realism.pdf"}],"referenceOrigin":"Inquadramento bibliografico aggiunto all’atlante; non implica una precedente approvazione della scheda.","status":"definitive","note":"Poster definitivo fornito dall’autore nel sesto gruppo di allegati, 4 ottobre 2026. Abbinamento e slogan trascritti dal poster.","approvalBatch":6,"seriesNumber":51,"order":50,"sourceName":"86477.png","image":"assets/definitivi/naive-realism-original.png","original":"assets/definitivi/naive-realism-original.png","thumb":"assets/definitivi/naive-realism-thumb.webp","variants":[],"section":"Bias cognitivi","topic":"Relazione"},{"id":"explanatory-depth","name":"Illusione della profondità esplicativa","english":"Illusion of explanatory depth","animal":"Pesce rosso","animals":["Pesce rosso"],"family":"Informazione","slogan":"La relazione prova a scendere davvero in profondità. Il limite pensa di conoscere l’abisso perché ne ha visto la superficie.","closing":"Anteprima apparentemente profondissima del prossimo libro.","description":"La familiarità con un fenomeno può farci credere di comprenderne il funzionamento più a fondo di quanto sappiamo spiegare. Provare a descrivere il meccanismo passo per passo può far emergere lacune che prima non riconoscevamo.","example":"Il pesce rosso, equipaggiato da subacqueo, si muove in una boccia che sembra un oceano profondo. La scena distingue l’impressione di conoscere un abisso dall’esplorarne davvero i passaggi e i limiti.","question":"Riesco a spiegare come funziona, passo per passo, senza saltare ciò che non conosco?","aliases":["ioed","comprensione","profondita","boccia","abisso","goldfish"],"authors":["Leonid Rozenblit","Frank Keil"],"references":[{"label":"Leonid Rozenblit & Frank Keil (2002)","citation":"The misunderstood limits of folk science: An illusion of explanatory depth. Cognitive Science, 26(5), 521–562.","url":"https://doi.org/10.1207/s15516709cog2605_1"}],"referenceOrigin":"Rozenblit & Keil (2002) già richiamati nello sviluppo del poster; voce bibliografica completata nell’atlante.","status":"definitive","note":"Poster definitivo fornito dall’autore nel sesto gruppo di allegati, 4 ottobre 2026. Abbinamento e slogan trascritti dal poster.","approvalBatch":6,"seriesNumber":52,"order":51,"sourceName":"86572.png","image":"assets/definitivi/explanatory-depth-original.png","original":"assets/definitivi/explanatory-depth-original.png","thumb":"assets/definitivi/explanatory-depth-thumb.webp","variants":[],"section":"Bias cognitivi","topic":"Informazione"},{"id":"uncertainty-intolerance","name":"Intolleranza dell’incertezza","english":"Uncertainty avoidance","animal":"Ippopotamo","animals":["Ippopotamo"],"family":"Decisione","slogan":"La relazione avanza anche senza garanzie. Il limite, davanti all’incertezza, si blocca.","closing":"Anteprima cautamente immobilizzata del prossimo libro.","description":"La difficoltà a tollerare ciò che non si può prevedere può portare a cercare garanzie complete, rimandare una decisione o restare immobili. Nella metafora del poster, l’incertezza diventa una ragione per non fare il passo successivo.","example":"L’ippopotamo resta fermo fra i cartelli “Limite” e “Relazione”. Il blocco del personaggio evoca il freezing richiesto nello sviluppo della scena, attraverso una rappresentazione simbolica.","question":"Quale passo posso compiere usando le informazioni disponibili, pur senza una garanzia completa?","aliases":["intolerance of uncertainty","uncertainty avoidance","freezing","incertezza","blocco","immobilita","garanzie"],"authors":["K. Buhr","M. J. Dugas"],"references":[{"label":"K. Buhr & M. J. Dugas (2002)","citation":"The Intolerance of Uncertainty Scale: Psychometric properties of the English version. Behaviour Research and Therapy, 40(8), 931–945.","url":"https://doi.org/10.1016/S0005-7967(01)00092-4"}],"referenceOrigin":"Inquadramento bibliografico aggiunto all’atlante per l’intolleranza individuale dell’incertezza rappresentata dalla scena.","status":"definitive","note":"Poster definitivo fornito dall’autore nel sesto gruppo di allegati, 4 ottobre 2026. Abbinamento e slogan trascritti dal poster. Il sottotitolo originale “Uncertainty avoidance” è conservato. Questa scheda riguarda il processo individuale evocato dal poster; la dimensione culturale di Hofstede appartiene a un diverso livello di analisi.","approvalBatch":6,"seriesNumber":53,"order":52,"sourceName":"86479.png","image":"assets/definitivi/uncertainty-intolerance-original.png","original":"assets/definitivi/uncertainty-intolerance-original.png","thumb":"assets/definitivi/uncertainty-intolerance-thumb.webp","variants":[],"section":"Bias cognitivi","topic":"Decisione"},{"id":"fight-response","name":"Risposta di attacco","english":"Fight response","animal":"Toro","animals":["Toro"],"slogan":"La relazione prova a leggere anche il contesto. Il limite, quando sente pericolo, passa subito al contrattacco.","closing":"Anteprima istintivamente combattiva del prossimo libro.","description":"Di fronte a una minaccia percepita, la risposta di attacco mobilita il corpo verso il confronto e la difesa attiva. È una risposta che può attivarsi automaticamente; il contesto aiuta a distinguere la protezione da un contrattacco immediato.","example":"Il toro carica a testa bassa accanto al cartello “Pericolo”. La scena mette in relazione l’impulso a reagire con la possibilità di leggere ciò che sta accadendo.","question":"Quale pericolo sto percependo e che cosa mi dice il contesto?","aliases":["fight","attacco","contrattacco","difesa attiva","bull","pericolo"],"authors":["Kasia Kozlowska","Peter Walker","Loyola McLean","Pascal Carrive"],"references":[{"label":"Kasia Kozlowska, Peter Walker, Loyola McLean & Pascal Carrive (2015)","citation":"Fear and the Defense Cascade: Clinical Implications and Management. Harvard Review of Psychiatry, 23(4), 263–287.","url":"https://doi.org/10.1097/HRP.0000000000000065"}],"referenceOrigin":"Inquadramento bibliografico aggiunto all’atlante per la risposta di difesa rappresentata dal poster.","family":"Risposte di difesa","status":"definitive","note":"Poster definitivo fornito dall’autore nel settimo gruppo di allegati, 4 ottobre 2026. Abbinamento e slogan trascritti dal poster. La scheda appartiene alle risposte di difesa della serie.","approvalBatch":7,"seriesNumber":54,"order":53,"sourceName":"86633.png","image":"assets/definitivi/fight-response-original.png","original":"assets/definitivi/fight-response-original.png","thumb":"assets/definitivi/fight-response-thumb.webp","variants":[],"section":"Gestione dello Stress","topic":"Risposte di difesa"},{"id":"flight-response","name":"Risposta di fuga","english":"Flight response","animal":"Gazzella","animals":["Gazzella"],"slogan":"La relazione cerca distanza per ritrovare orientamento. Il limite, quando sente pericolo, pensa che salvarsi significhi sparire.","closing":"Anteprima istintivamente sfuggente del prossimo libro.","description":"La risposta di fuga mobilita il corpo per allontanarsi dalla minaccia percepita. È una forma di difesa attiva che cerca distanza dal pericolo; il poster mette a confronto questa distanza con l’idea di dover sparire.","example":"La gazzella corre mentre un leone la insegue. Il movimento rende visibile la ricerca di distanza, che nello slogan può diventare uno spazio per ritrovare orientamento.","question":"Che cosa rappresenta per me la distanza in questa scena?","aliases":["flight","fuga","antilope","gazelle","distanza","allontanamento"],"authors":["Kasia Kozlowska","Peter Walker","Loyola McLean","Pascal Carrive"],"references":[{"label":"Kasia Kozlowska, Peter Walker, Loyola McLean & Pascal Carrive (2015)","citation":"Fear and the Defense Cascade: Clinical Implications and Management. Harvard Review of Psychiatry, 23(4), 263–287.","url":"https://doi.org/10.1097/HRP.0000000000000065"}],"referenceOrigin":"Inquadramento bibliografico aggiunto all’atlante per la risposta di difesa rappresentata dal poster.","family":"Risposte di difesa","status":"definitive","note":"Poster definitivo fornito dall’autore nel settimo gruppo di allegati, 4 ottobre 2026. Abbinamento e slogan trascritti dal poster. La scheda appartiene alle risposte di difesa della serie.","approvalBatch":7,"seriesNumber":55,"order":54,"sourceName":"86634.png","image":"assets/definitivi/flight-response-original.png","original":"assets/definitivi/flight-response-original.png","thumb":"assets/definitivi/flight-response-thumb.webp","variants":[],"section":"Gestione dello Stress","topic":"Risposte di difesa"},{"id":"freeze-response","name":"Risposta di blocco","english":"Freeze response","animal":"Cerbiatto","animals":["Cerbiatto"],"slogan":"La relazione accetta che fermarsi possa essere un passaggio. Il limite, quando sente pericolo, si immobilizza per non essere colpito.","closing":"Anteprima istintivamente immobilizzata del prossimo libro.","description":"Il freezing è un arresto del movimento di fronte alla minaccia, mentre l’allerta può restare alta. Nella cascata difensiva, l’azione di attacco o fuga resta sospesa: questo blocco è distinto dal collasso.","example":"Il cerbiatto resta rannicchiato e immobile nel bosco, con un lupo sullo sfondo. La scena rappresenta la sospensione dell’azione, senza confonderla con il cedimento del corpo.","question":"Che cosa cambia fra fermarsi per un passaggio e restare bloccati?","aliases":["freeze","freezing","blocco","immobilita","cervo","deer"],"authors":["Kasia Kozlowska","Peter Walker","Loyola McLean","Pascal Carrive"],"references":[{"label":"Kasia Kozlowska, Peter Walker, Loyola McLean & Pascal Carrive (2015)","citation":"Fear and the Defense Cascade: Clinical Implications and Management. Harvard Review of Psychiatry, 23(4), 263–287.","url":"https://doi.org/10.1097/HRP.0000000000000065"}],"referenceOrigin":"Inquadramento bibliografico aggiunto all’atlante per la risposta di difesa rappresentata dal poster.","family":"Risposte di difesa","status":"definitive","note":"Poster definitivo fornito dall’autore nel settimo gruppo di allegati, 4 ottobre 2026. Abbinamento e slogan trascritti dal poster. La scheda appartiene alle risposte di difesa della serie.","approvalBatch":7,"seriesNumber":56,"order":55,"sourceName":"86635.png","image":"assets/definitivi/freeze-response-original.png","original":"assets/definitivi/freeze-response-original.png","thumb":"assets/definitivi/freeze-response-thumb.webp","variants":[],"section":"Gestione dello Stress","topic":"Risposte di difesa"},{"id":"flop-faint-response","name":"Risposta di collasso","english":"Flop / Faint response","animal":"Capra","animals":["Capra"],"slogan":"La relazione prova a restare presente anche nella resa. Il limite, quando il carico è troppo, spegne il corpo per sopravvivere.","closing":"Anteprima istintivamente collassata del prossimo libro.","description":"La cascata difensiva descrive anche l’immobilità collassata di fronte a una minaccia percepita come inescapabile, quando la difesa attiva non riesce. Il titolo Flop / Faint riunisce nella metafora del poster il cedimento e lo svenimento; i due termini non sono equivalenti.","example":"La capra è rovesciata a terra accanto al cartello “Pericolo / Sovraccarico”. Il cedimento rende visibile il tema della resa e del carico eccessivo.","question":"Quale differenza mostra il poster fra il blocco e il collasso?","aliases":["flop","faint","collasso","svenimento","collapsed immobility","sovraccarico","goat"],"authors":["Kasia Kozlowska","Peter Walker","Loyola McLean","Pascal Carrive"],"references":[{"label":"Kasia Kozlowska, Peter Walker, Loyola McLean & Pascal Carrive (2015)","citation":"Fear and the Defense Cascade: Clinical Implications and Management. Harvard Review of Psychiatry, 23(4), 263–287.","url":"https://doi.org/10.1097/HRP.0000000000000065"}],"referenceOrigin":"Inquadramento bibliografico aggiunto all’atlante per la risposta di difesa rappresentata dal poster.","family":"Risposte di difesa","status":"definitive","note":"Poster definitivo fornito dall’autore nel settimo gruppo di allegati, 4 ottobre 2026. Abbinamento e slogan trascritti dal poster. La scheda appartiene alle risposte di difesa della serie. “Spegnere il corpo” è la formulazione simbolica dello slogan; la scena animale non identifica una diagnosi o un meccanismo fisiologico specifico.","approvalBatch":7,"seriesNumber":57,"order":56,"sourceName":"86639.png","image":"assets/definitivi/flop-faint-response-original.png","original":"assets/definitivi/flop-faint-response-original.png","thumb":"assets/definitivi/flop-faint-response-thumb.webp","variants":[],"section":"Gestione dello Stress","topic":"Risposte di difesa"},{"id":"fawn-response","name":"Risposta compiacente","english":"Fawn response","animal":"Cane","animals":["Cane"],"slogan":"La relazione riconosce il bisogno di proteggersi senza compiacere tutto e tutti. Il limite, quando sente pericolo, cerca sicurezza adattandosi all’altro.","closing":"Anteprima istintivamente accomodante del prossimo libro.","description":"Nel modello clinico di Pete Walker, fawn indica la ricerca di sicurezza attraverso l’accondiscendenza verso l’altro, anche rinunciando ai propri bisogni e confini. La risposta compiacente può diventare una modalità abituale di protezione nelle relazioni percepite come minacciose.","example":"Il cane offre un mazzo di fiori al lupo sotto il cartello “Pericolo”. La scena contrappone il desiderio di placare l’altro al bisogno di proteggersi mantenendo i propri confini.","question":"Quali bisogni e confini del personaggio restano visibili nella relazione?","aliases":["fawn","compiacenza","compiacente","accondiscendenza","people pleasing","appeasement","accomodante"],"authors":["Pete Walker"],"references":[{"label":"Pete Walker (2003)","citation":"Codependency, Trauma and the Fawn Response. The East Bay Therapist, gennaio–febbraio 2003.","url":"https://www.pete-walker.com/codependencyFawnResponse.htm"}],"referenceOrigin":"Inquadramento bibliografico aggiunto all’atlante: fawn è qui riferito al modello clinico descritto da Pete Walker.","family":"Risposte di difesa","status":"definitive","note":"Poster definitivo fornito dall’autore nel settimo gruppo di allegati, 4 ottobre 2026. Abbinamento e slogan trascritti dal poster. La scheda appartiene alle risposte di difesa della serie. Il riferimento a fawn segue la terminologia del modello clinico di Walker.","approvalBatch":7,"seriesNumber":58,"order":57,"sourceName":"86640.png","image":"assets/definitivi/fawn-response-original.png","original":"assets/definitivi/fawn-response-original.png","thumb":"assets/definitivi/fawn-response-thumb.webp","variants":[],"section":"Gestione dello Stress","topic":"Risposte di difesa"},{"id":"emotion-joy","name":"Gioia","english":"Joy","animal":"Cane","animals":["Cane"],"slogan":"La relazione lascia che la gioia si mostri. Il limite, a volte, dimentica che anche stare bene richiede spazio.","closing":"Anteprima istintivamente luminosa del prossimo libro.","description":"La gioia esprime un’esperienza piacevole e può manifestarsi nel sorriso, nel movimento e nel desiderio di condivisione. Il poster invita a lasciare spazio anche a ciò che fa stare bene.","example":"Il cane corre verso chi guarda, con la bocca aperta in un sorriso e una zampa sollevata. La luce calda del tramonto accompagna la sua esuberanza.","question":"Quanto spazio lascio alla possibilità di mostrare che sto bene?","aliases":["felicita","allegria","happiness","sorriso","benessere"],"authors":["Paul Ekman","Wallace V. Friesen"],"references":[{"label":"Paul Ekman & Wallace V. Friesen (1971)","citation":"Constants across cultures in the face and emotion. Journal of Personality and Social Psychology, 17(2), 124–129.","url":"https://doi.org/10.1037/h0030377"}],"referenceOrigin":"Inquadramento bibliografico aggiunto all’atlante per il modello classico delle espressioni emotive. La lettura della scena è editoriale.","family":"Emozioni","status":"definitive","note":"Poster definitivo fornito dall’autore nell’ottavo gruppo di allegati, 4 ottobre 2026. Abbinamento, slogan e chiusura trascritti dal poster. La scheda appartiene alla famiglia Emozioni della serie.","approvalBatch":8,"seriesNumber":59,"order":58,"sourceName":"86745.png","image":"assets/definitivi/emotion-joy-original.png","original":"assets/definitivi/emotion-joy-original.png","thumb":"assets/definitivi/emotion-joy-thumb.webp","variants":[],"section":"Mente, esperienza e relazione","topic":"Emozioni e processi affettivi"},{"id":"emotion-sadness","name":"Tristezza","english":"Sadness","animal":"Koala","animals":["Koala"],"slogan":"La relazione sa restare accanto anche a ciò che fa male. Il limite vorrebbe che la tristezza passasse prima di averla ascoltata.","closing":"Anteprima istintivamente malinconica del prossimo libro.","description":"La tristezza può accompagnare una perdita, una mancanza o una delusione. Il poster richiama il tempo necessario per riconoscere ciò che fa male e la possibilità di trovare vicinanza nella relazione.","example":"Il koala stringe una fotografia fra le zampe, seduto vicino a un albero. Lo sguardo abbassato e le lacrime raccontano la mancanza, mentre il tramonto mantiene un’atmosfera calda.","question":"Che cosa sta chiedendo ascolto dietro questa tristezza?","aliases":["malinconia","perdita","mancanza","fotografia","lacrime","sad"],"authors":["Paul Ekman","Wallace V. Friesen"],"references":[{"label":"Paul Ekman & Wallace V. Friesen (1971)","citation":"Constants across cultures in the face and emotion. Journal of Personality and Social Psychology, 17(2), 124–129.","url":"https://doi.org/10.1037/h0030377"}],"referenceOrigin":"Inquadramento bibliografico aggiunto all’atlante per il modello classico delle espressioni emotive. La lettura della scena è editoriale.","family":"Emozioni","status":"definitive","note":"Poster definitivo fornito dall’autore nell’ottavo gruppo di allegati, 4 ottobre 2026. Abbinamento, slogan e chiusura trascritti dal poster. La scheda appartiene alla famiglia Emozioni della serie.","approvalBatch":8,"seriesNumber":60,"order":59,"sourceName":"86744.png","image":"assets/definitivi/emotion-sadness-original.png","original":"assets/definitivi/emotion-sadness-original.png","thumb":"assets/definitivi/emotion-sadness-thumb.webp","variants":[],"section":"Mente, esperienza e relazione","topic":"Emozioni e processi affettivi"},{"id":"emotion-fear","name":"Paura","english":"Fear","animal":"Lepre","animals":["Lepre"],"slogan":"La relazione ascolta ciò che la paura segnala. Il limite, quando sente pericolo, lascia che la paura occupi tutto il campo.","closing":"Anteprima istintivamente allarmata del prossimo libro.","description":"La paura segnala una minaccia percepita e orienta l’attenzione verso il pericolo. Nel poster, lo spazio occupato dall’allarme si confronta con la possibilità di ascoltarne il significato.","example":"La lepre resta fra le erbe con occhi spalancati, orecchie sollevate e bocca tesa. L’ambiente al crepuscolo rende visibile l’incertezza su ciò che potrebbe accadere.","question":"Che cosa segnala la paura e quali altri elementi del contesto riesco ancora a vedere?","aliases":["allarme","pericolo","timore","hare","coniglio"],"authors":["Paul Ekman","Wallace V. Friesen"],"references":[{"label":"Paul Ekman & Wallace V. Friesen (1971)","citation":"Constants across cultures in the face and emotion. Journal of Personality and Social Psychology, 17(2), 124–129.","url":"https://doi.org/10.1037/h0030377"}],"referenceOrigin":"Inquadramento bibliografico aggiunto all’atlante per il modello classico delle espressioni emotive. La lettura della scena è editoriale.","family":"Emozioni","status":"definitive","note":"Poster definitivo fornito dall’autore nell’ottavo gruppo di allegati, 4 ottobre 2026. Abbinamento, slogan e chiusura trascritti dal poster. La scheda appartiene alla famiglia Emozioni della serie.","approvalBatch":8,"seriesNumber":61,"order":60,"sourceName":"86743.png","image":"assets/definitivi/emotion-fear-original.png","original":"assets/definitivi/emotion-fear-original.png","thumb":"assets/definitivi/emotion-fear-thumb.webp","variants":[],"section":"Mente, esperienza e relazione","topic":"Emozioni e processi affettivi"},{"id":"emotion-anger","name":"Rabbia","english":"Anger","animal":"Tasso","animals":["Tasso"],"slogan":"La relazione ascolta ciò che la rabbia segnala. Il limite lascia che sia la rabbia a decidere cosa fare.","closing":"Anteprima istintivamente infuocata del prossimo libro.","description":"La rabbia può emergere quando qualcosa ostacola un obiettivo o viene vissuto come un torto. Il poster distingue l’ascolto del suo segnale dall’impulso di lasciarle decidere l’azione.","example":"Il tasso mostra sopracciglia contratte, muso teso e postura protesa in avanti, in mezzo a cassette rovesciate e ortaggi sparsi. L’espressione dà forma all’intensità della rabbia.","question":"Che cosa sta segnalando la rabbia, prima che diventi un’azione?","aliases":["ira","collera","frustrazione","badger","infuocata"],"authors":["Paul Ekman","Wallace V. Friesen"],"references":[{"label":"Paul Ekman & Wallace V. Friesen (1971)","citation":"Constants across cultures in the face and emotion. Journal of Personality and Social Psychology, 17(2), 124–129.","url":"https://doi.org/10.1037/h0030377"}],"referenceOrigin":"Inquadramento bibliografico aggiunto all’atlante per il modello classico delle espressioni emotive. La lettura della scena è editoriale.","family":"Emozioni","status":"definitive","note":"Poster definitivo fornito dall’autore nell’ottavo gruppo di allegati, 4 ottobre 2026. Abbinamento, slogan e chiusura trascritti dal poster. La scheda appartiene alla famiglia Emozioni della serie.","approvalBatch":8,"seriesNumber":62,"order":61,"sourceName":"86742.png","image":"assets/definitivi/emotion-anger-original.png","original":"assets/definitivi/emotion-anger-original.png","thumb":"assets/definitivi/emotion-anger-thumb.webp","variants":[],"section":"Mente, esperienza e relazione","topic":"Emozioni e processi affettivi"},{"id":"emotion-surprise","name":"Sorpresa","english":"Surprise","animal":"Tarsio","animals":["Tarsio"],"slogan":"La relazione si apre a ciò che interrompe l’atteso. Il limite, per un istante, sospende ciò che credeva di sapere.","closing":"Anteprima inaspettatamente sospesa del prossimo libro.","description":"La sorpresa nasce da qualcosa che interrompe l’atteso. Può aprire un momento di sospensione e orientare l’attenzione verso il nuovo; il significato dell’evento dipende da ciò che segue.","example":"Il tarsio spalanca gli occhi e la bocca davanti a uno scrigno da cui escono farfalle luminose. Il gesto sospeso delle mani rende visibile l’incontro con l’inaspettato.","question":"Che cosa posso osservare di nuovo quando le mie aspettative si interrompono?","aliases":["inaspettato","stupore","meraviglia","tarsier","scrigno","atteso"],"authors":["Paul Ekman","Wallace V. Friesen"],"references":[{"label":"Paul Ekman & Wallace V. Friesen (1971)","citation":"Constants across cultures in the face and emotion. Journal of Personality and Social Psychology, 17(2), 124–129.","url":"https://doi.org/10.1037/h0030377"}],"referenceOrigin":"Inquadramento bibliografico aggiunto all’atlante per il modello classico delle espressioni emotive. La lettura della scena è editoriale.","family":"Emozioni","status":"definitive","note":"Poster definitivo fornito dall’autore nell’ottavo gruppo di allegati, 4 ottobre 2026. Abbinamento, slogan e chiusura trascritti dal poster. La scheda appartiene alla famiglia Emozioni della serie.","approvalBatch":8,"seriesNumber":63,"order":62,"sourceName":"86741.png","image":"assets/definitivi/emotion-surprise-original.png","original":"assets/definitivi/emotion-surprise-original.png","thumb":"assets/definitivi/emotion-surprise-thumb.webp","variants":[],"section":"Mente, esperienza e relazione","topic":"Emozioni e processi affettivi"},{"id":"emotion-disgust","name":"Disgusto","english":"Disgust","animal":"Lama","animals":["Lama"],"slogan":"La relazione ascolta anche ciò che respinge. Il limite sente disgusto e vuole subito allontanarsi.","closing":"Anteprima istintivamente schifata del prossimo libro.","description":"Il disgusto esprime repulsione e può orientare all’allontanamento da ciò che viene percepito come sgradevole. Il poster invita a riconoscere questa reazione e ciò che la suscita.","example":"Il lama arriccia il muso e ritrae le zampe davanti a un piatto dall’aspetto sgradevole, circondato da mosche. La scena dà una forma immediata alla repulsione.","question":"Che cosa mi respinge in questa scena e quale significato gli attribuisco?","aliases":["repulsione","rifiuto","schifo","llama","sgradevole"],"authors":["Paul Ekman","Wallace V. Friesen"],"references":[{"label":"Paul Ekman & Wallace V. Friesen (1971)","citation":"Constants across cultures in the face and emotion. Journal of Personality and Social Psychology, 17(2), 124–129.","url":"https://doi.org/10.1037/h0030377"}],"referenceOrigin":"Inquadramento bibliografico aggiunto all’atlante per il modello classico delle espressioni emotive. La lettura della scena è editoriale.","family":"Emozioni","status":"definitive","note":"Poster definitivo fornito dall’autore nell’ottavo gruppo di allegati, 4 ottobre 2026. Abbinamento, slogan e chiusura trascritti dal poster. La scheda appartiene alla famiglia Emozioni della serie.","approvalBatch":8,"seriesNumber":64,"order":63,"sourceName":"86740.png","image":"assets/definitivi/emotion-disgust-original.png","original":"assets/definitivi/emotion-disgust-original.png","thumb":"assets/definitivi/emotion-disgust-thumb.webp","variants":[],"section":"Mente, esperienza e relazione","topic":"Emozioni e processi affettivi"},{"id":"emotional-contagion","name":"Contagio emotivo","english":"Emotional contagion","animal":"Cane · Koala · Lepre · Tasso · Tarsio · Lama","animals":["Cane","Koala","Lepre","Tasso","Tarsio","Lama"],"slogan":"La relazione lascia circolare ciò che sentiamo. Il limite dimentica che nessuna emozione resta soltanto di chi la prova.","closing":"Anteprima emotivamente contagiosa del prossimo libro.","description":"Nelle interazioni, espressioni, gesti e tono di voce possono influenzare gli stati emotivi di chi è presente, anche senza una scelta consapevole. Il contagio emotivo è il processo relazionale che connette le emozioni rappresentate nella serie.","example":"I sei animali delle emozioni compaiono insieme: il cane gioioso, il koala triste, la lepre impaurita, il tasso arrabbiato, il tarsio sorpreso e il lama disgustato. Le scie luminose rendono visibili gli scambi fra i personaggi.","question":"In che modo ciò che provo influenza il clima della relazione, e come quel clima influenza me?","aliases":["emotional contagion","contagio","clima emotivo","intelligenza sociale","sei emozioni","gioia","tristezza","paura","rabbia","sorpresa","disgusto"],"authors":["Daniel Goleman","Elaine Hatfield","John T. Cacioppo","Richard L. Rapson"],"references":[{"label":"Daniel Goleman (edizione italiana 2007)","citation":"Intelligenza sociale. Rizzoli / BUR.","url":"https://www.rizzolilibri.it/libri/intelligenza-sociale/"},{"label":"Elaine Hatfield, John T. Cacioppo & Richard L. Rapson (1993)","citation":"Emotional Contagion. Current Directions in Psychological Science, 2(3), 96–100.","url":"https://doi.org/10.1111/1467-8721.ep10770953"}],"referenceOrigin":"Daniel Goleman, Intelligenza sociale, già richiamato nello sviluppo del poster; riferimento a Hatfield, Cacioppo e Rapson completato come integrazione bibliografica nell’atlante.","family":"Emozioni","status":"definitive","note":"Poster definitivo fornito dall’autore nell’ottavo gruppo di allegati, 4 ottobre 2026. Abbinamento, slogan e chiusura trascritti dal poster. La scheda appartiene alla famiglia Emozioni della serie. Il contagio emotivo collega le sei emozioni della serie ed è presentato come processo relazionale, non come settima emozione primaria.","approvalBatch":8,"seriesNumber":65,"order":64,"sourceName":"86746.png","image":"assets/definitivi/emotional-contagion-original.png","original":"assets/definitivi/emotional-contagion-original.png","thumb":"assets/definitivi/emotional-contagion-thumb.webp","variants":[],"section":"Mente, esperienza e relazione","topic":"Emozioni e processi affettivi"},{"id":"mental-social-representation","name":"Rappresentazione mentale e sociale","english":"Mental and social representation","animal":"Delfino","animals":["Delfino"],"family":"Relazione","slogan":"La relazione costruisce significati condivisi. Il limite confonde ciò che pensa con ciò che tutti pensano.","closing":"Anteprima mentalmente costruita e socialmente condivisa del prossimo libro.","description":"Una rappresentazione mentale è il modo in cui il singolo si raffigura qualcosa, attraverso percezioni, ricordi, conoscenze ed esperienze. Una rappresentazione sociale è un insieme di significati elaborati e condivisi nelle relazioni e nella comunicazione di una comunità. I due livelli si influenzano: la nostra immagine personale utilizza anche significati disponibili nella cultura. I significati condivisi possono variare tra gruppi e persone.","example":"Per chi osserva il delfino emergono ricordi di un tramonto, di un incontro in mare o di un disegno infantile. Nello spazio sociale compaiono parole come intelligenza, libertà, amicizia, gioco, terapia e salvataggio: associazioni culturali che orientano il modo di immaginare l’animale.","question":"Quali significati nascono dalla mia esperienza e quali ho incontrato nelle parole, nelle immagini e nelle relazioni della mia comunità?","status":"definitive","note":"Poster definitivo fornito dall’autore nel nono gruppo di allegati, 4 ottobre 2026. Titolo, abbinamento, slogan e chiusura trascritti dal poster. La scheda confronta il livello individuale e quello sociale della costruzione del significato.","aliases":["rappresentazione mentale","rappresentazione sociale","rappresentazioni sociali","rappresentazioni mentali","immagine personale","significati condivisi","immaginario collettivo","dolphin","comunita","cultura"],"order":65,"seriesNumber":66,"approvalBatch":9,"references":[{"label":"Serge Moscovici (2005)","citation":"Le rappresentazioni sociali. Il Mulino.","url":"https://www.mulino.it/isbn/9788815106780"},{"label":"Philip N. Johnson-Laird (2010)","citation":"Mental models and human reasoning. Proceedings of the National Academy of Sciences, 107(43), 18243–18250.","url":"https://doi.org/10.1073/pnas.1012933107"}],"authors":["Serge Moscovici","Philip N. Johnson-Laird"],"referenceOrigin":"Inquadramento bibliografico aggiunto all’atlante: Moscovici per le rappresentazioni sociali; Johnson-Laird per i modelli mentali, una forma di rappresentazione mentale. La lettura del delfino riprende la distinzione già definita nello sviluppo del poster.","image":"assets/definitivi/mental-social-representation-original.png","original":"assets/definitivi/mental-social-representation-original.png","thumb":"assets/definitivi/mental-social-representation-thumb.webp","sourceName":"86785.png","variants":[],"section":"Mente, esperienza e relazione","topic":"Identità, rappresentazioni e motivazione"},{"id":"stress-management","name":"Gestione dello stress","english":"Stress management","animal":"Scimmia","slogan":"La relazione aiuta a regolare ciò che agita. Il limite, sotto pressione, dimentica perfino di respirare.","closing":"Anteprima ironicamente zen del prossimo libro.","description":"Gestire lo stress significa riconoscere le richieste della situazione e le risorse disponibili, scegliendo come affrontarle. Il coping può intervenire sul problema, sulle emozioni o sui significati. Strategie diverse possono combinarsi e cambiare con il contesto.","example":"La scimmia, seduta in una posa meditativa, introduce il percorso: crea uno spazio per riconoscere la pressione prima di scegliere come rispondere. La scena è una metafora visiva della regolazione.","question":"Che cosa mi sta mettendo sotto pressione e quali risorse posso attivare?","aliases":["stress","regolazione","coping","pressione","zen","meditazione","monkey"],"references":[{"label":"Richard S. Lazarus e Susan Folkman (1984)","citation":"Stress, Appraisal, and Coping. Springer Publishing Company.","url":"https://books.google.com/books/about/Stress_Appraisal_and_Coping.html?id=i-ySQQuUpr8C"}],"animals":["Scimmia"],"family":"Gestione dello Stress","status":"definitive","order":66,"seriesNumber":67,"approvalBatch":10,"note":"Poster definitivo fornito dall’autore nel decimo gruppo di allegati, 5 ottobre 2026. Titolo, animale, slogan e chiusura trascritti dall’originale. Fa parte dello spazio Gestione dello Stress richiesto dall’autore.","authors":["Richard S. Lazarus","Susan Folkman"],"referenceOrigin":"Inquadramento bibliografico aggiunto all’atlante: il modello di Lazarus e Folkman collega valutazione della situazione, risorse e coping. Il poster è l’introduzione editoriale allo spazio Gestione dello Stress; la posa meditativa resta una metafora della serie.","image":"assets/definitivi/stress-management-original.png","original":"assets/definitivi/stress-management-original.png","thumb":"assets/definitivi/stress-management-thumb.webp","sourceName":"86822.png","variants":[],"section":"Gestione dello Stress","bookTitle":"Psiche & Thanatos","bookUrl":"https://www.amazon.it/dp/B0DVCC1HY6","topic":"Il tema"},{"id":"problem-focused-coping","name":"Coping centrato sul problema","english":"Problem-focused coping","animal":"Lontra","slogan":"La relazione cerca ciò che può essere modificato. Il limite si sente sopraffatto dal problema intero.","closing":"Anteprima operativamente adattiva del prossimo libro.","description":"Il coping centrato sul problema mira a modificare la situazione che genera stress. Comprende raccogliere informazioni, individuare parti su cui si può intervenire e agire. Può affiancarsi alla regolazione emotiva: conta quanto il problema è effettivamente modificabile.","example":"La lontra osserva i tronchi che ostacolano il torrente, individua un ramo su cui intervenire e comincia a spostarlo. Affronta una parte concreta dell’ostacolo.","question":"Quale parte di questo problema posso modificare con un primo intervento concreto?","aliases":["problem focused","problema","azione","modificare","otter"],"references":[{"label":"Richard S. Lazarus e Susan Folkman (1984)","citation":"Stress, Appraisal, and Coping. Springer Publishing Company.","url":"https://books.google.com/books/about/Stress_Appraisal_and_Coping.html?id=i-ySQQuUpr8C"},{"label":"Susan Folkman, Richard S. Lazarus e colleghi (1986)","citation":"Folkman, S., Lazarus, R. S., Dunkel-Schetter, C., DeLongis, A., e Gruen, R. J. Dynamics of a stressful encounter: cognitive appraisal, coping, and encounter outcomes. Journal of Personality and Social Psychology, 50(5), 992–1003.","url":"https://pubmed.ncbi.nlm.nih.gov/3712234/"}],"animals":["Lontra"],"family":"Gestione dello Stress","status":"definitive","order":67,"seriesNumber":68,"approvalBatch":10,"note":"Poster definitivo fornito dall’autore nel decimo gruppo di allegati, 5 ottobre 2026. Titolo, animale, slogan e chiusura trascritti dall’originale. Fa parte dello spazio Gestione dello Stress richiesto dall’autore.","authors":["Richard S. Lazarus","Susan Folkman"],"referenceOrigin":"Inquadramento bibliografico aggiunto all’atlante: Lazarus e Folkman per il coping centrato sul problema. Titolo, animale, slogan e sequenza operativa provengono dall’originale fornito dall’autore.","image":"assets/definitivi/problem-focused-coping-original.png","original":"assets/definitivi/problem-focused-coping-original.png","thumb":"assets/definitivi/problem-focused-coping-thumb.webp","sourceName":"86999.png","variants":[],"section":"Gestione dello Stress","bookTitle":"Psiche & Thanatos","bookUrl":"https://www.amazon.it/dp/B0DVCC1HY6","topic":"Strategie di coping"},{"id":"planful-problem-solving","name":"Soluzione pianificata del problema","english":"Planful problem solving","animal":"Corvo","slogan":"La relazione organizza le risorse prima di muoversi. Il limite reagisce prima di aver capito dove andare.","closing":"Anteprima strategicamente pianificata del prossimo libro.","description":"La soluzione pianificata del problema combina analisi della situazione, confronto fra alternative e preparazione dell’azione. È una strategia del coping centrato sul problema: definisce un percorso e impiega le risorse disponibili per seguirlo.","example":"Il corvo si ferma davanti al passaggio interrotto, consulta la mappa e valuta più percorsi. La scena organizza tre momenti: osservare, valutare le opzioni, pianificare e agire.","question":"Quali opzioni ho e quali risorse servono per mettere in pratica il piano?","aliases":["planful","problem solving","pianificazione","piano","opzioni","raven","crow"],"references":[{"label":"Richard S. Lazarus e Susan Folkman (1984)","citation":"Stress, Appraisal, and Coping. Springer Publishing Company.","url":"https://books.google.com/books/about/Stress_Appraisal_and_Coping.html?id=i-ySQQuUpr8C"},{"label":"Susan Folkman · Ways of Coping","citation":"Ways of Coping: questionario e scale di coping. Materiale reso disponibile da Susan Folkman attraverso UCSF; include pianificazione, supporto sociale, rivalutazione positiva ed evitamento/fuga.","url":"https://prevention.ucsf.edu/sites/prevention.ucsf.edu/files/uploads/tools/surveys/pdf/Ways%20of%20coping.pdf"}],"animals":["Corvo"],"family":"Gestione dello Stress","status":"definitive","order":68,"seriesNumber":69,"approvalBatch":10,"note":"Poster definitivo fornito dall’autore nel decimo gruppo di allegati, 5 ottobre 2026. Titolo, animale, slogan e chiusura trascritti dall’originale. Fa parte dello spazio Gestione dello Stress richiesto dall’autore.","authors":["Richard S. Lazarus","Susan Folkman"],"referenceOrigin":"Inquadramento bibliografico aggiunto all’atlante: Planful problem-solving è una delle scale del Ways of Coping. È qui presentata come strategia specifica, distinta dal poster generale sul coping centrato sul problema.","image":"assets/definitivi/planful-problem-solving-original.png","original":"assets/definitivi/planful-problem-solving-original.png","thumb":"assets/definitivi/planful-problem-solving-thumb.webp","sourceName":"87001.png","variants":[],"section":"Gestione dello Stress","bookTitle":"Psiche & Thanatos","bookUrl":"https://www.amazon.it/dp/B0DVCC1HY6","topic":"Strategie di coping"},{"id":"seeking-social-support","name":"Ricerca di supporto sociale","english":"Seeking social support","animal":"Formiche","animals":["Formica"],"slogan":"La relazione chiede aiuto quando serve. Il limite confonde l’autonomia con il dover fare tutto da soli.","closing":"Anteprima cooperativamente adattiva del prossimo libro.","description":"Cercare supporto sociale significa coinvolgere altre persone per ottenere ascolto, informazioni o aiuto concreto. Il sostegno può riguardare sia il problema sia il vissuto emotivo. Riconoscere un bisogno permette di condividere risorse e compiti.","example":"Una formica tenta di sostenere un masso troppo pesante; le altre si avvicinano e partecipano allo sforzo. Chiedere aiuto trasforma un peso individuale in un compito condiviso.","question":"Di quale aiuto ho bisogno e a chi posso chiederlo con chiarezza?","aliases":["social support","sostegno sociale","aiuto","cooperazione","formica","ants"],"references":[{"label":"Richard S. Lazarus e Susan Folkman (1984)","citation":"Stress, Appraisal, and Coping. Springer Publishing Company.","url":"https://books.google.com/books/about/Stress_Appraisal_and_Coping.html?id=i-ySQQuUpr8C"},{"label":"Susan Folkman · Ways of Coping","citation":"Ways of Coping: questionario e scale di coping. Materiale reso disponibile da Susan Folkman attraverso UCSF; include pianificazione, supporto sociale, rivalutazione positiva ed evitamento/fuga.","url":"https://prevention.ucsf.edu/sites/prevention.ucsf.edu/files/uploads/tools/surveys/pdf/Ways%20of%20coping.pdf"}],"family":"Gestione dello Stress","status":"definitive","order":69,"seriesNumber":70,"approvalBatch":10,"note":"Poster definitivo fornito dall’autore nel decimo gruppo di allegati, 5 ottobre 2026. Titolo, animale, slogan e chiusura trascritti dall’originale. Fa parte dello spazio Gestione dello Stress richiesto dall’autore.","authors":["Richard S. Lazarus","Susan Folkman"],"referenceOrigin":"Inquadramento bibliografico aggiunto all’atlante: Seeking social support è una delle scale del Ways of Coping e comprende sostegno emotivo, informativo e concreto. Abbinamento e slogan sono trascritti dal poster.","image":"assets/definitivi/seeking-social-support-original.png","original":"assets/definitivi/seeking-social-support-original.png","thumb":"assets/definitivi/seeking-social-support-thumb.webp","sourceName":"87000.png","variants":[],"section":"Gestione dello Stress","bookTitle":"Psiche & Thanatos","bookUrl":"https://www.amazon.it/dp/B0DVCC1HY6","topic":"Strategie di coping"},{"id":"positive-reappraisal","name":"Rivalutazione positiva","english":"Positive reappraisal","animal":"Panda rosso","slogan":"La relazione non cancella ciò che è accaduto: prova a costruirne un significato. Il limite vede soltanto ciò che è stato perso.","closing":"Anteprima costruttivamente reinterpretata del prossimo libro.","description":"La rivalutazione positiva cerca un significato costruttivo nell’esperienza, anche attraverso ciò che si può imparare o riconoscere come importante. Nel poster la perdita viene riconosciuta: la ricerca di un nuovo significato parte da ciò che è accaduto e da ciò che resta.","example":"Il panda rosso trova un albero caduto lungo il percorso e lo utilizza come passaggio. La scena lega il riconoscimento della perdita alla ricerca di un significato e all’uso delle risorse rimaste.","question":"Che cosa resta disponibile e quale significato posso costruire a partire da questa esperienza?","aliases":["positive reappraisal","rivalutazione","significato","reinterpretazione","red panda"],"references":[{"label":"Richard S. Lazarus e Susan Folkman (1984)","citation":"Stress, Appraisal, and Coping. Springer Publishing Company.","url":"https://books.google.com/books/about/Stress_Appraisal_and_Coping.html?id=i-ySQQuUpr8C"},{"label":"Susan Folkman · Ways of Coping","citation":"Ways of Coping: questionario e scale di coping. Materiale reso disponibile da Susan Folkman attraverso UCSF; include pianificazione, supporto sociale, rivalutazione positiva ed evitamento/fuga.","url":"https://prevention.ucsf.edu/sites/prevention.ucsf.edu/files/uploads/tools/surveys/pdf/Ways%20of%20coping.pdf"}],"animals":["Panda rosso"],"family":"Gestione dello Stress","status":"definitive","order":70,"seriesNumber":71,"approvalBatch":10,"note":"Poster definitivo fornito dall’autore nel decimo gruppo di allegati, 5 ottobre 2026. Titolo, animale, slogan e chiusura trascritti dall’originale. Fa parte dello spazio Gestione dello Stress richiesto dall’autore.","authors":["Richard S. Lazarus","Susan Folkman"],"referenceOrigin":"Inquadramento bibliografico aggiunto all’atlante: Positive reappraisal è una delle scale del Ways of Coping. La lettura della perdita e del nuovo passaggio riprende la scena e le parole del poster definitivo.","image":"assets/definitivi/positive-reappraisal-original.png","original":"assets/definitivi/positive-reappraisal-original.png","thumb":"assets/definitivi/positive-reappraisal-thumb.webp","sourceName":"87002.png","variants":[],"section":"Gestione dello Stress","bookTitle":"Psiche & Thanatos","bookUrl":"https://www.amazon.it/dp/B0DVCC1HY6","topic":"Strategie di coping"},{"id":"escape-avoidance","name":"Evitamento / Fuga","english":"Escape–avoidance","animal":"Paguro","slogan":"La relazione può prendere le distanze senza perdere il problema di vista. Il limite si sente meglio finché riesce a non guardarlo.","closing":"Anteprima temporaneamente rassicurante del prossimo libro.","description":"L’evitamento/fuga comprende tentativi di sottrarsi alla situazione stressante o alla sua presenza nella mente. Nel poster il sollievo dipende dal non guardare le richieste rimaste aperte. Prendere una pausa mantenendo il problema presente è diverso dal rimandarne continuamente il confronto.","example":"Il paguro si rifugia nella conchiglia sotto una coperta, circondato da bollette, tasse, lettere e scadenze. Il riparo nasconde le richieste alla vista, mentre continuano a occupare lo spazio intorno a lui.","question":"Sto prendendo una pausa per recuperare risorse oppure sto rinviando il confronto con il problema?","aliases":["escape avoidance","evitamento","fuga","distanziare","bolletta","scadenza","hermit crab"],"references":[{"label":"Richard S. Lazarus e Susan Folkman (1984)","citation":"Stress, Appraisal, and Coping. Springer Publishing Company.","url":"https://books.google.com/books/about/Stress_Appraisal_and_Coping.html?id=i-ySQQuUpr8C"},{"label":"Susan Folkman · Ways of Coping","citation":"Ways of Coping: questionario e scale di coping. Materiale reso disponibile da Susan Folkman attraverso UCSF; include pianificazione, supporto sociale, rivalutazione positiva ed evitamento/fuga.","url":"https://prevention.ucsf.edu/sites/prevention.ucsf.edu/files/uploads/tools/surveys/pdf/Ways%20of%20coping.pdf"}],"animals":["Paguro"],"family":"Gestione dello Stress","status":"definitive","order":71,"seriesNumber":72,"approvalBatch":10,"note":"Poster definitivo fornito dall’autore nel decimo gruppo di allegati, 5 ottobre 2026. Titolo, animale, slogan e chiusura trascritti dall’originale. Fa parte dello spazio Gestione dello Stress richiesto dall’autore.","authors":["Richard S. Lazarus","Susan Folkman"],"referenceOrigin":"Il richiamo a Lazarus e Folkman è presente nel poster originale. I riferimenti bibliografici sono completati nell’atlante attraverso il loro modello e la scala Escape-avoidance del Ways of Coping. La pausa descritta nello slogan è distinta dall’evitamento persistente.","image":"assets/definitivi/escape-avoidance-original.png","original":"assets/definitivi/escape-avoidance-original.png","thumb":"assets/definitivi/escape-avoidance-thumb.webp","sourceName":"86993.png","variants":[],"section":"Gestione dello Stress","bookTitle":"Psiche & Thanatos","bookUrl":"https://www.amazon.it/dp/B0DVCC1HY6","topic":"Strategie di coping"},{"id":"emotion-focused-coping","name":"Coping centrato sull’emozione","english":"Emotion-focused coping","animal":"Orso","slogan":"La relazione non controlla sempre ciò che accade, ma può regolare come lo attraversa. Il limite combatte anche ciò che non può cambiare.","closing":"Anteprima emotivamente adattiva del prossimo libro.","description":"Il coping centrato sull’emozione riguarda il modo di gestire le emozioni legate a una situazione stressante. Nel poster l’orso cerca riparo e recupera risorse mentre il temporale prosegue. Regolazione emotiva e intervento sul problema possono essere usati insieme, secondo il contesto.","example":"L’orso al riparo dalla tempesta si avvolge nella coperta e tiene una bevanda calda. Nella vignetta immaginata cerca invece di combattere il temporale: la scena contrappone il recupero delle risorse a uno sforzo senza presa sulla situazione.","question":"Che cosa posso fare per attraversare questa situazione e recuperare risorse, mentre valuto ciò che è modificabile?","aliases":["emotion focused","emozione","emozioni","attivazione","riparo","bear"],"references":[{"label":"Richard S. Lazarus e Susan Folkman (1984)","citation":"Stress, Appraisal, and Coping. Springer Publishing Company.","url":"https://books.google.com/books/about/Stress_Appraisal_and_Coping.html?id=i-ySQQuUpr8C"},{"label":"Susan Folkman, Richard S. Lazarus e colleghi (1986)","citation":"Folkman, S., Lazarus, R. S., Dunkel-Schetter, C., DeLongis, A., e Gruen, R. J. Dynamics of a stressful encounter: cognitive appraisal, coping, and encounter outcomes. Journal of Personality and Social Psychology, 50(5), 992–1003.","url":"https://pubmed.ncbi.nlm.nih.gov/3712234/"}],"animals":["Orso"],"family":"Gestione dello Stress","status":"definitive","order":72,"seriesNumber":73,"approvalBatch":10,"note":"Poster definitivo fornito dall’autore nel decimo gruppo di allegati, 5 ottobre 2026. Titolo, animale, slogan e chiusura trascritti dall’originale. Fa parte dello spazio Gestione dello Stress richiesto dall’autore.","authors":["Richard S. Lazarus","Susan Folkman"],"referenceOrigin":"Inquadramento bibliografico aggiunto all’atlante: Lazarus e Folkman per il coping centrato sull’emozione. Riparo, regolazione dell’attivazione e recupero delle risorse riprendono la metafora dell’orso nel poster.","image":"assets/definitivi/emotion-focused-coping-original.png","original":"assets/definitivi/emotion-focused-coping-original.png","thumb":"assets/definitivi/emotion-focused-coping-thumb.webp","sourceName":"86992.png","variants":[],"section":"Gestione dello Stress","bookTitle":"Psiche & Thanatos","bookUrl":"https://www.amazon.it/dp/B0DVCC1HY6","topic":"Strategie di coping"},{"id":"overprecision","name":"Eccesso di precisione","english":"Overprecision","animal":"Falco","animals":["Falco"],"family":"Informazione","slogan":"La relazione sa che ogni previsione ha un margine. Il limite mette troppi decimali anche dove servirebbe un ‘circa’.","closing":"Anteprima precisamente troppo sicura del prossimo libro.","description":"Si attribuisce alle proprie stime un grado di certezza superiore a quello giustificato dai dati, usando margini d’incertezza troppo stretti. I decimali del poster rendono visibile questa sicurezza eccessiva. È una forma di overconfidence: riguarda la certezza delle proprie valutazioni; l’overplacement riguarda invece la posizione che ci attribuiamo rispetto agli altri. La precisione numerica può essere appropriata quando è sostenuta da misure affidabili.","example":"Il falco annuncia pioggia alle 15:17 e una distanza di 12,43 km con un margine di ±20 m. Le osservazioni disponibili sostengono invece una previsione di pioggia probabile nel pomeriggio e una distanza di circa 10–15 km. La scena mostra una stima più precisa di quanto consentano le informazioni.","question":"Quale margine d’incertezza giustificano i dati e quanto è affidabile la mia stima?","status":"definitive","note":"Poster definitivo fornito dall’autore nell’undicesimo gruppo di allegati, 8 ottobre 2026. Titolo, abbinamento, slogan e chiusura trascritti dall’originale. L’eccesso di precisione è distinto dall’eccesso di posizionamento.","aliases":["overprecision","eccesso di precisione","overconfidence","troppi decimali","incertezza","previsioni","falcon","calibrazione","margine di errore","sicurezza eccessiva","stima"],"order":73,"seriesNumber":74,"approvalBatch":11,"references":[{"label":"Don A. Moore e Paul J. Healy (2008)","citation":"The trouble with overconfidence. Psychological Review, 115(2), 502–517.","url":"https://doi.org/10.1037/0033-295X.115.2.502"}],"authors":["Don A. Moore","Paul J. Healy"],"referenceOrigin":"Riferimento bibliografico aggiunto all’atlante per inquadrare l’eccesso di precisione e distinguerlo da overestimation e overplacement. L’abbinamento con il falco e la metafora delle previsioni riprendono lo sviluppo del poster; titolo, slogan e chiusura provengono dall’originale definitivo.","image":"assets/definitivi/overprecision-original.png","original":"assets/definitivi/overprecision-original.png","thumb":"assets/definitivi/overprecision-thumb.webp","sourceName":"87100.png","variants":[],"section":"Bias cognitivi","topic":"Informazione"},{"id":"locus-of-control","name":"Locus of control · Interno ed esterno","english":"Locus of control","animal":"Topolini","animals":["Topolino"],"family":"Identità","slogan":"La relazione distingue ciò che dipende da sé da ciò che dipende dal contesto. Il limite si sbilancia: se tutto dipende da me cresce l’ansia; se nulla dipende da me cresce l’impotenza.","closing":"Anteprima ironicamente sbilanciata del prossimo libro.","description":"Il locus of control descrive le aspettative su quanto gli esiti dipendano dalle proprie azioni o da fattori esterni, come fortuna, altre persone e circostanze. L’orientamento interno o esterno va letto rispetto alla situazione, senza considerarlo sempre positivo o negativo. Nel poster sono raffigurati due sbilanciamenti: sentirsi responsabili di tutto oppure percepirsi senza possibilità di incidere. Ansia e impotenza sono evocazioni della scena, non esiti automatici del locus of control.","example":"Il topolino a sinistra accumula studio, lavoro e compiti da controllare, convinto che tutto sia sulle sue spalle. Quello a destra si affida alla fortuna, agli altri e alle circostanze. La scena invita a distinguere il proprio contributo dai fattori sui quali non si può intervenire.","question":"Che cosa può cambiare con le mie azioni e quali fattori del contesto devo riconoscere?","aliases":["locus of control interno","locus of control esterno","controllo interno","controllo esterno","aspettative","fortuna","responsabilità","contesto","topolino","mouse","mice"],"references":[{"label":"Julian B. Rotter (1966)","citation":"Generalized expectancies for internal versus external control of reinforcement. Psychological Monographs: General and Applied, 80(1), 1–28.","url":"https://doi.org/10.1037/h0092976"},{"label":"Julian B. Rotter (1975)","citation":"Some problems and misconceptions related to the construct of internal versus external control of reinforcement. Journal of Consulting and Clinical Psychology, 43(1), 56–67.","url":"https://doi.org/10.1037/h0076301"}],"authors":["Julian B. Rotter"],"referenceOrigin":"Inquadramento bibliografico aggiunto all’atlante: Rotter per le aspettative di controllo interno ed esterno e per i limiti nell’interpretazione del costrutto. Il locus of control è un costrutto psicologico; i due estremi raffigurati e lo slogan restano la metafora editoriale della serie.","status":"definitive","order":74,"seriesNumber":75,"approvalBatch":12,"note":"Poster definitivo fornito dall’autore nel dodicesimo gruppo di allegati, 9 ottobre 2026. Titolo, animali, slogan e chiusura trascritti dall’originale. La scheda presenta il concetto illustrato nel poster.","image":"assets/definitivi/locus-of-control-original.png","original":"assets/definitivi/locus-of-control-original.png","thumb":"assets/definitivi/locus-of-control-thumb.webp","sourceName":"87597.png","variants":[],"section":"Mente, esperienza e relazione","topic":"Identità, rappresentazioni e motivazione"},{"id":"reality-of-reality","name":"La realtà della realtà","english":"The reality of reality","animal":"Topolini","animals":["Topolino"],"family":"Relazione","slogan":"La relazione prova a capire come l’altro costruisce il significato. Il limite crede che la realtà sia una sola: la propria.","closing":"Anteprima ironicamente interpretata del prossimo libro.","description":"Nella distinzione di Watzlawick, la realtà di primo ordine riguarda gli aspetti osservabili e verificabili; quella di secondo ordine i significati e il valore che attribuiamo a ciò che incontriamo. Esperienze, aspettative e comunicazione contribuiscono a costruire queste letture e orientano le nostre risposte. La scena mostra come una situazione condivisa possa essere vissuta come opportunità o minaccia.","example":"I due topolini osservano lo stesso pezzo di formaggio. Per il primo significa finalmente cibo, in una cornice di fiducia e curiosità. Per il secondo, segnato da diffidenza e cautela, può essere una trappola. Il formaggio è condiviso; il significato attribuito e la risposta che ne segue sono diversi.","question":"Quale significato sto attribuendo a questa situazione e quali esperienze possono orientare il punto di vista dell’altro?","aliases":["realtà della realtà","realtà di primo ordine","realtà di secondo ordine","realtà di secondo livello","first-order reality","second-order reality","significato","esperienze","formaggio","topolino","mouse","mice"],"references":[{"label":"Paul Watzlawick (1978)","citation":"La realtà della realtà. Comunicazione, disinformazione, confusione. Astrolabio Ubaldini. Traduzione di Jean Sanders.","url":"https://www.astrolabio-ubaldini.com/libro/125"}],"authors":["Paul Watzlawick"],"referenceOrigin":"Il richiamo a Watzlawick riprende lo sviluppo già definito del poster sul significato e sulla realtà di secondo ordine. L’atlante esplicita il riferimento all’edizione italiana del libro. I topolini davanti allo stesso formaggio sono la metafora originale della serie.","status":"definitive","order":75,"seriesNumber":76,"approvalBatch":12,"note":"Poster definitivo fornito dall’autore nel dodicesimo gruppo di allegati, 9 ottobre 2026. Titolo, animali, slogan e chiusura trascritti dall’originale. La scheda presenta il concetto illustrato nel poster.","image":"assets/definitivi/reality-of-reality-original.png","original":"assets/definitivi/reality-of-reality-original.png","thumb":"assets/definitivi/reality-of-reality-thumb.webp","sourceName":"87598.png","variants":[],"section":"Mente, esperienza e relazione","topic":"Identità, rappresentazioni e motivazione"},{"id":"illusion-of-transparency","name":"Illusione di trasparenza","english":"Illusion of transparency","animal":"Rana","animals":["Rana"],"family":"Relazione","slogan":"La relazione sa che l’altro vede solo una parte di ciò che sentiamo. Il limite pensa che ciò che accade dentro sia evidente anche fuori.","closing":"Anteprima apparentemente trasparente del prossimo libro.","description":"Possiamo sopravvalutare quanto gli altri riescano a cogliere i nostri stati interni, come emozioni, disagio o intenzioni. Partiamo dall’intensità di ciò che viviamo e correggiamo troppo poco questa impressione quando immaginiamo il punto di vista di chi ci osserva. Sentire con forza qualcosa può così farci credere che sia evidente anche all’altro, che dispone soltanto di una parte delle informazioni.","example":"La rana sente il cuore battere e vive una forte tensione durante il colloquio. Nel poster, il corpo trasparente rende visibile al lettore questa esperienza interna. La rana può pensare che l’interlocutore colga tutto ciò che prova; chi le sta davanti vede invece solo alcuni segnali e ascolta ciò che viene comunicato. La trasparenza del corpo è la metafora del bias.","question":"Che cosa ho davvero comunicato all’altro e che cosa sto dando per evidente solo perché lo sento dentro di me?","aliases":["illusion of transparency","illusione di trasparenza","trasparenza","rana di vetro","frog","stati interni","emozioni","leggibilità","prospettiva","colloquio"],"authors":["Thomas Gilovich","Kenneth Savitsky","Victoria Husted Medvec"],"references":[{"label":"Thomas Gilovich, Kenneth Savitsky e Victoria Husted Medvec (1998)","citation":"The illusion of transparency: Biased assessments of others’ ability to read one’s emotional states. Journal of Personality and Social Psychology, 75(2), 332–346.","url":"https://doi.org/10.1037/0022-3514.75.2.332"}],"referenceOrigin":"Inquadramento bibliografico aggiunto all’atlante: Gilovich, Savitsky e Medvec per la tendenza a sovrastimare quanto i propri stati interni siano riconoscibili dagli altri. La rana trasparente e la scena del colloquio sono la metafora editoriale dell’originale.","status":"definitive","order":76,"seriesNumber":77,"approvalBatch":13,"note":"Poster definitivo fornito dall’autore nel tredicesimo gruppo di allegati, 9 ottobre 2026. Titolo, animale, slogan e chiusura trascritti dall’originale. La scheda riguarda la visibilità percepita dei propri stati interni.","image":"assets/definitivi/illusion-of-transparency-original.png","original":"assets/definitivi/illusion-of-transparency-original.png","thumb":"assets/definitivi/illusion-of-transparency-thumb.webp","sourceName":"87710.png","variants":[],"section":"Bias cognitivi","topic":"Relazione"},{"id":"limit-model","name":"L.I.M.I.T. Model · Tavola d’insieme","english":"L.I.M.I.T. Model","animal":"Mulo · Cervo · Polpo · Volpe · Lince","animals":["Mulo","Cervo","Polpo","Volpe","Lince"],"slogan":"La relazione integra carico, identità, mentalizzazione, inibizione e tensione. Il limite emerge quando queste forze si sbilanciano sotto pressione.","closing":"Anteprima sinteticamente operativa del prossimo libro.","description":"Il L.I.M.I.T. Model è la proposta teorica e formativa di Tommaso Corona per leggere i sistemi cognitivi e relazionali sotto pressione. Load, Identity, Mentalizing, Inhibition e Tension sono dimensioni compresenti, che cambiano e si influenzano reciprocamente. La cornice aiuta a osservare come carico, senso di sé, comprensione degli stati mentali, regolazione della risposta e tensione partecipino alla stessa esperienza. Le lettere organizzano l’osservazione, senza stabilire una sequenza di fasi.","example":"Un’interazione impegnativa può aumentare il carico del mulo, mettere in discussione l’identità del cervo, restringere le ipotesi del polpo, sollecitare l’impulso della volpe e far crescere la tensione della lince. Il poster li riunisce nella stessa scena: nel debriefing si può esplorare come un cambiamento in una dimensione abbia accompagnato cambiamenti nelle altre.","question":"Quali dimensioni erano presenti, come si sono influenzate e dove si è riaperto uno spazio di scelta?","aliases":["LIMIT","LIMIT Model","L I M I T","tavola d’insieme","sintesi","sistema","interazione circolare","debriefing","Load","Identity","Mentalizing","Inhibition","Tension"],"family":"L.I.M.I.T. Model","status":"definitive","order":77,"seriesNumber":78,"approvalBatch":14,"authors":["Tommaso Corona"],"references":[],"modelAttribution":"Tommaso Corona · Limite & Relazione. L.I.M.I.T. Model: proposta teorica e formativa personale.","referenceOrigin":"Il modello e la sua applicazione formativa riprendono il lavoro dell’autore. Le cinque dimensioni sono compresenti e interagiscono continuamente. La proposta non è ancora validata empiricamente.","note":"Poster definitivo fornito dall’autore nel quattordicesimo gruppo di allegati, 9 ottobre 2026. Titolo, abbinamenti, slogan e chiusura trascritti dall’originale. Fa parte dello spazio dedicato al L.I.M.I.T. Model.","image":"assets/definitivi/limit-model-original.png","original":"assets/definitivi/limit-model-original.png","thumb":"assets/definitivi/limit-model-thumb.webp","sourceName":"87704.png","variants":[],"section":"L.I.M.I.T. Model","topic":"Il modello"},{"id":"limit-load","name":"L — Load · Carico cognitivo","english":"L — Load (Carico cognitivo)","animal":"Mulo","animals":["Mulo"],"modelLetter":"L","modelTerm":"Load","modelTranslation":"Carico cognitivo","slogan":"La relazione seleziona ciò che conta. Il limite si perde quando il carico supera la capacità di orientarsi.","closing":"Anteprima concettualmente sovraccarica del LIMIT Model.","description":"Nel L.I.M.I.T. Model, Load riguarda il carico di informazioni, richieste e rappresentazioni da gestire. Sotto pressione, obiettivi, problemi e scadenze possono contendersi l’attenzione e rendere difficile riconoscere una priorità. La dimensione invita a osservare il rapporto tra ciò che la situazione richiede e le risorse disponibili, insieme agli effetti sulle altre dimensioni del modello.","example":"Il mulo porta libri, mappe, strumenti e compiti mentre riceve indicazioni in molte direzioni. Aggiungere un’altra richiesta senza rivedere le priorità può accrescere il disorientamento. La scena invita a distinguere ciò che serve adesso da ciò che può attendere, considerando anche tensione, aspettative e possibilità di risposta.","question":"Quale richiesta è prioritaria adesso e quali informazioni o compiti posso mettere temporaneamente in secondo piano?","aliases":["LIMIT","LIMIT Model","L I M I T","Load","carico cognitivo","carico mentale","sovraccarico","priorità","mule","mulo"],"family":"L.I.M.I.T. Model","status":"definitive","order":78,"seriesNumber":79,"approvalBatch":14,"authors":["Tommaso Corona"],"references":[],"modelAttribution":"Tommaso Corona · Limite & Relazione. L.I.M.I.T. Model: proposta teorica e formativa personale.","referenceOrigin":"Il modello e la sua applicazione formativa riprendono il lavoro dell’autore. Le cinque dimensioni sono compresenti e interagiscono continuamente. La proposta non è ancora validata empiricamente.","note":"Poster definitivo fornito dall’autore nel quattordicesimo gruppo di allegati, 9 ottobre 2026. Titolo, abbinamenti, slogan e chiusura trascritti dall’originale. Fa parte dello spazio dedicato al L.I.M.I.T. Model.","image":"assets/definitivi/limit-load-original.png","original":"assets/definitivi/limit-load-original.png","thumb":"assets/definitivi/limit-load-thumb.webp","sourceName":"87709.png","variants":[],"section":"L.I.M.I.T. Model","topic":"Le cinque dimensioni"},{"id":"limit-identity","name":"I — Identity · Identità","english":"I — Identity (Identità)","animal":"Cervo","animals":["Cervo"],"modelLetter":"I","modelTerm":"Identity","modelTranslation":"Identità","slogan":"La relazione riconosce chi siamo anche sotto pressione. Il limite irrigidisce l’identità quando sente che potrebbe incrinarsi.","closing":"Anteprima simbolicamente identitaria del LIMIT Model.","description":"Nel L.I.M.I.T. Model, Identity riguarda la continuità del senso di sé, i ruoli, le appartenenze e i valori che orientano la persona. Una situazione può essere vissuta anche attraverso ciò che sembra mettere in discussione della propria identità. La dimensione aiuta a riconoscere come la protezione dell’immagine di sé partecipi all’interazione con carico, tensione, comprensione dell’altro e regolazione della risposta.","example":"Il cervo guarda nello specchio una figura incerta e una figura corazzata, circondato da richiami a ruoli, aspettative e approvazione. Nel debriefing, la scena può aiutare a chiedersi quale parte di sé ci si è sentiti chiamati a proteggere e come questa esigenza abbia orientato il modo di rispondere.","question":"Quale ruolo, appartenenza o valore sento messo in discussione e come sta orientando la mia risposta?","aliases":["LIMIT","LIMIT Model","L I M I T","Identity","identità","ruoli","appartenenza","immagine di sé","aspettative","cervo","deer"],"family":"L.I.M.I.T. Model","status":"definitive","order":79,"seriesNumber":80,"approvalBatch":14,"authors":["Tommaso Corona"],"references":[],"modelAttribution":"Tommaso Corona · Limite & Relazione. L.I.M.I.T. Model: proposta teorica e formativa personale.","referenceOrigin":"Il modello e la sua applicazione formativa riprendono il lavoro dell’autore. Le cinque dimensioni sono compresenti e interagiscono continuamente. La proposta non è ancora validata empiricamente.","note":"Poster definitivo fornito dall’autore nel quattordicesimo gruppo di allegati, 9 ottobre 2026. Titolo, abbinamenti, slogan e chiusura trascritti dall’originale. Fa parte dello spazio dedicato al L.I.M.I.T. Model.","image":"assets/definitivi/limit-identity-original.png","original":"assets/definitivi/limit-identity-original.png","thumb":"assets/definitivi/limit-identity-thumb.webp","sourceName":"87708.png","variants":[],"section":"L.I.M.I.T. Model","topic":"Le cinque dimensioni"},{"id":"limit-mentalizing","name":"M — Mentalizing · Mentalizzazione","english":"Mentalization (Mentalizzazione)","animal":"Polpo · Volpe","animals":["Polpo","Volpe"],"modelLetter":"M","modelTerm":"Mentalizing","modelTranslation":"Mentalizzazione","slogan":"La relazione si chiede cosa possa esserci dietro un comportamento. Il limite decide troppo presto cosa l’altro pensa, sente o vuole.","closing":"Anteprima curiosamente mentalizzata del prossimo libro.","description":"Nel L.I.M.I.T. Model, Mentalizing riguarda il modo in cui consideriamo gli stati mentali propri e altrui per comprendere un comportamento. Emozioni, intenzioni e aspettative sono ipotesi da esplorare, conservando spazio per ciò che ancora non sappiamo. Il polpo rappresenta questa curiosità: i punti interrogativi aiutano a mantenere aperte più letture, anche quando carico e tensione rendono urgente una conclusione.","example":"Durante il colloquio, il polpo si domanda se nella postura della volpe ci siano paura, rabbia, vergogna o stanchezza. I cartelli sono domande, non conclusioni sulla sua mente. La scena invita a distinguere ciò che si osserva dalle interpretazioni e a cercare chiarimenti attraverso la relazione.","question":"Che cosa sto osservando, quale stato mentale sto ipotizzando e come posso verificare la mia lettura?","aliases":["LIMIT","LIMIT Model","L I M I T","Mentalizing","Mentalization","mentalizzazione","stati mentali","Paura?","Rabbia?","Vergogna?","Stanchezza?","colloquio","polpo","volpe"],"family":"L.I.M.I.T. Model","status":"definitive","order":80,"seriesNumber":81,"approvalBatch":14,"authors":["Tommaso Corona"],"references":[],"modelAttribution":"Tommaso Corona · Limite & Relazione. L.I.M.I.T. Model: proposta teorica e formativa personale.","referenceOrigin":"Il modello e la sua applicazione formativa riprendono il lavoro dell’autore. Le cinque dimensioni sono compresenti e interagiscono continuamente. La proposta non è ancora validata empiricamente.","note":"Poster definitivo fornito dall’autore nel quattordicesimo gruppo di allegati, 9 ottobre 2026. Titolo, abbinamenti, slogan e chiusura trascritti dall’originale. Fa parte dello spazio dedicato al L.I.M.I.T. Model.","image":"assets/definitivi/limit-mentalizing-original.png","original":"assets/definitivi/limit-mentalizing-original.png","thumb":"assets/definitivi/limit-mentalizing-thumb.webp","sourceName":"87707.png","variants":[],"section":"L.I.M.I.T. Model","topic":"Le cinque dimensioni"},{"id":"limit-inhibition","name":"I — Inhibition · Inibizione","english":"I — Inhibition (Inibizione)","animal":"Volpe","animals":["Volpe"],"modelLetter":"I","modelTerm":"Inhibition","modelTranslation":"Inibizione","slogan":"La relazione trattiene la risposta finché non ne comprende il senso. Il limite agisce troppo presto o si blocca quando non riesce più a regolare l’impulso.","closing":"Anteprima decisamente trattenuta del LIMIT Model.","description":"Nel L.I.M.I.T. Model, Inhibition riguarda la possibilità di modulare o sospendere una risposta automatica, osservare gli effetti e considerare alternative. Una pausa può offrire spazio per scegliere quando e come agire. La dimensione comprende la regolazione dell’impulso e va letta insieme al carico, alla tensione, al senso di sé e alla comprensione della situazione.","example":"La volpe tiene la zampa sopra un pulsante, fra l’invito alla ricompensa immediata e i cartelli “Fermati, rifletti, valuta, scegli”. Nel colloquio, il pulsante può rappresentare l’impulso a correggere, spiegare o rispondere subito. La pausa permette di osservare che cosa si sta cercando di ottenere con quella risposta.","question":"Quale impulso sto per seguire e che cosa posso comprendere se mi concedo una pausa prima di rispondere?","aliases":["LIMIT","LIMIT Model","L I M I T","Inhibition","inibizione","impulso","pausa","risposta automatica","fermati","rifletti","valuta","scegli","volpe","fox"],"family":"L.I.M.I.T. Model","status":"definitive","order":81,"seriesNumber":82,"approvalBatch":14,"authors":["Tommaso Corona"],"references":[],"modelAttribution":"Tommaso Corona · Limite & Relazione. L.I.M.I.T. Model: proposta teorica e formativa personale.","referenceOrigin":"Il modello e la sua applicazione formativa riprendono il lavoro dell’autore. Le cinque dimensioni sono compresenti e interagiscono continuamente. La proposta non è ancora validata empiricamente.","note":"Poster definitivo fornito dall’autore nel quattordicesimo gruppo di allegati, 9 ottobre 2026. Titolo, abbinamenti, slogan e chiusura trascritti dall’originale. Fa parte dello spazio dedicato al L.I.M.I.T. Model.","image":"assets/definitivi/limit-inhibition-original.png","original":"assets/definitivi/limit-inhibition-original.png","thumb":"assets/definitivi/limit-inhibition-thumb.webp","sourceName":"87706.png","variants":[],"section":"L.I.M.I.T. Model","topic":"Le cinque dimensioni"},{"id":"limit-tension","name":"T — Tension · Tensione","english":"T — Tension (Tensione)","animal":"Lince","animals":["Lince"],"modelLetter":"T","modelTerm":"Tension","modelTranslation":"Tensione","slogan":"La relazione contiene la tensione e le dà una direzione. Il limite, quando la tensione sale troppo, restringe il pensiero e la scelta.","closing":"Anteprima emotivamente sotto pressione del LIMIT Model.","description":"Nel L.I.M.I.T. Model, Tension riguarda la pressione dinamica vissuta fra richieste, obiettivi, vincoli, emozioni e possibilità percepite. Il modello invita a osservare come la tensione cambi nell’interazione e partecipi alla disponibilità di alternative. Allerta, paura e dubbio sono i vissuti evocati dalla lince: si intrecciano con le altre dimensioni, anziché costituire una fase conclusiva.","example":"La lince resta in allerta su una passerella sotto il temporale, fra cartelli di pressione, paura e dubbio. La scena mette in primo piano la tensione vissuta. Nel debriefing, si può esplorare come siano cambiati il pensiero, la lettura dell’altro e la risposta quando la pressione è cresciuta o ha trovato contenimento.","question":"Come sta cambiando la mia tensione e quali possibilità di pensiero e di risposta riesco ancora a considerare?","aliases":["LIMIT","LIMIT Model","L I M I T","Tension","tensione","allerta","paura","pressione","dubbio","lince","lynx"],"family":"L.I.M.I.T. Model","status":"definitive","order":82,"seriesNumber":83,"approvalBatch":14,"authors":["Tommaso Corona"],"references":[],"modelAttribution":"Tommaso Corona · Limite & Relazione. L.I.M.I.T. Model: proposta teorica e formativa personale.","referenceOrigin":"Il modello e la sua applicazione formativa riprendono il lavoro dell’autore. Le cinque dimensioni sono compresenti e interagiscono continuamente. La proposta non è ancora validata empiricamente.","note":"Poster definitivo fornito dall’autore nel quattordicesimo gruppo di allegati, 9 ottobre 2026. Titolo, abbinamenti, slogan e chiusura trascritti dall’originale. Fa parte dello spazio dedicato al L.I.M.I.T. Model.","image":"assets/definitivi/limit-tension-original.png","original":"assets/definitivi/limit-tension-original.png","thumb":"assets/definitivi/limit-tension-thumb.webp","sourceName":"87705.png","variants":[],"section":"L.I.M.I.T. Model","topic":"Le cinque dimensioni"},{"id":"intersubjectivity","name":"Intersoggettività","english":"Intersubjectivity","animal":"Orso · Volpe","animals":["Orso","Volpe"],"family":"Relazione","slogan":"La relazione vede nell’altro un soggetto che interpreta, sente e risponde. Il limite lo riduce a un contenitore di informazioni da estrarre.","closing":"Anteprima autenticamente intersoggettiva del prossimo libro.","description":"L’intersoggettività riguarda l’incontro fra soggettività che interpretano, sentono e contribuiscono all’interazione. Riconoscere l’altro come soggetto significa considerare che risposte e comportamenti prendono forma anche attraverso la sua esperienza, le intenzioni e il significato attribuito alla situazione. Entrambi i partecipanti contribuiscono a ciò che accade nella relazione. Nel poster, all’interesse per i dati si affianca il riconoscimento della persona che li comunica.","example":"A sinistra, l’orso guarda la volpe attraverso fascicoli di dati, risposte e informazioni. A destra, la scena dà spazio anche a identità, memoria, paura, significati e intenzioni. L’interlocutore viene riconosciuto come qualcuno che vive e interpreta il colloquio; il modo di rivolgersi a lui partecipa alla relazione e alle risposte che prendono forma.","question":"Sto considerando anche l’esperienza e i significati dell’altro, oltre alle informazioni che mi sta comunicando?","aliases":["intersubjectivity","intersoggettività","soggettività","riconoscimento","soggetto","oggetto","incontro","colloquio","interrogatorio","identità","memoria","significati","intenzioni","bear","fox"],"authors":["Jessica Benjamin","Daniel N. Stern"],"references":[{"label":"Jessica Benjamin (2004)","citation":"Beyond doer and done to: An intersubjective view of thirdness. The Psychoanalytic Quarterly, 73(1), 5–46.","url":"https://doi.org/10.1002/j.2167-4086.2004.tb00151.x"},{"label":"Daniel N. Stern (2005)","citation":"Il momento presente. In psicoterapia e nella vita quotidiana. Raffaello Cortina Editore.","url":"https://www.raffaellocortina.it/scheda-libro/daniel-n-stern/il-momento-presente-9788870789485-757.html"}],"referenceOrigin":"Inquadramento bibliografico aggiunto all’atlante: Benjamin per la partecipazione di due soggettività e il riconoscimento; Stern per l’esperienza condivisa nell’incontro. Sono riferimenti teorici all’intersoggettività, distinti dall’applicazione editoriale al colloquio rappresentata nel poster.","status":"definitive","order":83,"seriesNumber":84,"approvalBatch":15,"note":"Poster definitivo fornito dall’autore nel quindicesimo gruppo di allegati, 10 ottobre 2026. Titolo, animali, slogan e chiusura trascritti dall’originale. La scheda presenta un processo relazionale nel tema Relazione.","image":"assets/definitivi/intersubjectivity-original.png","original":"assets/definitivi/intersubjectivity-original.png","thumb":"assets/definitivi/intersubjectivity-thumb.webp","sourceName":"87718.png","variants":[],"section":"Mente, esperienza e relazione","topic":"Relazioni, legami e dinamiche sociali"},{"id":"expectation-blindness","name":"Cecità da aspettativa","english":"Expectation blindness","animal":"Segugio · Procione","animals":["Segugio","Cane","Procione"],"family":"Informazione","slogan":"La relazione lascia spazio anche a ciò che non si aspettava di trovare. Il limite vede soprattutto ciò che aveva già previsto.","closing":"Anteprima prevedibilmente distratta del prossimo libro.","description":"Qui “cecità da aspettativa” descrive il rischio di trascurare elementi inattesi mentre l’attenzione è orientata verso ciò che si sta cercando. Obiettivi e caratteristiche attese possono guidare la selezione degli indizi: qualcosa di visibile può restare inosservato quando l’attenzione è impegnata altrove. La scena richiama gli studi sull’orientamento dell’attenzione e sulla cecità da disattenzione. L’invito del poster è mantenere aperta la possibilità di incontrare informazioni diverse da quelle previste.","example":"Il cartello “Cerca: volpe” orienta il segugio sulle impronte, mentre il procione e gli oggetti accanto a lui restano sotto il cartello “Prova inattesa”. La scena mostra il rischio di una ricerca troppo stretta. Nella lettura di un resoconto, cercare soltanto un dettaglio previsto può far trascurare un passaggio importante che riguarda un’altra possibilità. Fermarsi e rileggere con una domanda più aperta può aiutare a considerarlo.","question":"Quale elemento potrei aver trascurato perché cercavo soltanto ciò che mi aspettavo di trovare?","aliases":["expectation blindness","cecità da aspettativa","aspettative","attenzione selettiva","attentional set","inattentional blindness","cecità da disattenzione","prova inattesa","cerca volpe","segugio","cane","procione","hound","dog","raccoon"],"authors":["Steven B. Most","Brian J. Scholl","Erin R. Clifford","Daniel J. Simons","Christopher F. Chabris"],"references":[{"label":"Steven B. Most, Brian J. Scholl, Erin R. Clifford e Daniel J. Simons (2005)","citation":"What you see is what you set: Sustained inattentional blindness and the capture of awareness. Psychological Review, 112(1), 217–242.","url":"https://doi.org/10.1037/0033-295X.112.1.217"},{"label":"Daniel J. Simons e Christopher F. Chabris (1999)","citation":"Gorillas in our midst: Sustained inattentional blindness for dynamic events. Perception, 28(9), 1059–1074.","url":"https://doi.org/10.1068/p281059"}],"referenceOrigin":"Inquadramento bibliografico aggiunto all’atlante: Most e colleghi per il ruolo degli obiettivi attentivi; Simons e Chabris per la mancata rilevazione di eventi inattesi. Il titolo è conservato nel senso descrittivo del poster. Le fonti riguardano processi attentivi collegati alla scena, senza identificare il titolo editoriale con una categoria sperimentale autonoma.","status":"definitive","order":84,"seriesNumber":85,"approvalBatch":16,"note":"Poster definitivo fornito dall’autore nel sedicesimo gruppo di allegati, 10 ottobre 2026. Titolo, slogan e chiusura trascritti dall’originale. Il segugio è il protagonista; il procione rappresenta l’elemento inatteso nella scena.","image":"assets/definitivi/expectation-blindness-original.png","original":"assets/definitivi/expectation-blindness-original.png","thumb":"assets/definitivi/expectation-blindness-thumb.webp","sourceName":"87761.png","variants":[],"section":"Mente, esperienza e relazione","topic":"Percezione, coscienza e memoria"},{"id":"dodo-verdict","name":"Verdetto del dodo","english":"Dodo verdict","animal":"Dodo · Lepre · Varano · Volpe · Tasso · Gufo","animals":["Dodo","Lepre","Varano","Volpe","Tasso","Gufo"],"family":"Relazione","slogan":"La relazione non si ferma al traguardo formale, ma osserva il cambiamento prodotto. Il limite pensa che arrivare alla meta significhi aver formato allo stesso modo.","closing":"Anteprima formalmente riuscita del prossimo libro.","description":"Il verdetto del dodo richiama una metafora tratta da Alice nel Paese delle Meraviglie: il giudice dichiara che tutti hanno vinto. Rosenzweig la porta nel dibattito sui fattori comuni delle psicoterapie, poi sviluppato anche da Wampold. Nel poster, il richiamo viene applicato alla formazione: percorsi diversi convergono verso lo stesso traguardo, ma il completamento formale lascia aperta la domanda sul cambiamento prodotto. Per valutarlo occorre osservare che cosa ciascun partecipante ha appreso e riesce a mettere in pratica. L’analogia formativa è una lettura editoriale; il dibattito clinico non stabilisce che ogni trattamento produca gli stessi esiti per qualsiasi problema.","example":"La lepre corre, il varano procede sulla strada lastricata, la volpe consulta una mappa, il tasso percorre il sentiero roccioso e il gufo vola verso il dodo al traguardo. Il cartello chiede “Tutti hanno vinto?”. In un corso, due partecipanti possono ottenere lo stesso attestato: uno applica una competenza in una situazione nuova, l’altro riesce ancora a usarla soltanto nell’esercizio guidato. Per comprendere l’esito formativo bisogna osservare anche ciò che accade dopo il traguardo.","question":"Oltre al traguardo raggiunto, quale cambiamento riesco a osservare e come si manifesta nella pratica?","aliases":["dodo verdict","verdetto del dodo","dodo bird verdict","dodo bird effect","fattori comuni","common factors","equivalenza degli esiti","formazione","apprendimento","cambiamento","traguardo formale","tutti hanno vinto","Alice nel Paese delle Meraviglie","Lewis Carroll","monitor lizard","hare","fox","badger","owl"],"authors":["Saul Rosenzweig","Bruce E. Wampold"],"references":[{"label":"Saul Rosenzweig (1936)","citation":"Some implicit common factors in diverse methods of psychotherapy. American Journal of Orthopsychiatry, 6(3), 412–415.","url":"https://doi.org/10.1111/j.1939-0025.1936.tb05248.x"},{"label":"Bruce E. Wampold (2015)","citation":"How important are the common factors in psychotherapy? An update. World Psychiatry, 14(3), 270–277.","url":"https://doi.org/10.1002/wps.20238"}],"referenceOrigin":"Inquadramento bibliografico aggiunto all’atlante: Rosenzweig per il richiamo al dodo e ai fattori comuni delle psicoterapie; Wampold per il successivo modello contestuale e le evidenze sui fattori comuni. Sono riferimenti al dibattito clinico. L’applicazione al traguardo formale e al cambiamento nella formazione appartiene alla metafora editoriale del poster.","status":"definitive","order":85,"seriesNumber":86,"approvalBatch":17,"note":"Poster definitivo fornito dall’autore nel diciassettesimo gruppo di allegati, 10 ottobre 2026. Titolo, slogan e chiusura trascritti dall’originale. Il dodo è il giudice; lepre, varano, volpe, tasso e gufo convergono verso il traguardo attraverso percorsi diversi.","image":"assets/definitivi/dodo-verdict-original.png","original":"assets/definitivi/dodo-verdict-original.png","thumb":"assets/definitivi/dodo-verdict-thumb.webp","sourceName":"87773.png","variants":[],"section":"Mente, esperienza e relazione","topic":"Relazioni, legami e dinamiche sociali"},{"id":"state-of-consciousness","name":"Stato di coscienza","english":"State of consciousness","animal":"Lemuri","animals":["Lemure"],"sourceName":"87958.png","slogan":"La relazione considera lo stato in cui la persona si trova prima di interpretarne parole e gesti. Il limite giudica la risposta, senza vedere la condizione da cui nasce.","closing":"Anteprima lucidamente variabile del prossimo libro.","description":"Lo stato di coscienza riguarda la condizione complessiva in cui si svolge l’esperienza della persona. Vigilanza e consapevolezza sono dimensioni da distinguere: essere svegli non esaurisce ciò che significa essere consapevoli di sé e dell’ambiente. Nel poster i lemuri richiamano sonnolenza, veglia tranquilla e forte allerta. Quest’ultima riguarda l’attivazione; lo stress può modificare la regolazione dell’attenzione e delle risposte. L’invito è considerare la condizione della persona quando si cerca di comprendere ciò che dice e fa.","example":"Un lemure riposa, uno osserva con calma e uno appare molto allertato. In un colloquio, una risposta lenta può accompagnarsi alla stanchezza, mentre una risposta brusca può emergere in una situazione di forte tensione. Prima di attribuire un significato stabile a quel comportamento, si può esplorare come la persona stia vivendo il momento e adattare ritmo e modalità del dialogo.","question":"Sto interpretando la risposta tenendo conto della vigilanza, della fatica e della tensione di chi ho davanti?","aliases":["state of consciousness","stato di coscienza","vigilanza","veglia","consapevolezza","sonnolenza","allerta","attivazione","arousal","fatica","lemure","lemur"],"authors":["Steven Laureys","Amy F. T. Arnsten"],"references":[{"label":"Steven Laureys (2005)","citation":"The neural correlate of (un)awareness: lessons from the vegetative state. Trends in Cognitive Sciences, 9(12), 556–559.","url":"https://doi.org/10.1016/j.tics.2005.10.010"},{"label":"Amy F. T. Arnsten (2009)","citation":"Stress signalling pathways that impair prefrontal cortex structure and function. Nature Reviews Neuroscience, 10(6), 410–422.","url":"https://doi.org/10.1038/nrn2648"}],"referenceOrigin":"Inquadramento bibliografico aggiunto all’atlante: Laureys per la distinzione fra vigilanza e consapevolezza; Arnsten per gli effetti dello stress sulla regolazione cognitiva. Il riferimento clinico di Laureys fornisce una distinzione concettuale; i lemuri rappresentano condizioni quotidiane, senza corrispondere a una classificazione di disturbi della coscienza.","note":"Poster definitivo fornito dall’autore nel diciottesimo gruppo di allegati, 11 ottobre 2026. Titolo, slogan e chiusura trascritti dall’originale. Tre lemuri rappresentano differenti condizioni di vigilanza e attivazione. Fa parte del tema Coscienza.","family":"Coscienza","status":"definitive","order":86,"seriesNumber":87,"approvalBatch":18,"image":"assets/definitivi/state-of-consciousness-original.png","original":"assets/definitivi/state-of-consciousness-original.png","thumb":"assets/definitivi/state-of-consciousness-thumb.webp","variants":[],"section":"Mente, esperienza e relazione","topic":"Percezione, coscienza e memoria"},{"id":"field-of-consciousness","name":"Campo di coscienza","english":"Field of consciousness","animal":"Suricato · Serpente · Rapace","animals":["Suricato","Serpente","Rapace"],"sourceName":"87959.png","slogan":"La relazione tiene insieme il contesto. Il limite scambia ciò che cattura l’attenzione per tutto ciò che conta.","closing":"Anteprima attentivamente situata del prossimo libro.","description":"Il campo di coscienza è qui inteso come l’insieme dei contenuti presenti nell’esperienza del momento: percezioni, sensazioni, pensieri e vissuti, con elementi in primo piano e altri sullo sfondo. L’attenzione selettiva privilegia alcuni contenuti e orienta ciò che stiamo considerando. Campo e fuoco attentivo sono collegati, ma non sono sinonimi. Il contesto esterno comprende anche elementi che non abbiamo ancora notato: il poster invita a esplorarlo senza ridurre la situazione al solo dettaglio che ci attrae.","example":"Il suricato guarda una bacca rossa, mentre intorno ci sono un altro suricato, un serpente e un rapace. Il cerchio tratteggiato rende visibile la focalizzazione: è una metafora, non un confine letterale della coscienza. Durante una conversazione, una singola parola può assorbire l’attenzione; tornando a osservare tono, situazione e andamento dello scambio, si possono considerare aspetti che quel dettaglio aveva lasciato in secondo piano.","question":"Che cosa sto mettendo a fuoco e quali aspetti del contesto potrei ancora esplorare?","aliases":["field of consciousness","campo di coscienza","fuoco attentivo","attenzione selettiva","contesto","primo piano","sfondo","fringe","bacca rossa","suricato","meerkat","snake","bird of prey"],"authors":["William James","Victor A. F. Lamme"],"references":[{"label":"William James (1890; ristampa 1918)","citation":"The Principles of Psychology. Vol. I, cap. IX, “The Stream of Thought”, e cap. XI, “Attention”. Henry Holt and Company. Opera originale pubblicata nel 1890; testo consultato nella ristampa del 1918.","url":"https://www.gutenberg.org/ebooks/57628"},{"label":"Victor A. F. Lamme (2003)","citation":"Why visual attention and awareness are different. Trends in Cognitive Sciences, 7(1), 12–18.","url":"https://doi.org/10.1016/S1364-6613(02)00013-X"}],"referenceOrigin":"Inquadramento bibliografico aggiunto all’atlante: James per il flusso dell’esperienza, i contenuti in primo piano e la frangia di relazioni e significati; Lamme per la distinzione teorica fra attenzione e consapevolezza visiva. Il poster usa questi concetti in una metafora del contesto e della focalizzazione, senza rappresentare una misura del campo di coscienza.","note":"Poster definitivo fornito dall’autore nel diciottesimo gruppo di allegati, 11 ottobre 2026. Titolo, slogan e chiusura trascritti dall’originale. Il suricato concentrato sulla bacca è il protagonista; il secondo suricato, il serpente e il rapace partecipano al contesto. Fa parte del tema Coscienza.","family":"Coscienza","status":"definitive","order":87,"seriesNumber":88,"approvalBatch":18,"image":"assets/definitivi/field-of-consciousness-original.png","original":"assets/definitivi/field-of-consciousness-original.png","thumb":"assets/definitivi/field-of-consciousness-thumb.webp","variants":[],"section":"Mente, esperienza e relazione","topic":"Percezione, coscienza e memoria"},{"id":"mood-congruent-memory","name":"Memoria congruente con l’umore","english":"Mood-congruent memory","animal":"Procioni","animals":["Procione"],"slogan":"La relazione sa che l’umore orienta ciò che torna alla mente. Il limite scambia ciò che è più accessibile per ciò che è più importante.","closing":"Anteprima emotivamente evocata del prossimo libro.","description":"La memoria congruente con l’umore è la tendenza a richiamare più facilmente contenuti il cui tono emotivo è compatibile con l’umore del momento. Quando siamo tristi possono tornare alla mente più facilmente episodi negativi; un umore piacevole può favorire ricordi positivi. È una tendenza, non una regola automatica. La maggiore accessibilità di un ricordo non ne dimostra l’importanza, la completezza o l’accuratezza. La congruenza riguarda il rapporto fra umore attuale e tono del contenuto ricordato; la memoria dipendente dall’umore riguarda invece la corrispondenza fra lo stato al momento dell’apprendimento e quello al richiamo.","example":"Il procione triste sfoglia fotografie nel lato buio e piovoso della scena; quello sorridente, illuminato dal sole, guarda un ricordo affettuoso. Ripensando alla giornata dopo una delusione, possono emergere subito gli episodi spiacevoli. In un momento più sereno possono diventare più accessibili anche quelli positivi. L’invito del poster è riconoscere questo orientamento e chiedersi quali altri episodi meritino di essere considerati.","question":"Quanto del ricordo che mi viene subito in mente dipende dal mio umore, e quali altri episodi potrei considerare?","aliases":["mood congruent memory","memoria congruente con l’umore","congruenza emotiva","richiamo","ricordo","ricordi","umore","accessibilità","memoria autobiografica","mood congruence","affect and memory","procione","raccoon"],"family":"Memoria","status":"definitive","order":88,"seriesNumber":89,"approvalBatch":19,"authors":["Gordon H. Bower","Paul H. Blaney"],"references":[{"label":"Gordon H. Bower (1981)","citation":"Mood and memory. American Psychologist, 36(2), 129–148.","url":"https://doi.org/10.1037/0003-066X.36.2.129"},{"label":"Paul H. Blaney (1986)","citation":"Affect and memory: A review. Psychological Bulletin, 99(2), 229–246.","url":"https://doi.org/10.1037/0033-2909.99.2.229"}],"referenceOrigin":"Inquadramento bibliografico aggiunto all’atlante: Bower per gli esperimenti e il modello associativo sui rapporti fra umore e memoria; Blaney come riferimento di rassegna sul rapporto fra affetto e memoria. Questi riferimenti integrano la metafora editoriale del poster.","note":"Poster definitivo fornito dall’autore nel diciannovesimo gruppo di allegati, 11 ottobre 2026. Titolo, slogan e chiusura trascritti dall’originale. Due procioni, uno triste e uno sorridente, richiamano ricordi in due ambienti dal diverso tono emotivo. Fa parte del tema Memoria.","image":"assets/definitivi/mood-congruent-memory-original.png","original":"assets/definitivi/mood-congruent-memory-original.png","thumb":"assets/definitivi/mood-congruent-memory-thumb.webp","sourceName":"87990.png","variants":[],"section":"Mente, esperienza e relazione","topic":"Percezione, coscienza e memoria"},{"id":"empathy-emotional-intelligence","name":"Empatia e intelligenza emotiva","english":"Empathy and emotional intelligence","animal":"Elefante · Volpe","animals":["Elefante","Volpe"],"sourceName":"88030.png","family":"Relazione","slogan":"La relazione ascolta anche ciò che l’altro non riesce a dire. Il limite si ferma alle parole e non vede l’emozione che le accompagna.","closing":"Anteprima emotivamente sintonizzata del prossimo libro.","description":"L’empatia permette di avvicinarsi al vissuto dell’altro, cercando di comprenderne la prospettiva e risuonando con le sue emozioni, mantenendo distinta la propria esperienza. L’intelligenza emotiva riguarda le capacità di riconoscere, esprimere e regolare le emozioni proprie e altrui e di utilizzarle per orientare il pensiero e l’azione. Le due capacità si intrecciano nell’ascolto: parole, postura e lacrime offrono indizi da esplorare. Il loro significato va chiarito nel dialogo, lasciando alla persona lo spazio per nominare ciò che prova.","example":"L’elefante offre un fazzoletto alla volpe che dice “Sto bene…” e piange. Le parole “Paura”, “Tristezza” e “Tensione” rendono visibili possibili vissuti nella metafora del poster. In una conversazione, si può accogliere la risposta e chiedere con delicatezza “Ti va di raccontarmi come ti senti?”, rispettando il ritmo dell’altro e riconoscendo anche le proprie reazioni emotive.","question":"Sto ascoltando parole ed emozioni, lasciando all’altro la possibilità di chiarire il proprio vissuto?","aliases":["empatia","intelligenza emotiva","empathy","emotional intelligence","ascolto","sintonizzazione emotiva","regolazione emotiva","prospettiva dell’altro","elephant","fox"],"authors":["Peter Salovey","John D. Mayer","Jean Decety","Philip L. Jackson","Daniel Goleman"],"references":[{"label":"Peter Salovey e John D. Mayer (1990)","citation":"Emotional intelligence. Imagination, Cognition and Personality, 9(3), 185–211.","url":"https://doi.org/10.2190/DUGG-P24E-52WK-6CDG"},{"label":"Jean Decety e Philip L. Jackson (2004)","citation":"The functional architecture of human empathy. Behavioral and Cognitive Neuroscience Reviews, 3(2), 71–100.","url":"https://doi.org/10.1177/1534582304267187"},{"label":"Daniel Goleman (2001) · testo integrale","citation":"An EI-Based Theory of Performance. In C. Cherniss e D. Goleman (a cura di), The Emotionally Intelligent Workplace: How to Select for, Measure, and Improve Emotional Intelligence in Individuals, Groups, and Organizations (pp. 27–44). Jossey-Bass.","url":"https://www.eiconsortium.org/pdf/an_ei_based_theory_of_performance.pdf"}],"referenceOrigin":"Inquadramento bibliografico aggiunto all’atlante: Salovey e Mayer per il modello di abilità dell’intelligenza emotiva; Decety e Jackson per le componenti dell’empatia, compresa la consapevolezza di sé e la regolazione emotiva; Goleman per il modello delle competenze emotive articolato in consapevolezza di sé, gestione di sé, consapevolezza sociale e gestione delle relazioni. Il contributo di Goleman è collegato al testo integrale reso disponibile dal Consortium for Research on Emotional Intelligence in Organizations, aggiunto su richiesta dell’autore il 12 ottobre 2026. L’esempio di ascolto sviluppa la metafora editoriale del poster.","note":"Poster definitivo fornito dall’autore nel ventesimo gruppo di allegati, 12 ottobre 2026. Titolo, slogan e chiusura trascritti dall’originale; il titolo inglese nella scheda è una traduzione. L’elefante ascolta e offre un fazzoletto alla volpe. Fa parte del tema Relazione.","status":"definitive","order":89,"seriesNumber":90,"approvalBatch":20,"image":"assets/definitivi/empathy-emotional-intelligence-original.png","original":"assets/definitivi/empathy-emotional-intelligence-original.png","thumb":"assets/definitivi/empathy-emotional-intelligence-thumb.webp","variants":[],"section":"Mente, esperienza e relazione","bookTitle":"Psiche & Thanatos","bookUrl":"https://www.amazon.it/dp/B0DVCC1HY6","topic":"Relazioni, legami e dinamiche sociali"},{"id":"apophenia","name":"Apofenia","english":"Apophenia","animal":"Corvo","animals":["Corvo"],"sourceName":"88187.png","family":"Informazione","slogan":"La relazione verifica se il legame esiste davvero. Il limite unisce i puntini e scambia per significativo ciò che assomiglia a un disegno.","closing":"Anteprima ironicamente interpretativa del prossimo libro.","description":"L’apofenia consiste nel percepire significati, schemi o connessioni causali in elementi casuali o non collegati. La mente può costruire un disegno coerente a partire da somiglianze e coincidenze e scambiarlo per un legame reale. Riconoscere regolarità è utile; la verifica aiuta a distinguere un’ipotesi da un collegamento illusorio. Il poster invita a cercare riscontri indipendenti, considerare il ruolo del caso e confrontare spiegazioni alternative prima di attribuire significato alle connessioni individuate.","example":"Il corvo collega con fili rossi foglie, numeri, macchie, impronte e costellazioni. Nella vita quotidiana, incontrare più volte lo stesso numero può indurre a pensare che annunci un evento. Prima di attribuirgli un significato predittivo, si può esaminare quanto quel numero compaia normalmente e quali dati sostengano l’ipotesi. Il disegno costruito dai collegamenti diventa così un punto di partenza per la verifica.","question":"Quali prove sostengono questo collegamento, e quali altre spiegazioni potrebbero rendere conto degli stessi elementi?","aliases":["apofenia","apophenia","collegamenti illusori","connessioni causali","coincidenze","riconoscimento di schemi","pattern perception","illusory pattern perception","unire i puntini","corvo","raven","crow"],"authors":["Colin G. DeYoung","Rachael G. Grazioplene","Jordan B. Peterson","Jennifer A. Whitson","Adam D. Galinsky"],"references":[{"label":"Colin G. DeYoung, Rachael G. Grazioplene e Jordan B. Peterson (2012)","citation":"From madness to genius: The Openness/Intellect trait domain as a paradoxical simplex. Journal of Research in Personality, 46(1), 63–78.","url":"https://doi.org/10.1016/j.jrp.2011.12.003"},{"label":"Jennifer A. Whitson e Adam D. Galinsky (2008)","citation":"Lacking control increases illusory pattern perception. Science, 322(5898), 115–117.","url":"https://doi.org/10.1126/science.1159845"}],"referenceOrigin":"Inquadramento bibliografico aggiunto all’atlante: DeYoung, Grazioplene e Peterson per l’apofenia come percezione di schemi o connessioni inesistenti nella ricerca sulla personalità; Whitson e Galinsky per gli esperimenti sulla percezione di collegamenti illusori in condizioni di ridotto controllo. La scheda riprende il tema dei falsi collegamenti nella vita quotidiana.","note":"Poster definitivo fornito dall’autore nel ventesimo gruppo di allegati, 12 ottobre 2026. Titolo, slogan e chiusura trascritti dall’originale. Il corvo osserva una parete di elementi collegati da fili rossi. Fa parte del tema Informazione.","status":"definitive","order":90,"seriesNumber":91,"approvalBatch":20,"image":"assets/definitivi/apophenia-original.png","original":"assets/definitivi/apophenia-original.png","thumb":"assets/definitivi/apophenia-thumb.webp","variants":[],"section":"Mente, esperienza e relazione","topic":"Percezione, coscienza e memoria"},{"id":"intrinsic-motivation","name":"Motivazione intrinseca","english":"Intrinsic motivation","sourceName":"88194.png","slogan":"La relazione nutre ciò che ha senso anche senza premio. Il limite perde il piacere, quando tutto diventa solo prestazione.","closing":"Anteprima felicemente autodeterminata del prossimo libro.","description":"La motivazione intrinseca sostiene un’attività per l’interesse e il piacere che offre in sé. Il cane che esplora gli incastri rende visibile questo coinvolgimento: l’attività è già gratificante mentre viene svolta. Nella teoria dell’autodeterminazione, autonomia e possibilità di sentirsi competenti aiutano a sostenerlo. Il significato personale evocato dallo slogan può accompagnare anche motivazioni estrinseche interiorizzate; il criterio dell’intrinseca resta l’interesse per l’attività stessa.","example":"Il cane prova a inserire una forma nel gioco, incuriosito dal problema e coinvolto nella scoperta. Una persona può dedicarsi a un rompicapo o a disegnare perché le piace farlo, anche senza ricevere un premio. Chi la accompagna può lasciare spazio all’esplorazione e offrire un riscontro utile, rispettando il piacere di provare e imparare.","question":"Che cosa mi interessa o mi piace dell’attività mentre la sto svolgendo?","aliases":["intrinsic motivation","motivazione intrinseca","interesse","curiosità","piacere","gioco","incastri","autodeterminazione","self determination theory","SDT","cane","dog"],"note":"Poster definitivo fornito dall’autore nel ventunesimo gruppo di allegati, 12 ottobre 2026. Titolo, slogan e chiusura trascritti dall’originale. Il cane esplora un gioco a incastri. Fa parte del tema Motivazione e della sezione Mente, esperienza e relazione.","animal":"Cane","animals":["Cane"],"family":"Motivazione","section":"Mente, esperienza e relazione","authors":["Edward L. Deci","Richard M. Ryan"],"references":[{"label":"Richard M. Ryan e Edward L. Deci (2000) · Definizioni e testo integrale","citation":"Intrinsic and Extrinsic Motivations: Classic Definitions and New Directions. Contemporary Educational Psychology, 25(1), 54–67. DOI: 10.1006/ceps.1999.1020.","url":"https://www.selfdeterminationtheory.org/SDT/documents/2000_RyanDeci_IntExtDefs.pdf"},{"label":"Richard M. Ryan e Edward L. Deci (2000) · Autodeterminazione e testo integrale","citation":"Self-determination theory and the facilitation of intrinsic motivation, social development, and well-being. American Psychologist, 55(1), 68–78. DOI: 10.1037/0003-066X.55.1.68.","url":"https://www.selfdeterminationtheory.org/SDT/documents/2000_RyanDeci_SDT.pdf"}],"referenceOrigin":"Abbinamento a Deci e Ryan indicato da Tommaso Corona. Gli articoli del 2000 sono aggiunti come riferimenti specifici per le definizioni, i diversi gradi di autonomia e la cornice dell’autodeterminazione. I collegamenti aprono i testi integrali sul sito della teoria.","status":"definitive","order":91,"seriesNumber":92,"approvalBatch":21,"image":"assets/definitivi/intrinsic-motivation-original.png","original":"assets/definitivi/intrinsic-motivation-original.png","thumb":"assets/definitivi/intrinsic-motivation-thumb.webp","variants":[],"bookTitle":"Psiche & Thanatos","bookUrl":"https://www.amazon.it/dp/B0DVCC1HY6","topic":"Identità, rappresentazioni e motivazione"},{"id":"extrinsic-motivation","name":"Motivazione estrinseca","english":"Extrinsic motivation","sourceName":"88193.png","slogan":"La relazione sa usare il premio senza scambiarlo per il senso. Il limite si muove solo quando arrivano ricompensa, voto o applauso.","closing":"Anteprima dichiaratamente premiata del prossimo libro.","description":"La motivazione estrinseca orienta l’attività verso un risultato separabile dal suo svolgimento, come una ricompensa, un voto o un obiettivo ritenuto importante. Nel poster il cane salta verso un premio: è una metafora della regolazione esterna. Deci e Ryan distinguono forme estrinseche con diversi gradi di autonomia. L’obiettivo può essere imposto oppure riconosciuto e fatto proprio dalla persona; l’interiorizzazione può rendere la scelta più autonoma, pur conservandone la finalità strumentale.","example":"Il cane attraversa il cerchio mentre una mano mostra un bocconcino e il pubblico applaude. In un corso, una persona può impegnarsi per ottenere un attestato. Può anche scegliere di imparare una competenza perché la considera utile nel lavoro: l’esito cercato resta distinto dal piacere dell’attività, ma l’obiettivo è personalmente condiviso.","question":"Quale risultato sto cercando, e quanto riconosco questo obiettivo come una mia scelta?","aliases":["extrinsic motivation","motivazione estrinseca","ricompensa","premio","voto","applauso","regolazione esterna","interiorizzazione","regolazione identificata","regolazione integrata","autonomia","self determination theory","SDT","cane","dog"],"note":"Poster definitivo fornito dall’autore nel ventunesimo gruppo di allegati, 12 ottobre 2026. Titolo, slogan e chiusura trascritti dall’originale. Il cane attraversa un cerchio verso una ricompensa, con pubblico e trofeo. Fa parte del tema Motivazione e della sezione Mente, esperienza e relazione.","animal":"Cane","animals":["Cane"],"family":"Motivazione","section":"Mente, esperienza e relazione","authors":["Edward L. Deci","Richard M. Ryan"],"references":[{"label":"Richard M. Ryan e Edward L. Deci (2000) · Definizioni e testo integrale","citation":"Intrinsic and Extrinsic Motivations: Classic Definitions and New Directions. Contemporary Educational Psychology, 25(1), 54–67. DOI: 10.1006/ceps.1999.1020.","url":"https://www.selfdeterminationtheory.org/SDT/documents/2000_RyanDeci_IntExtDefs.pdf"},{"label":"Richard M. Ryan e Edward L. Deci (2000) · Autodeterminazione e testo integrale","citation":"Self-determination theory and the facilitation of intrinsic motivation, social development, and well-being. American Psychologist, 55(1), 68–78. DOI: 10.1037/0003-066X.55.1.68.","url":"https://www.selfdeterminationtheory.org/SDT/documents/2000_RyanDeci_SDT.pdf"}],"referenceOrigin":"Abbinamento a Deci e Ryan indicato da Tommaso Corona. Gli articoli del 2000 sono aggiunti come riferimenti specifici per le definizioni, i diversi gradi di autonomia e la cornice dell’autodeterminazione. I collegamenti aprono i testi integrali sul sito della teoria.","status":"definitive","order":92,"seriesNumber":93,"approvalBatch":21,"image":"assets/definitivi/extrinsic-motivation-original.png","original":"assets/definitivi/extrinsic-motivation-original.png","thumb":"assets/definitivi/extrinsic-motivation-thumb.webp","variants":[],"bookTitle":"Psiche & Thanatos","bookUrl":"https://www.amazon.it/dp/B0DVCC1HY6","topic":"Identità, rappresentazioni e motivazione"},{"id":"law-of-the-instrument","name":"Legge del martello","english":"Law of the instrument","sourceName":"88224.png","slogan":"La relazione cambia strumento quando cambia il problema. Il limite, se ha solo un martello, vede solo chiodi su cui battere.","closing":"Anteprima ironicamente martellante del prossimo libro.","description":"La legge del martello descrive la tendenza ad affrontare problemi diversi con lo strumento o il metodo che conosciamo meglio, anche quando sarebbe più adatto un altro approccio. La familiarità può influenzare anche il modo in cui definiamo il problema: cerchiamo ciò che il nostro strumento sa trattare e trascuriamo le caratteristiche che richiedono una soluzione diversa. La metafora invita a scegliere il metodo in funzione del problema; non significa che uno strumento familiare sia sempre inadeguato.","example":"Lo scimpanzé impugna un martello davanti a una vite, un nodo, una tazza rotta, una serratura bloccata, un cucchiaio piegato, un orologio delicato e un chiodo. Nella formazione, usare sempre una spiegazione frontale può portare a trattare allo stesso modo un dubbio sui contenuti, una difficoltà pratica e un conflitto nel gruppo, benché richiedano interventi diversi.","question":"Sto scegliendo lo strumento in base al problema, oppure sto adattando il problema allo strumento che so già usare?","aliases":["law of the instrument","legge dello strumento","legge del martello","martello di Maslow","Maslow hammer","golden hammer","martello d’oro","tutto è un chiodo","strumento familiare","metodo","scimpanzé","scimmia","chimpanzee"],"note":"Poster definitivo fornito dall’autore nel ventiduesimo gruppo di allegati, 13 ottobre 2026. Titolo, slogan e chiusura trascritti dall’originale. Lo scimpanzé è in un laboratorio con il cartello «TUTTO È UN CHIODO» e sette oggetti che richiedono strumenti diversi. Fa parte della sezione Bias cognitivi e del tema Decisione.","animal":"Scimpanzé","animals":["Scimpanzé","Scimmia"],"family":"Decisione","section":"Bias cognitivi","authors":["Abraham Kaplan","Abraham H. Maslow"],"references":[{"label":"Abraham Kaplan (1964) · Scheda della ristampa","citation":"The Conduct of Inquiry: Methodology for Behavioral Science. Chandler Publishing Company, p. 28. Il collegamento apre la scheda editoriale della ristampa del 1998.","url":"https://www.routledge.com/The-Conduct-of-Inquiry-Methodology-for-Behavioural-Science/Kaplan/p/book/9780765804488"},{"label":"Abraham Kaplan (1964) · Articolo con accesso a pagamento","citation":"The Age of the Symbol: A Philosophy of Library Education. The Library Quarterly, 34(4), 295–304, in particolare p. 303. DOI: 10.1086/619264. Il testo integrale richiede acquisto o accesso tramite abbonamento.","url":"https://doi.org/10.1086/619264"},{"label":"Abraham H. Maslow (1966) · Scheda bibliografica","citation":"The Psychology of Science: A Reconnaissance. Harper & Row, pp. 15–16. Il collegamento apre la scheda bibliografica su Google Books; la consultazione del contenuto dipende dall’anteprima disponibile.","url":"https://books.google.com/books/about/The_Psychology_of_Science.html?id=qitgAAAAMAAJ"}],"referenceOrigin":"Riferimenti teorici e storici aggiunti per documentare la provenienza della legge dello strumento e della metafora del martello. Le opere offrono riflessioni metodologiche sulla scelta degli strumenti e sul modo di definire i problemi. L’associazione a Kaplan e Maslow è un’integrazione bibliografica dell’atlante; i due autori non sono indicati nel poster.","status":"definitive","order":93,"seriesNumber":94,"approvalBatch":22,"image":"assets/definitivi/law-of-the-instrument-original.png","original":"assets/definitivi/law-of-the-instrument-original.png","thumb":"assets/definitivi/law-of-the-instrument-thumb.webp","variants":[],"referenceHeading":"RIFERIMENTI TEORICI E STORICI","topic":"Decisione"},{"id":"paradoxical-stratagem","name":"Stratagemma paradossale","english":"Paradoxical stratagem","sourceName":"88226.png","slogan":"La relazione comprende ciò che alimenta il problema e lo usa per modificarlo. Il limite tenta sempre di spegnerlo nello stesso modo.","closing":"Anteprima paradossalmente strategica del prossimo libro.","description":"Nell’approccio strategico di Giorgio Nardone, lo stratagemma paradossale impiega una dinamica che sembra contraria all’obiettivo per modificare il funzionamento del problema. Si parte dall’osservazione delle tentate soluzioni: alcuni sforzi ripetuti possono contribuire a mantenere ciò che vorrebbero risolvere. Il paradosso cambia il modo in cui quella dinamica viene utilizzata, il suo contesto o la sua funzione. Nel poster, «aggiungere legna per spegnere il fuoco» è una metafora di questa inversione strategica. La scelta dell’intervento si basa sul funzionamento specifico del problema e sugli effetti osservati.","example":"In una riunione, ogni tentativo di vietare le obiezioni può far crescere l’opposizione. Dedicare uno spazio concordato a raccoglierle e trasformarle in questioni concrete può usare la stessa dinamica per cambiare l’interazione. L’esempio mostra il passaggio dalla soppressione delle critiche al loro impiego nel lavoro comune; gli effetti vanno verificati nel contesto.","question":"Quale tentata soluzione sta alimentando il problema, e come potrei cambiare la funzione di quella stessa dinamica?","aliases":["stratagemma paradossale","paradoxical stratagem","paradosso","aggiungere legna per spegnere il fuoco","spegnere il fuoco aggiungendo la legna","tentate soluzioni","logiche non ordinarie","cambiamento strategico","psicologia strategica","terapia breve strategica","canide","orso","procione","cervo","lepre"],"note":"Poster definitivo fornito dall’autore nel ventitreesimo gruppo di allegati, 13 ottobre 2026. Titolo, slogan e chiusura trascritti dall’originale. Un canide avvicina un ramo acceso al fuoco mentre orso, procione, cervo e lepre osservano. La scena è una metafora dello stratagemma paradossale. Inserito in Mente, esperienza e relazione, nel tema Psicologia strategica.","animal":"Canide · Orso · Procione · Cervo · Lepre","animals":["Canide","Orso","Procione","Cervo","Lepre"],"family":"Psicologia strategica","section":"Psicologia Strategica","authors":["Giorgio Nardone","Paul Watzlawick"],"referenceHeading":"OPERE DI NARDONE E APPROFONDIMENTI","references":[{"label":"Giorgio Nardone (2003) · Cavalcare la propria tigre","citation":"Cavalcare la propria tigre. Gli stratagemmi nelle arti marziali ovvero come risolvere problemi difficili attraverso soluzioni semplici. Ponte alle Grazie. Il link apre la scheda ufficiale del volume presso il Centro di Terapia Strategica, con presentazione e rimando all’ebook.","url":"https://www.centroditerapiastrategica.com/pubblicazione/cavalcare-la-propria-tigregli-stratagemmi-nelle-arti-marziali-ovvero-come-risolvere-problemi-difficili-attraverso-soluzioni-semplici/"},{"label":"Giorgio Nardone e Paul Watzlawick (1990) · L’arte del cambiamento","citation":"L’arte del cambiamento. Manuale di terapia strategica e ipnosi senza trance. Ponte alle Grazie. Il link apre la scheda ufficiale del volume presso il Centro di Terapia Strategica, per la cornice teorica e operativa del cambiamento.","url":"https://www.centroditerapiastrategica.com/pubblicazione/larte-del-cambiamentola-soluzione-dei-problemi-psicologici-personali-e-interpersonali-in-tempi-brevi/"},{"label":"Giorgio Nardone · Logica strategica e problem solving, testo consultabile","citation":"Presentazione del modello sul sito ufficiale di Giorgio Nardone. Il testo è leggibile online e illustra le tentate soluzioni, le logiche non ordinarie e la tecnica del come peggiorare.","url":"https://giorgionardone.com/it/formazione-soluzione-dei-problemi/"}],"referenceOrigin":"Collegamento ai lavori di Giorgio Nardone richiesto da Tommaso Corona. Le due opere sono riferimenti teorici e applicativi; i link aprono le schede ufficiali dei libri. L’approfondimento sul sito di Nardone è invece consultabile direttamente. Paul Watzlawick è incluso come coautore di L’arte del cambiamento. La lettura della scena e l’esempio della riunione sono elaborazioni formative dell’atlante, distinte dagli esempi clinici delle opere.","status":"definitive","order":94,"seriesNumber":95,"approvalBatch":23,"image":"assets/definitivi/paradoxical-stratagem-original.png","original":"assets/definitivi/paradoxical-stratagem-original.png","thumb":"assets/definitivi/paradoxical-stratagem-thumb.webp","variants":[],"topic":"Modelli e strategie"},{"id":"deindividuation","name":"Deindividuazione","english":"Deindividuation","sourceName":"88259.png","slogan":"La relazione mantiene il senso di sé anche dentro il gruppo. Il limite si perde nella massa e dimentica la responsabilità personale.","closing":"Anteprima anonimamente collettiva del prossimo libro.","description":"Nella formulazione classica, la deindividuazione descrive una riduzione dell’attenzione alla propria identità individuale e della percezione di essere riconoscibili e personalmente valutati quando si è immersi in un gruppo. Nel poster, l’eccitazione collettiva e i foulard uguali accompagnano comportamenti che la singola iena, isolata, appare meno propensa a compiere. Le ricerche successive danno rilievo alle norme del contesto e all’identità di gruppo: ciò che il gruppo approva può orientare il comportamento. La scena rappresenta una possibile dinamica aggressiva; l’appartenenza al gruppo può anche sostenere cooperazione e aiuto, secondo le norme condivise.","example":"Le iene con il foulard rosso circondano una lepre impaurita, gridano e ridono. Nel riquadro, una iena presa individualmente appare esitante: il confronto rende visibile il cambiamento dentro il gruppo. In una situazione analoga, chi si unisce a una derisione collettiva può sentirsi meno esposto come singolo e seguire ciò che gli altri stanno approvando.","question":"Se fossi riconoscibile e dovessi rispondere personalmente di ciò che sto facendo, agirei nello stesso modo?","aliases":["deindividuazione","deindividuation","psicologia delle folle","psicologia delle masse","anonimato","responsabilità personale","identità di gruppo","norme del gruppo","eccitazione collettiva","foulard rosso","iena","iene","hyena","lepre"],"note":"Poster definitivo fornito dall’autore nel ventiquattresimo gruppo di allegati, 13 ottobre 2026. Titolo, slogan e chiusura trascritti dall’originale. Le iene indossano foulard rossi e circondano una lepre; una singola iena esitante è rappresentata nel riquadro. La scena riguarda un gruppo in presenza. Inserito nella sezione Mente, esperienza e relazione e nel tema Relazione.","animal":"Iene · Lepre","animals":["Iena","Lepre"],"family":"Relazione","section":"Mente, esperienza e relazione","authors":["Gustave Le Bon","Sigmund Freud","Philip G. Zimbardo","Tom Postmes","Russell Spears"],"referenceHeading":"RIFERIMENTI STORICI E RICERCA","references":[{"label":"Gustave Le Bon (1895) · Psicologia delle folle, testo originale","citation":"Psychologie des foules. Félix Alcan. Riferimento storico sulla psicologia delle folle, la suggestione e il contagio. Il link apre il testo completo in francese dell’edizione del 1895 su Wikisource.","url":"https://fr.wikisource.org/wiki/Psychologie_des_foules/Texte_entier"},{"label":"Sigmund Freud (1921) · Psicologia delle masse e analisi dell’Io","citation":"Massenpsychologie und Ich-Analyse. Internationaler Psychoanalytischer Verlag. Riferimento storico su identificazione e legami fra i membri del gruppo. Il link apre Group Psychology and the Analysis of the Ego, traduzione inglese di James Strachey del 1922, consultabile integralmente su Project Gutenberg.","url":"https://www.gutenberg.org/files/35877/35877-h/35877-h.htm"},{"label":"Philip G. Zimbardo · Il modello classico della deindividuazione","citation":"The human choice: Individuation, reason, and order versus deindividuation, impulse, and chaos. In W. J. Arnold e D. Levine (a cura di), 1969 Nebraska Symposium on Motivation, pp. 237–307. University of Nebraska Press. Il link apre la bibliografia dell’autore su Social Psychology Network, dove il contributo è registrato nel 1970.","url":"https://zimbardo.socialpsychology.org/publications"},{"label":"Tom Postmes e Russell Spears (1998) · Norme del gruppo e revisione delle evidenze","citation":"Deindividuation and antinormative behavior: A meta-analysis. Psychological Bulletin, 123(3), 238–259. Il link apre la scheda dell’articolo e l’abstract nel portale dell’Università di Groningen, per il ruolo delle norme specifiche della situazione.","url":"https://research.rug.nl/en/publications/deindividuation-and-antinormative-behavior-a-meta-analysis/"}],"referenceOrigin":"Le Bon, Freud e Zimbardo sono abbinamenti richiesti da Tommaso Corona. Le Bon e Freud sono presentati come antecedenti storici sulla psicologia collettiva; Zimbardo come riferimento per il modello classico della deindividuazione. La meta-analisi di Postmes e Spears è un’integrazione bibliografica dell’atlante per distinguere la scena aggressiva dal più ampio ruolo delle norme del gruppo. Le quattro fonti appartengono a cornici teoriche e periodi differenti. I link indicano lingua e tipo di accesso.","status":"definitive","order":95,"seriesNumber":96,"approvalBatch":24,"image":"assets/definitivi/deindividuation-original.png","original":"assets/definitivi/deindividuation-original.png","thumb":"assets/definitivi/deindividuation-thumb.webp","variants":[],"bookTitle":"Psiche & Thanatos","bookUrl":"https://www.amazon.it/dp/B0DVCC1HY6","topic":"Relazioni, legami e dinamiche sociali"},{"id":"moral-disengagement-conduct","name":"Disimpegno morale · Ristrutturazione cognitiva del comportamento","english":"Moral disengagement · Cognitive restructuring of behavior","sourceName":"88720.png","animal":"Volpe · Galline","animals":["Volpe","Gallina"],"family":"Disimpegno morale","section":"Mente, esperienza e relazione","slogan":"La relazione chiama le cose con il loro nome. Il limite cambia il racconto finché il comportamento sembra giusto.","closing":"Anteprima fin troppo giustificata del prossimo libro.","description":"Questo raggruppamento modifica il significato attribuito alla condotta dannosa. La giustificazione morale la presenta al servizio di uno scopo ritenuto buono; l’etichettamento eufemistico usa parole che ne attenuano la gravità; il confronto vantaggioso la accosta a un comportamento peggiore, facendola apparire più accettabile. Nel modello di Bandura queste reinterpretazioni possono allentare l’autocensura morale mentre il comportamento lesivo resta in atto.","example":"La volpe sottrae le uova e cambia il racconto nelle tre scene: «Lo faccio per il bene dei miei piccoli» richiama la giustificazione morale; «Non è un furto, è una redistribuzione» mostra l’etichettamento eufemistico; «Altri avrebbero portato via tutto il pollaio» mostra il confronto vantaggioso.","question":"Come descriverei ciò che sto facendo senza il fine nobile, le parole rassicuranti o il confronto con qualcosa di peggiore?","aliases":["disimpegno morale","moral disengagement","Ristrutturazione cognitiva del comportamento","Giustificazione morale","Etichettamento eufemistico","Confronto vantaggioso","locus comportamentale","moral justification","euphemistic labeling","advantageous comparison","lo faccio per il bene dei miei piccoli","non è un furto","redistribuzione","pollaio"],"note":"Poster definitivo fornito dall’autore nel venticinquesimo gruppo di allegati, 13 ottobre 2026. Tavola 1 di quattro sul disimpegno morale di Bandura. Titolo, slogan e chiusura trascritti dall’originale. La volpe prende le uova dal pollaio nelle tre scene, ciascuna dedicata a uno dei tre meccanismi. La scheda appartiene al tema Disimpegno morale nella sezione Mente, esperienza e relazione.","authors":["Albert Bandura"],"references":[{"label":"Albert Bandura (1999) · I meccanismi del disimpegno morale","citation":"Moral Disengagement in the Perpetration of Inhumanities. Personality and Social Psychology Review, 3(3), 193–209. DOI: 10.1207/s15327957pspr0303_3. Il link apre la pagina dell’articolo presso l’editore; l’accesso al testo integrale segue le condizioni della rivista.","url":"https://doi.org/10.1207/s15327957pspr0303_3"},{"label":"Albert Bandura · Disimpegno morale, anteprima in italiano","citation":"Disimpegno morale. Come facciamo del male continuando a vivere bene. Edizioni Erickson, capitolo 2: I meccanismi del disimpegno morale. Il link apre l’anteprima editoriale in PDF, con l’indice e alcuni estratti del volume.","url":"https://static.erickson.it/prod/files/ItemVariant/itemvariant_sfoglialibro/5189_9788859014324_x828_disimpegno-morale.pdf"},{"label":"Albert Bandura · Presentazione e bibliografia dell’autore","citation":"Moral Disengagement. Testo consultabile sul sito di Albert Bandura, con presentazione del processo e riferimenti ai suoi lavori teorici ed empirici.","url":"https://albertbandura.com/albert-bandura-moral-disengagement.html"}],"referenceHeading":"IL MODELLO DI BANDURA E I SUOI LAVORI","referenceOrigin":"Abbinamento al disimpegno morale di Albert Bandura indicato dall’autore. Le quattro tavole raggruppano gli otto meccanismi nei loci del comportamento, dell’agency, degli effetti e della vittima; sono ambiti di intervento dell’autoregolazione morale che possono interagire. L’articolo del 1999, l’anteprima italiana e la presentazione sul sito di Bandura sono aggiunti come riferimenti specifici. Le scene e le battute sono metafore editoriali della serie.","status":"definitive","order":96,"seriesNumber":97,"approvalBatch":25,"image":"assets/definitivi/moral-disengagement-conduct-original.png","original":"assets/definitivi/moral-disengagement-conduct-original.png","thumb":"assets/definitivi/moral-disengagement-conduct-thumb.webp","variants":[],"bookTitle":"Psiche & Thanatos","bookUrl":"https://www.amazon.it/dp/B0DVCC1HY6","topic":"Relazioni, legami e dinamiche sociali"},{"id":"moral-disengagement-responsibility","name":"Disimpegno morale · Riduzione della responsabilità personale","english":"Moral disengagement · Reduction of personal responsibility","sourceName":"88725.png","animal":"Scimmie · Gufo","animals":["Scimmia","Gufo"],"family":"Disimpegno morale","section":"Mente, esperienza e relazione","slogan":"La relazione riconosce la propria parte anche nel gruppo. Il limite si alleggerisce dicendo: me l’hanno ordinato, lo fanno tutti.","closing":"Anteprima convenientemente deresponsabilizzata del prossimo libro.","description":"Il disimpegno può riguardare il riconoscimento del proprio ruolo nell’azione. Nello spostamento della responsabilità la persona attribuisce la decisione a un’autorità o a chi impartisce ordini. Nella diffusione della responsabilità diluisce il proprio contributo fra tutti i partecipanti. Questi due meccanismi possono ridurre l’autocensura presentando la propria partecipazione come poco rilevante o dipendente da altri.","example":"Le scimmie sono tra le stoviglie rotte e indicano il gufo o gli altri membri del gruppo. «Ho semplicemente eseguito gli ordini» rappresenta lo spostamento della responsabilità; «Lo stavano facendo tutti» rappresenta la sua diffusione. La scena mette a confronto i due modi di allontanare da sé il riconoscimento della propria parte.","question":"Qual è stata la mia parte concreta nell’azione, anche in presenza di ordini o di altre persone?","aliases":["disimpegno morale","moral disengagement","Riduzione della responsabilità personale","Spostamento della responsabilità","Diffusione della responsabilità","locus dell’agency","displacement of responsibility","diffusion of responsibility","ho semplicemente eseguito gli ordini","lo stavano facendo tutti","deresponsabilizzazione","obbedienza"],"note":"Poster definitivo fornito dall’autore nel venticinquesimo gruppo di allegati, 13 ottobre 2026. Tavola 2 di quattro sul disimpegno morale di Bandura. Titolo, slogan e chiusura trascritti dall’originale. Le scimmie indicano il gufo o gli altri partecipanti fra stoviglie rotte e frutta rovesciata. La scheda appartiene al tema Disimpegno morale nella sezione Mente, esperienza e relazione.","authors":["Albert Bandura"],"references":[{"label":"Albert Bandura (1999) · I meccanismi del disimpegno morale","citation":"Moral Disengagement in the Perpetration of Inhumanities. Personality and Social Psychology Review, 3(3), 193–209. DOI: 10.1207/s15327957pspr0303_3. Il link apre la pagina dell’articolo presso l’editore; l’accesso al testo integrale segue le condizioni della rivista.","url":"https://doi.org/10.1207/s15327957pspr0303_3"},{"label":"Albert Bandura · Disimpegno morale, anteprima in italiano","citation":"Disimpegno morale. Come facciamo del male continuando a vivere bene. Edizioni Erickson, capitolo 2: I meccanismi del disimpegno morale. Il link apre l’anteprima editoriale in PDF, con l’indice e alcuni estratti del volume.","url":"https://static.erickson.it/prod/files/ItemVariant/itemvariant_sfoglialibro/5189_9788859014324_x828_disimpegno-morale.pdf"},{"label":"Albert Bandura · Presentazione e bibliografia dell’autore","citation":"Moral Disengagement. Testo consultabile sul sito di Albert Bandura, con presentazione del processo e riferimenti ai suoi lavori teorici ed empirici.","url":"https://albertbandura.com/albert-bandura-moral-disengagement.html"}],"referenceHeading":"IL MODELLO DI BANDURA E I SUOI LAVORI","referenceOrigin":"Abbinamento al disimpegno morale di Albert Bandura indicato dall’autore. Le quattro tavole raggruppano gli otto meccanismi nei loci del comportamento, dell’agency, degli effetti e della vittima; sono ambiti di intervento dell’autoregolazione morale che possono interagire. L’articolo del 1999, l’anteprima italiana e la presentazione sul sito di Bandura sono aggiunti come riferimenti specifici. Le scene e le battute sono metafore editoriali della serie.","status":"definitive","order":97,"seriesNumber":98,"approvalBatch":25,"image":"assets/definitivi/moral-disengagement-responsibility-original.png","original":"assets/definitivi/moral-disengagement-responsibility-original.png","thumb":"assets/definitivi/moral-disengagement-responsibility-thumb.webp","variants":[],"bookTitle":"Psiche & Thanatos","bookUrl":"https://www.amazon.it/dp/B0DVCC1HY6","topic":"Relazioni, legami e dinamiche sociali"},{"id":"moral-disengagement-consequences","name":"Disimpegno morale · Minimizzazione delle conseguenze","english":"Moral disengagement · Minimization of consequences","sourceName":"88724.png","animal":"Cinghiale","animals":["Cinghiale"],"family":"Disimpegno morale","section":"Mente, esperienza e relazione","slogan":"La relazione guarda anche il danno prodotto. Il limite si tranquillizza dicendo che non è successo nulla di grave.","closing":"Anteprima comodamente minimizzata del prossimo libro.","description":"Il disimpegno morale può agire sulla percezione degli effetti dell’azione: il danno viene trascurato, distorto o minimizzato. La persona può così attenuare il peso morale della propria condotta senza confrontarsi pienamente con ciò che ha prodotto. Il poster concentra l’attenzione sul divario fra la frase rassicurante del cinghiale e le conseguenze visibili intorno a lui.","example":"Il cinghiale alza le zampe davanti al banco danneggiato e alla frutta schiacciata, dicendo «Non è poi così grave!». La sua valutazione riduce la portata di un danno che la scena continua a mostrare. Un esempio quotidiano è liquidare una conseguenza con «non è successo niente» prima di ascoltare chi l’ha subita.","question":"Quali conseguenze sto riducendo nel racconto, e che cosa direbbe chi le ha subite?","aliases":["disimpegno morale","moral disengagement","Minimizzazione delle conseguenze","Distorsione o minimizzazione delle conseguenze","locus degli effetti","distorting consequences","minimizing consequences","negazione del danno","non è poi così grave","noncuranza degli effetti lesivi","frutta"],"note":"Poster definitivo fornito dall’autore nel venticinquesimo gruppo di allegati, 13 ottobre 2026. Tavola 3 di quattro sul disimpegno morale di Bandura. Titolo, slogan e chiusura trascritti dall’originale. Il cinghiale minimizza davanti a un banco danneggiato e alla frutta schiacciata. La scheda appartiene al tema Disimpegno morale nella sezione Mente, esperienza e relazione.","authors":["Albert Bandura"],"references":[{"label":"Albert Bandura (1999) · I meccanismi del disimpegno morale","citation":"Moral Disengagement in the Perpetration of Inhumanities. Personality and Social Psychology Review, 3(3), 193–209. DOI: 10.1207/s15327957pspr0303_3. Il link apre la pagina dell’articolo presso l’editore; l’accesso al testo integrale segue le condizioni della rivista.","url":"https://doi.org/10.1207/s15327957pspr0303_3"},{"label":"Albert Bandura · Disimpegno morale, anteprima in italiano","citation":"Disimpegno morale. Come facciamo del male continuando a vivere bene. Edizioni Erickson, capitolo 2: I meccanismi del disimpegno morale. Il link apre l’anteprima editoriale in PDF, con l’indice e alcuni estratti del volume.","url":"https://static.erickson.it/prod/files/ItemVariant/itemvariant_sfoglialibro/5189_9788859014324_x828_disimpegno-morale.pdf"},{"label":"Albert Bandura · Presentazione e bibliografia dell’autore","citation":"Moral Disengagement. Testo consultabile sul sito di Albert Bandura, con presentazione del processo e riferimenti ai suoi lavori teorici ed empirici.","url":"https://albertbandura.com/albert-bandura-moral-disengagement.html"}],"referenceHeading":"IL MODELLO DI BANDURA E I SUOI LAVORI","referenceOrigin":"Abbinamento al disimpegno morale di Albert Bandura indicato dall’autore. Le quattro tavole raggruppano gli otto meccanismi nei loci del comportamento, dell’agency, degli effetti e della vittima; sono ambiti di intervento dell’autoregolazione morale che possono interagire. L’articolo del 1999, l’anteprima italiana e la presentazione sul sito di Bandura sono aggiunti come riferimenti specifici. Le scene e le battute sono metafore editoriali della serie.","status":"definitive","order":98,"seriesNumber":99,"approvalBatch":25,"image":"assets/definitivi/moral-disengagement-consequences-original.png","original":"assets/definitivi/moral-disengagement-consequences-original.png","thumb":"assets/definitivi/moral-disengagement-consequences-thumb.webp","variants":[],"bookTitle":"Psiche & Thanatos","bookUrl":"https://www.amazon.it/dp/B0DVCC1HY6","topic":"Relazioni, legami e dinamiche sociali"},{"id":"moral-disengagement-victim","name":"Disimpegno morale · Rappresentazione della vittima","english":"Moral disengagement · Representation of the victim","sourceName":"88726.png","animal":"Lupi · Coniglio","animals":["Lupo","Coniglio"],"family":"Disimpegno morale","section":"Mente, esperienza e relazione","slogan":"La relazione riconosce l’altro come soggetto. Il limite lo svaluta o lo accusa, così smette di sentirne il peso.","closing":"Anteprima freddamente giustificata del prossimo libro.","description":"Questo raggruppamento riguarda il modo in cui viene rappresentato chi subisce il danno. La deumanizzazione svaluta la vittima e ne oscura le qualità e il valore come soggetto. L’attribuzione della colpa alla vittima presenta invece il danno come qualcosa che avrebbe provocato o meritato. I due meccanismi possono rendere più facile giustificare la condotta lesiva e ridurre l’autocensura di chi la compie.","example":"I lupi circondano un coniglio impaurito. «Sei un microbo!» rappresenta la deumanizzazione; «Se l’è cercata!» attribuisce la colpa alla vittima. Il poster mostra due racconti differenti che distolgono l’attenzione dall’azione di chi produce il danno e dal vissuto di chi lo subisce.","question":"Sto riconoscendo l’altro come soggetto, oppure lo sto svalutando o accusando per alleggerire il peso della mia azione?","aliases":["disimpegno morale","moral disengagement","Rappresentazione della vittima","Deumanizzazione","Attribuzione della colpa alla vittima","locus della vittima","dehumanization","attribution of blame","victim blaming","colpevolizzazione della vittima","disumanizzazione","sei un microbo","se l’è cercata"],"note":"Poster definitivo fornito dall’autore nel venticinquesimo gruppo di allegati, 13 ottobre 2026. Tavola 4 di quattro sul disimpegno morale di Bandura. Titolo, slogan e chiusura trascritti dall’originale. I lupi svalutano e accusano un coniglio impaurito nelle due nuvolette e nei cartelli del poster. La scheda appartiene al tema Disimpegno morale nella sezione Mente, esperienza e relazione.","authors":["Albert Bandura"],"references":[{"label":"Albert Bandura (1999) · I meccanismi del disimpegno morale","citation":"Moral Disengagement in the Perpetration of Inhumanities. Personality and Social Psychology Review, 3(3), 193–209. DOI: 10.1207/s15327957pspr0303_3. Il link apre la pagina dell’articolo presso l’editore; l’accesso al testo integrale segue le condizioni della rivista.","url":"https://doi.org/10.1207/s15327957pspr0303_3"},{"label":"Albert Bandura · Disimpegno morale, anteprima in italiano","citation":"Disimpegno morale. Come facciamo del male continuando a vivere bene. Edizioni Erickson, capitolo 2: I meccanismi del disimpegno morale. Il link apre l’anteprima editoriale in PDF, con l’indice e alcuni estratti del volume.","url":"https://static.erickson.it/prod/files/ItemVariant/itemvariant_sfoglialibro/5189_9788859014324_x828_disimpegno-morale.pdf"},{"label":"Albert Bandura · Presentazione e bibliografia dell’autore","citation":"Moral Disengagement. Testo consultabile sul sito di Albert Bandura, con presentazione del processo e riferimenti ai suoi lavori teorici ed empirici.","url":"https://albertbandura.com/albert-bandura-moral-disengagement.html"}],"referenceHeading":"IL MODELLO DI BANDURA E I SUOI LAVORI","referenceOrigin":"Abbinamento al disimpegno morale di Albert Bandura indicato dall’autore. Le quattro tavole raggruppano gli otto meccanismi nei loci del comportamento, dell’agency, degli effetti e della vittima; sono ambiti di intervento dell’autoregolazione morale che possono interagire. L’articolo del 1999, l’anteprima italiana e la presentazione sul sito di Bandura sono aggiunti come riferimenti specifici. Le scene e le battute sono metafore editoriali della serie.","status":"definitive","order":99,"seriesNumber":100,"approvalBatch":25,"image":"assets/definitivi/moral-disengagement-victim-original.png","original":"assets/definitivi/moral-disengagement-victim-original.png","thumb":"assets/definitivi/moral-disengagement-victim-thumb.webp","variants":[],"bookTitle":"Psiche & Thanatos","bookUrl":"https://www.amazon.it/dp/B0DVCC1HY6","topic":"Relazioni, legami e dinamiche sociali"},{"id":"tall-poppy-syndrome","name":"Sindrome del papavero alto","english":"Tall poppy syndrome","sourceName":"88835.png","animal":"Talpa giardiniera","animals":["Talpa"],"family":"Relazione","section":"Mente, esperienza e relazione","slogan":"La relazione riconosce il valore di chi emerge. Il limite preferisce abbassarlo anziché cercare di crescere.","closing":"Anteprima ingiustamente potata del prossimo libro.","description":"L’espressione descrive la tendenza a sminuire o ostacolare chi si distingue per risultati, capacità o visibilità: il «papavero alto» viene ricondotto all’altezza degli altri. Il confronto sociale, l’invidia e le valutazioni su quanto un successo sia meritato aiutano a leggere queste reazioni, che dipendono anche dal contesto. Il termine «sindrome» è usato come metafora sociale, non come diagnosi clinica; una critica fondata a un comportamento resta distinta dalla svalutazione di una persona perché emerge.","example":"Una talpa giardiniera con metro e cesoie si prepara a tagliare il papavero più alto, mentre le altre talpe espongono «Chi si crede di essere?» e «Qui dobbiamo essere tutti uguali!». Nella scena, il trullo fa da sfondo al tentativo di livellare ciò che emerge. Un esempio quotidiano è ridicolizzare il buon risultato di un collega senza discuterne il merito, invece di riconoscerlo e imparare dalla sua esperienza.","question":"Sto valutando un risultato con criteri concreti, oppure sto cercando di ridimensionare chi emerge?","aliases":["tall poppy syndrome","sindrome del papavero alto","papaveri alti","cutting down the tall poppy","confronto sociale","invidia","svalutazione del successo","livellamento","merito","chi si crede di essere","qui dobbiamo essere tutti uguali","trullo","Norman Feather","Norman T. Feather"],"note":"Poster definitivo fornito dall’autore nel ventiseiesimo gruppo di allegati, 14 ottobre 2026. Titolo, slogan e chiusura trascritti dall’originale. La talpa giardiniera, le cesoie e il metro rappresentano il tentativo di abbassare il papavero che emerge; sullo sfondo compare un trullo. La scheda è nel tema Relazione della sezione Mente, esperienza e relazione. Il PNG originale 2305×4096 è conservato senza modifiche. Identificazione dell’animale corretta su indicazione dell’autore il 14 ottobre 2026.","authors":["N. T. Feather","R. E. Volkmer","I. R. McKee"],"references":[{"label":"N. T. Feather (1989) · Studi sul papavero alto","citation":"Attitudes towards the high achiever: The fall of the tall poppy. Australian Journal of Psychology, 41(3), 239–267. DOI: 10.1080/00049538908260088. Il link apre la scheda istituzionale di Flinders University, con abstract e citazione; il testo integrale segue le condizioni dell’editore.","url":"https://researchnow.flinders.edu.au/en/publications/attitudes-towards-the-high-achiever-the-fall-of-the-tall-poppy/"},{"label":"Feather, Volkmer e McKee (1991) · Successo e merito percepito","citation":"Attitudes towards high achievers in public life: Attributions, deservingness, personality, and affect. Australian Journal of Psychology, 43(2), 85–91. DOI: 10.1080/00049539108259105. La pagina editoriale presenta l’abstract; l’accesso al testo integrale segue le condizioni della rivista.","url":"https://doi.org/10.1080/00049539108259105"},{"label":"N. T. Feather (1994) · Quadro teorico e ricerca","citation":"Attitudes toward high achievers and reactions to their fall: Theory and research concerning tall poppies. Advances in Experimental Social Psychology, 26, 1–73. DOI: 10.1016/S0065-2601(08)60151-3. Il link apre la scheda istituzionale di Flinders University, con sintesi del programma di ricerca e riferimento al capitolo.","url":"https://researchnow.flinders.edu.au/en/publications/attitudes-toward-high-achievers-and-reactions-to-their-fall-theor/"}],"referenceHeading":"STUDI SUL PAPAVERO ALTO","referenceOrigin":"Feather e i suoi coautori sono un’integrazione bibliografica per inquadrare il fenomeno sociale rappresentato. Le ricerche documentano atteggiamenti verso chi ha successo e reazioni alla sua caduta, considerando anche valori e merito percepito. Il papavero, la talpa giardiniera e il trullo appartengono alla metafora editoriale della serie; non sono categorie scientifiche né indicazioni diagnostiche.","status":"definitive","order":100,"seriesNumber":101,"approvalBatch":26,"image":"assets/definitivi/tall-poppy-syndrome-original.png","original":"assets/definitivi/tall-poppy-syndrome-original.png","thumb":"assets/definitivi/tall-poppy-syndrome-thumb.webp","variants":[],"topic":"Identità, rappresentazioni e motivazione"},{"id":"pareidolia","name":"Pareidolia","english":"Pareidolia","sourceName":"89249.png","animal":"Uccello dal piumaggio a ventaglio","animals":["Uccello"],"family":"Informazione","section":"Mente, esperienza e relazione","slogan":"La relazione distingue ciò che osserva da ciò che la mente riconosce. Il limite vede un volto anche dove ci sono soltanto forme.","closing":"Anteprima apparentemente riconoscibile del prossimo libro.","description":"La pareidolia consiste nel riconoscere forme familiari in configurazioni che non rappresentano davvero ciò che vi vediamo. Nella pareidolia facciale, pochi indizi possono attivare rapidamente i processi con cui rileviamo i volti; anche aspettative e interpretazioni contribuiscono a dare forma a ciò che percepiamo. È un fenomeno comune della percezione. La scheda sull’apofenia riguarda l’attribuzione di legami e significati fra elementi; qui l’attenzione è sulla configurazione visiva che viene riconosciuta come un volto.","example":"L’uccello mostra il piumaggio rosso disposto a ventaglio: due grandi ocelli ricordano gli occhi di un volto, e l’osservatore esclama «Ma… mi sta fissando?!». I riquadri separano ciò che percepiamo, «Un volto che ci osserva», da ciò che è raffigurato, «Solo piume e colori». Nella vita quotidiana accade quando vediamo una faccia nelle venature di un tronco o in una presa elettrica: possiamo riconoscere la somiglianza sapendo che l’oggetto resta quello che è.","question":"Quali dettagli vedo davvero, e quali sto unendo per riconoscervi un volto?","aliases":["pareidolia facciale","face pareidolia","illusione pareidolitica","volti nelle forme","volti negli oggetti","riconoscimento dei volti","ocelli","piumaggio rosso","mi sta fissando","solo piume e colori","trullo"],"note":"Poster definitivo fornito dall’autore nel ventisettesimo gruppo di allegati, 16 ottobre 2026. Titolo, slogan e chiusura trascritti dall’originale. L’uccello rosso dal piumaggio a ventaglio e i motivi circolari sulle piume costruiscono la metafora di un volto apparente, osservato da un piccolo mammifero; sullo sfondo compare un trullo. Il PNG originale 2305×4096 è conservato senza modifiche. La scheda appartiene al tema Informazione della sezione Mente, esperienza e relazione. Identificazione dell’animale corretta su indicazione dell’autore il 16 ottobre 2026; l’animale è indicato in forma descrittiva.","authors":["Susan G. Wardle","Jessica Taubert","Lina Teichmann","Chris I. Baker","Jiangang Liu","Jun Li","Lu Feng","Ling Li","Jie Tian","Kang Lee"],"references":[{"label":"Wardle e colleghi (2020) · La percezione rapida dei volti apparenti","citation":"Wardle, S. G., Taubert, J., Teichmann, L., & Baker, C. I. (2020). Rapid and dynamic processing of face pareidolia in the human brain. Nature Communications, 11, 4518. DOI: 10.1038/s41467-020-18325-8. Studio sul riconoscimento di volti illusori negli oggetti. Il link apre il testo integrale open access nella rivista.","url":"https://www.nature.com/articles/s41467-020-18325-8"},{"label":"Liu e colleghi (2014) · Aspettative e riconoscimento dei volti","citation":"Liu, J., Li, J., Feng, L., Li, L., Tian, J., & Lee, K. (2014). Seeing Jesus in toast: Neural and behavioral correlates of face pareidolia. Cortex, 53, 60–77. DOI: 10.1016/j.cortex.2014.01.013. Studio sul contributo delle aspettative al riconoscimento di volti in immagini prive di volti reali. Il link apre il manoscritto dell’autore disponibile integralmente in PubMed Central.","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC3980010/"}],"referenceHeading":"STUDI SULLA PAREIDOLIA","referenceOrigin":"I lavori di Wardle e colleghi e di Liu e colleghi sono integrazioni bibliografiche per inquadrare il riconoscimento dei volti e il contributo delle aspettative. Il piumaggio, il volto apparente e la reazione dell’osservatore sono una metafora editoriale della serie; gli studi citati non riguardano gli animali o la scena del poster.","status":"definitive","order":101,"seriesNumber":102,"approvalBatch":27,"image":"assets/definitivi/pareidolia-original.png","original":"assets/definitivi/pareidolia-original.png","thumb":"assets/definitivi/pareidolia-thumb.webp","variants":[],"topic":"Percezione, coscienza e memoria"},{"id":"persuasion-reciprocity","name":"Reciprocità","english":"Reciprocity","sourceName":"89977.png","animal":"Volpe · Lupo","animals":["Volpe","Lupo"],"slogan":"La relazione riconosce il valore di un favore senza trasformarlo in un debito. Il limite si sente obbligato a ricambiare anche quando non vorrebbe.","closing":"Anteprima paradossalmente strategica del prossimo libro.","description":"Ricevere un favore, un regalo o un aiuto può creare una spinta a ricambiare. Nel principio di reciprocità descritto da Cialdini, questa pressione può influenzare una decisione anche quando il favore non era stato richiesto. La gratitudine e la valutazione della proposta possono essere considerate separatamente.","example":"La volpe porge un piccolo cesto al lupo, già piegato sotto un carico enorme di doni e provviste. La scena rende visibile il peso dell’obbligo percepito. Un esempio quotidiano è sentirsi tenuti ad acquistare un prodotto dopo aver ricevuto un campione gratuito, anche se non risponde alle proprie esigenze.","question":"Accetterei questa proposta anche se non avessi ricevuto quel favore?","aliases":["reciprocità","reciprocity","favore","dono","obbligo di ricambiare","debito percepito","cesto"],"family":"Persuasione","section":"Persuasione","authors":["Robert B. Cialdini"],"references":[{"label":"Robert B. Cialdini · Reciprocità","citation":"Presentazione del principio nel sito del Cialdini Institute. Testo consultabile in inglese, con spiegazione e collegamenti alla ricerca.","url":"https://cialdini.com/principles/reciprocity"}],"referenceHeading":"ROBERT CIALDINI · OPERE E RICERCA","referenceOrigin":"Collegamento a Robert Cialdini richiesto dall’autore della serie. Le fonti specifiche inquadrano il principio o il meccanismo illustrato. Scene, slogan e animali appartengono alla lettura editoriale dei poster. L’argomento è approfondito in Psiche & Thanatos, come indicato dall’autore.","status":"definitive","order":102,"seriesNumber":105,"approvalBatch":29,"note":"Poster definitivo fornito dall’autore nel ventinovesimo gruppo di allegati, 19 ottobre 2026. Titolo, slogan e chiusura trascritti dall’originale. Soggetti principali: Volpe · Lupo. La scheda appartiene alla sezione Persuasione. Il PNG originale 2305×4096 è conservato senza modifiche.","image":"assets/definitivi/persuasion-reciprocity-original.png","original":"assets/definitivi/persuasion-reciprocity-original.png","thumb":"assets/definitivi/persuasion-reciprocity-thumb.webp","variants":[],"bookTitle":"Psiche & Thanatos","bookUrl":"https://www.amazon.it/dp/B0DVCC1HY6","topic":"I principi di Cialdini"},{"id":"persuasion-commitment","name":"Impegno e coerenza","english":"Commitment & consistency","sourceName":"89976.png","animal":"Asino · Volpe","animals":["Asino","Volpe"],"slogan":"La relazione mantiene ciò che dice e fa in modo coerente. Il limite si sente obbligato a mantenere gli impegni, anche quando non vorrebbe.","closing":"Uno dei principi di persuasione di Robert Cialdini.","description":"Dopo aver preso una posizione o assunto un impegno, possiamo sentirci spinti ad agire in modo coerente con ciò che abbiamo detto o fatto. Un primo assenso può così favorire adesioni successive. Il valore della coerenza resta compatibile con la possibilità di rivedere una decisione alla luce di nuovi elementi.","example":"L’asino porta sacchi con le scritte «promesse», «piccole scelte», «impegni», «azioni passate» e «aspettative degli altri». La volpe indica una scala che parte dalla «piccola richiesta» e conduce verso un altro sì. Nella vita quotidiana, un piccolo impegno può diventare un vincolo percepito quando le richieste si ampliano.","question":"Sto confermando una scelta ancora valida o sto proseguendo soprattutto per restare coerente con il primo sì?","aliases":["impegno e coerenza","commitment","consistency","piccole scelte","promesse","azioni passate","piccolo sì","piede nella porta","foot in the door"],"family":"Persuasione","section":"Persuasione","authors":["Robert B. Cialdini"],"references":[{"label":"Robert B. Cialdini · Impegno e coerenza","citation":"Presentazione del principio nel sito del Cialdini Institute. Testo consultabile in inglese, con spiegazione e collegamenti alla ricerca.","url":"https://cialdini.com/principles/commitment-and-consistency"}],"referenceHeading":"ROBERT CIALDINI · OPERE E RICERCA","referenceOrigin":"Collegamento a Robert Cialdini richiesto dall’autore della serie. Le fonti specifiche inquadrano il principio o il meccanismo illustrato. Scene, slogan e animali appartengono alla lettura editoriale dei poster. L’argomento è approfondito in Psiche & Thanatos, come indicato dall’autore.","status":"definitive","order":103,"seriesNumber":106,"approvalBatch":29,"note":"Poster definitivo fornito dall’autore nel ventinovesimo gruppo di allegati, 19 ottobre 2026. Titolo, slogan e chiusura trascritti dall’originale. Soggetti principali: Asino · Volpe. La scheda appartiene alla sezione Persuasione. Il PNG originale 2305×4096 è conservato senza modifiche.","image":"assets/definitivi/persuasion-commitment-original.png","original":"assets/definitivi/persuasion-commitment-original.png","thumb":"assets/definitivi/persuasion-commitment-thumb.webp","variants":[],"bookTitle":"Psiche & Thanatos","bookUrl":"https://www.amazon.it/dp/B0DVCC1HY6","topic":"I principi di Cialdini"},{"id":"persuasion-scarcity","name":"Scarsità","english":"Scarcity","sourceName":"89975.png","animal":"Uccello mercante · Pinguino","animals":["Uccello","Pinguino"],"slogan":"La relazione valuta il valore anche quando il tempo stringe. Il limite desidera di più ciò che teme di perdere.","closing":"Anteprima a tempo limitato del prossimo libro.","description":"Un’opportunità può apparire più desiderabile quando è presentata come rara, in esaurimento o disponibile per poco tempo. La disponibilità limitata può aumentare l’urgenza percepita anche quando le qualità dell’oggetto restano uguali. Il poster invita a distinguere rarità, interesse personale e valore della proposta.","example":"Un uccello mercante presenta un francobollo sotto vetro, fra i cartelli «Rarissimo», «Ultimo esemplare» e «Solo per oggi». Il pinguino collezionista guarda l’offerta con evidente agitazione. La clessidra mette in scena la fretta di decidere prima di perdere un’occasione.","question":"Quanto mi interessa davvero questa offerta, oltre alla paura che non sia più disponibile?","aliases":["scarsità","scarcity","rarità","francobollo","collezione","filatelia","ultimo esemplare","solo per oggi","urgenza","tempo limitato"],"family":"Persuasione","section":"Persuasione","authors":["Robert B. Cialdini"],"references":[{"label":"Robert B. Cialdini · Scarsità","citation":"Presentazione del principio nel sito del Cialdini Institute. Testo consultabile in inglese, con spiegazione e collegamenti alla ricerca.","url":"https://cialdini.com/principles/scarcity"}],"referenceHeading":"ROBERT CIALDINI · OPERE E RICERCA","referenceOrigin":"Collegamento a Robert Cialdini richiesto dall’autore della serie. Le fonti specifiche inquadrano il principio o il meccanismo illustrato. Scene, slogan e animali appartengono alla lettura editoriale dei poster. L’argomento è approfondito in Psiche & Thanatos, come indicato dall’autore.","status":"definitive","order":104,"seriesNumber":107,"approvalBatch":29,"note":"Poster definitivo fornito dall’autore nel ventinovesimo gruppo di allegati, 19 ottobre 2026. Titolo, slogan e chiusura trascritti dall’originale. Soggetti principali: Uccello mercante · Pinguino. La scheda appartiene alla sezione Persuasione. Il PNG originale 2305×4096 è conservato senza modifiche.","image":"assets/definitivi/persuasion-scarcity-original.png","original":"assets/definitivi/persuasion-scarcity-original.png","thumb":"assets/definitivi/persuasion-scarcity-thumb.webp","variants":[],"bookTitle":"Psiche & Thanatos","bookUrl":"https://www.amazon.it/dp/B0DVCC1HY6","topic":"I principi di Cialdini"},{"id":"persuasion-social-proof","name":"Riprova sociale","english":"Social proof","sourceName":"89974.png","animal":"Sardine · Pesce","animals":["Sardina","Pesce"],"slogan":"La relazione considera le scelte degli altri senza rinunciare a valutare. Il limite scambia ciò che piace a molti per ciò che è necessariamente migliore.","closing":"Anteprima socialmente approvata del prossimo libro.","description":"Quando siamo incerti, le scelte e le valutazioni degli altri possono orientarci, soprattutto se percepiamo quelle persone come simili a noi. La riprova sociale offre un indizio su ciò che appare accettato o preferito. La popolarità, però, non stabilisce da sola l’adeguatezza di una scelta per una persona o una situazione.","example":"Un banco di sardine si dirige verso «La conchiglia più amata dalle sardine!», mentre un pesce osserva anche le altre conchiglie. Il cartello richiama il linguaggio pubblicitario che presenta l’apprezzamento collettivo come motivo per scegliere. La scena distingue il consenso dalla valutazione delle caratteristiche e dei propri bisogni.","question":"Che cosa sostengono le preferenze degli altri, e quanto contano per la mia scelta specifica?","aliases":["riprova sociale","social proof","consenso","popolarità","conchiglia","la conchiglia più amata dalle sardine","scelte degli altri","recensioni"],"family":"Persuasione","section":"Persuasione","authors":["Robert B. Cialdini"],"references":[{"label":"Robert B. Cialdini · Riprova sociale","citation":"Presentazione del principio nel sito del Cialdini Institute. Testo consultabile in inglese, con spiegazione e collegamenti alla ricerca.","url":"https://cialdini.com/principles/social-proof"}],"referenceHeading":"ROBERT CIALDINI · OPERE E RICERCA","referenceOrigin":"Collegamento a Robert Cialdini richiesto dall’autore della serie. Le fonti specifiche inquadrano il principio o il meccanismo illustrato. Scene, slogan e animali appartengono alla lettura editoriale dei poster. L’argomento è approfondito in Psiche & Thanatos, come indicato dall’autore.","status":"definitive","order":105,"seriesNumber":108,"approvalBatch":29,"note":"Poster definitivo fornito dall’autore nel ventinovesimo gruppo di allegati, 19 ottobre 2026. Titolo, slogan e chiusura trascritti dall’originale. Soggetti principali: Sardine · Pesce. La scheda appartiene alla sezione Persuasione. Il PNG originale 2305×4096 è conservato senza modifiche.","image":"assets/definitivi/persuasion-social-proof-original.png","original":"assets/definitivi/persuasion-social-proof-original.png","thumb":"assets/definitivi/persuasion-social-proof-thumb.webp","variants":[],"bookTitle":"Psiche & Thanatos","bookUrl":"https://www.amazon.it/dp/B0DVCC1HY6","topic":"I principi di Cialdini"},{"id":"persuasion-authority","name":"Autorità","english":"Authority","sourceName":"89973.png","animal":"Uccello in camice · Pinguini","animals":["Uccello","Pinguino"],"slogan":"La relazione riconosce il valore dell’esperienza e della competenza. Il limite obbedisce all’autorità senza valutare criticamente.","closing":"Anteprima autorevolmente consigliata del prossimo libro.","description":"Le indicazioni di una persona percepita come esperta o autorevole possono orientare le nostre decisioni. Titoli, abbigliamento e simboli professionali possono contribuire a questa percezione. Il principio di autorità richiede quindi attenzione al rapporto fra i segnali di competenza, l’esperienza effettiva e l’ambito della proposta.","example":"Un uccello in camice, con stetoscopio e documenti, indica il cartello «Consigliato dagli esperti». I pinguini ascoltano e uno pensa «Se lo dice lui, deve essere giusto!». La scena mostra come l’aspetto autorevole della fonte possa assumere un peso decisivo nella valutazione del messaggio.","question":"Quale competenza pertinente sostiene questa indicazione, e quali elementi posso valutarne direttamente?","aliases":["autorità","authority","autorevolezza","esperti","camice","competenza","qualità certificata","consigliato dagli esperti","se lo dice lui"],"family":"Persuasione","section":"Persuasione","authors":["Robert B. Cialdini"],"references":[{"label":"Robert B. Cialdini · Autorità","citation":"Presentazione del principio nel sito del Cialdini Institute. Testo consultabile in inglese, con spiegazione e collegamenti alla ricerca.","url":"https://cialdini.com/principles/authority"}],"referenceHeading":"ROBERT CIALDINI · OPERE E RICERCA","referenceOrigin":"Collegamento a Robert Cialdini richiesto dall’autore della serie. Le fonti specifiche inquadrano il principio o il meccanismo illustrato. Scene, slogan e animali appartengono alla lettura editoriale dei poster. L’argomento è approfondito in Psiche & Thanatos, come indicato dall’autore.","status":"definitive","order":106,"seriesNumber":109,"approvalBatch":29,"note":"Poster definitivo fornito dall’autore nel ventinovesimo gruppo di allegati, 19 ottobre 2026. Titolo, slogan e chiusura trascritti dall’originale. Soggetti principali: Uccello in camice · Pinguini. La scheda appartiene alla sezione Persuasione. Il PNG originale 2305×4096 è conservato senza modifiche.","image":"assets/definitivi/persuasion-authority-original.png","original":"assets/definitivi/persuasion-authority-original.png","thumb":"assets/definitivi/persuasion-authority-thumb.webp","variants":[],"bookTitle":"Psiche & Thanatos","bookUrl":"https://www.amazon.it/dp/B0DVCC1HY6","topic":"I principi di Cialdini"},{"id":"persuasion-liking","name":"Simpatia","english":"Liking","sourceName":"89972.png","animal":"Volpe · Lontra","animals":["Volpe","Lontra"],"slogan":"La relazione distingue il contenuto dal fascino di chi lo propone. Il limite dice più facilmente sì a chi trova simpatico, familiare o simile a sé.","closing":"Anteprima cordialmente simpatica del prossimo libro.","description":"Possiamo accogliere più facilmente una richiesta quando proviene da qualcuno che ci piace. Somiglianze, familiarità, apprezzamento e collaborazione possono favorire questa disposizione. La simpatia contribuisce alla relazione, ma il giudizio sulla persona e quello sulla proposta possono essere esaminati distintamente.","example":"La volpe offre un pesce alla lontra, che la guarda con entusiasmo, fra i cartelli «Persone simili creano fiducia» e «Un sorriso oggi, una scelta domani!». Il poster mette in scena il fascino del proponente. Un esempio quotidiano è considerare migliore un’offerta perché il venditore ci è particolarmente simpatico.","question":"Quali ragioni sostengono la proposta, oltre alla simpatia che provo per chi la presenta?","aliases":["simpatia","liking","familiarità","somiglianza","fiducia","sorriso","persone simili","fascino"],"family":"Persuasione","section":"Persuasione","authors":["Robert B. Cialdini"],"references":[{"label":"Robert B. Cialdini · Simpatia","citation":"Presentazione del principio nel sito del Cialdini Institute. Testo consultabile in inglese, con spiegazione e collegamenti alla ricerca.","url":"https://cialdini.com/principles/liking"}],"referenceHeading":"ROBERT CIALDINI · OPERE E RICERCA","referenceOrigin":"Collegamento a Robert Cialdini richiesto dall’autore della serie. Le fonti specifiche inquadrano il principio o il meccanismo illustrato. Scene, slogan e animali appartengono alla lettura editoriale dei poster. L’argomento è approfondito in Psiche & Thanatos, come indicato dall’autore.","status":"definitive","order":107,"seriesNumber":110,"approvalBatch":29,"note":"Poster definitivo fornito dall’autore nel ventinovesimo gruppo di allegati, 19 ottobre 2026. Titolo, slogan e chiusura trascritti dall’originale. Soggetti principali: Volpe · Lontra. La scheda appartiene alla sezione Persuasione. Il PNG originale 2305×4096 è conservato senza modifiche.","image":"assets/definitivi/persuasion-liking-original.png","original":"assets/definitivi/persuasion-liking-original.png","thumb":"assets/definitivi/persuasion-liking-thumb.webp","variants":[],"bookTitle":"Psiche & Thanatos","bookUrl":"https://www.amazon.it/dp/B0DVCC1HY6","topic":"I principi di Cialdini"},{"id":"persuasion-contrast","name":"Contrasto nella persuasione","english":"Contrast principle","sourceName":"89971.png","animal":"Bulldog · Lepre · Volpe","animals":["Cane","Lepre","Volpe"],"slogan":"La relazione valuta ogni proposta nel suo merito, senza lasciarsi guidare dal confronto. Il limite giudica più accettabile ciò che arriva dopo qualcosa di peggiore.","closing":"Anteprima strategicamente contrastata del prossimo libro.","description":"La valutazione di una proposta può cambiare in funzione di ciò che la precede: dopo una richiesta più gravosa, la successiva può apparire più accettabile. Questa tavola illustra il confronto tra richieste. Il contrasto non è un ottavo elemento della lista dei sette principi; lo studio di Cialdini e colleghi del 1975 distingue il contrasto dalle concessioni reciproche della tecnica della porta in faccia.","example":"Il bulldog indica la «richiesta dura», segnata come rifiutata; la volpe presenta la «richiesta più accettabile» alla lepre. Il passaggio sposta il termine di paragone. La scena invita a valutare la seconda richiesta anche rispetto ai propri criteri, oltre al sollievo prodotto dal confronto con la prima.","question":"Come valuterei questa proposta se fosse stata presentata da sola?","aliases":["contrasto","contrast principle","richiesta dura","richiesta più accettabile","confronto fra richieste","porta in faccia","door in the face","concessioni reciproche","bulldog"],"family":"Persuasione","section":"Persuasione","authors":["Robert B. Cialdini"],"references":[{"label":"Robert B. Cialdini · Opere sulla persuasione","citation":"Presentazione delle opere di Robert Cialdini nel sito Influence at Work, fra cui Influence e Pre-Suasion. Il link apre le schede dei libri, non i testi integrali.","url":"https://www.influenceatwork.com/books-and-publications/"},{"label":"Cialdini e colleghi (1975) · Concessioni reciproche e contrasto","citation":"Cialdini, R. B., Vincent, J. E., Lewis, S. K., Catalan, J., Wheeler, D., & Darby, B. L. (1975). Reciprocal concessions procedure for inducing compliance: The door-in-the-face technique. Journal of Personality and Social Psychology, 31(2), 206–215. DOI: 10.1037/h0076284. Testo integrale in PDF ospitato dal MIT; lo studio confronta la spiegazione delle concessioni reciproche con quella del contrasto.","url":"https://web.mit.edu/curhan/www/docs/Articles/15341_Readings/Influence_Compliance/Cialdini.et.al.Reciprocal.Concessions.Procedure.1975.article.pdf"}],"referenceHeading":"ROBERT CIALDINI · OPERE E RICERCA","referenceOrigin":"Collegamento a Robert Cialdini richiesto dall’autore della serie. Le fonti specifiche inquadrano il principio o il meccanismo illustrato. Scene, slogan e animali appartengono alla lettura editoriale dei poster. L’argomento è approfondito in Psiche & Thanatos, come indicato dall’autore.","status":"definitive","order":108,"seriesNumber":111,"approvalBatch":29,"note":"Poster definitivo fornito dall’autore nel ventinovesimo gruppo di allegati, 19 ottobre 2026. Titolo, slogan e chiusura trascritti dall’originale. Soggetti principali: Bulldog · Lepre · Volpe. La scheda appartiene alla sezione Persuasione. Il PNG originale 2305×4096 è conservato senza modifiche.","image":"assets/definitivi/persuasion-contrast-original.png","original":"assets/definitivi/persuasion-contrast-original.png","thumb":"assets/definitivi/persuasion-contrast-thumb.webp","variants":[],"bookTitle":"Psiche & Thanatos","bookUrl":"https://www.amazon.it/dp/B0DVCC1HY6","topic":"Altri processi d’influenza"},{"id":"persuasion-unity","name":"Unità","english":"Unity","sourceName":"89970.png","animal":"Pinguini","animals":["Pinguino"],"slogan":"La relazione si rafforza quando ci sentiamo parte dello stesso gruppo, con valori e obiettivi comuni. Il limite porta ad accettare e seguire le richieste solo perché provengono da chi percepiamo come “uno di noi”.","closing":"Anteprima unita del prossimo libro.","description":"L’identità condivisa può rendere più influente una richiesta: chi la propone viene percepito come parte dello stesso «noi». Nel principio di unità descritto da Cialdini, conta il senso di appartenenza comune, oltre alla semplice simpatia. La scena richiama una squadra che condivide valori, obiettivi e identità.","example":"I pinguini uniscono le mani davanti a un velivolo, con uniformi e simboli di appartenenza comuni. Il cartello elenca stessi valori, stessa squadra, stessi obiettivi e stessa identità. Questa cornice può sostenere la collaborazione e può anche aumentare il peso delle richieste provenienti dal proprio gruppo.","question":"Sto condividendo la decisione per le sue ragioni o soprattutto perché arriva da «uno di noi»?","aliases":["unità","unity","identità condivisa","appartenenza","stessa squadra","stessi valori","stessi obiettivi","stessa identità","uno di noi"],"family":"Persuasione","section":"Persuasione","authors":["Robert B. Cialdini"],"references":[{"label":"Robert B. Cialdini · Unità","citation":"Presentazione del principio nel sito del Cialdini Institute. Testo consultabile in inglese, con spiegazione e collegamenti alla ricerca.","url":"https://cialdini.com/principles/unity"}],"referenceHeading":"ROBERT CIALDINI · OPERE E RICERCA","referenceOrigin":"Collegamento a Robert Cialdini richiesto dall’autore della serie. Le fonti specifiche inquadrano il principio o il meccanismo illustrato. Scene, slogan e animali appartengono alla lettura editoriale dei poster. L’argomento è approfondito in Psiche & Thanatos, come indicato dall’autore.","status":"definitive","order":109,"seriesNumber":112,"approvalBatch":29,"note":"Poster definitivo fornito dall’autore nel ventinovesimo gruppo di allegati, 19 ottobre 2026. Titolo, slogan e chiusura trascritti dall’originale. Soggetti principali: Pinguini. La scheda appartiene alla sezione Persuasione. Il PNG originale 2305×4096 è conservato senza modifiche.","image":"assets/definitivi/persuasion-unity-original.png","original":"assets/definitivi/persuasion-unity-original.png","thumb":"assets/definitivi/persuasion-unity-thumb.webp","variants":[],"bookTitle":"Psiche & Thanatos","bookUrl":"https://www.amazon.it/dp/B0DVCC1HY6","topic":"I principi di Cialdini"},{"id":"persuasion-mere-exposure","name":"Effetto della mera esposizione","english":"Mere-exposure effect","sourceName":"89978.png","animal":"Camaleonte","animals":["Camaleonte"],"slogan":"La relazione riconosce che la familiarità può aumentare il gradimento. Il limite confonde ciò che ormai conosce bene con ciò che necessariamente vale di più.","closing":"Anteprima piacevolmente ripetuta del prossimo libro.","description":"L’esposizione ripetuta a uno stimolo può aumentarne il gradimento anche senza nuove informazioni sul suo valore. Negli studi di Robert B. Zajonc, il semplice incontro ripetuto con parole, simboli o immagini può rendere più favorevole la valutazione. La familiarità può quindi orientare una preferenza; l’effetto varia con lo stimolo e il contesto e non implica che il gradimento cresca senza limiti.","example":"Un camaleonte con le cuffie ascolta musica in poltrona, tra dischi e giradischi. I riquadri passano da «1° ascolto: Mah...» a «10° ascolto: Bellissima!». La scena illustra come un brano inizialmente poco apprezzato possa piacere di più con gli ascolti: i numeri rappresentano una progressione narrativa del poster, senza fissare una soglia valida per tutti.","question":"Questo brano, questa idea o questa proposta mi piace per le sue qualità o anche perché l’ho incontrata tante volte?","aliases":["mera esposizione","mere-exposure effect","mere exposure","effetto di mera esposizione","Zajonc","familiarità","gradimento","preferenza","ripetizione","ascolto ripetuto","stessa canzone","piacevolmente ripetuta"],"family":"Persuasione","section":"Persuasione","authors":["Robert B. Zajonc"],"references":[{"label":"Robert B. Zajonc (1968) · Attitudinal effects of mere exposure","citation":"Journal of Personality and Social Psychology, 9(2, Pt. 2), 1–27. Articolo di riferimento sull’effetto della mera esposizione; DOI: 10.1037/h0025848. Il collegamento conduce alla pagina dell’editore e l’accesso al testo può essere limitato.","url":"https://doi.org/10.1037/h0025848"},{"label":"Robert B. Zajonc (1965) · Rapporto di ricerca originale, testo integrale","citation":"The Attitudinal Effects of Mere Exposure. Technical Report No. 34, settembre 1965, Institute for Social Research, University of Michigan. Versione di ricerca precedente all’articolo del 1968, disponibile in PDF nell’archivio universitario.","url":"https://cdn.isr.umich.edu/pubFiles/historicPublications/Theattitudinaleffects_2360_.PDF"}],"referenceHeading":"ROBERT ZAJONC · STUDI SULLA MERA ESPOSIZIONE","referenceOrigin":"Il poster indica Zajonc. I collegamenti all’articolo del 1968 e al rapporto del 1965 sono integrazioni bibliografiche della scheda. La tavola affianca i principi di Cialdini nella sezione Persuasione come meccanismo distinto. Scena, slogan e progressione degli ascolti appartengono alla lettura editoriale della serie. L’argomento è approfondito in Psiche & Thanatos, secondo l’indicazione dell’autore per questa sezione.","status":"definitive","order":110,"seriesNumber":113,"approvalBatch":30,"note":"Poster definitivo fornito dall’autore nel trentesimo gruppo di allegati, 19 ottobre 2026. Titolo, slogan e chiusura trascritti dall’originale. Soggetto: camaleonte con cuffie in ascolto. La scheda appartiene alla sezione Persuasione. Il PNG originale 2305×4096 è conservato senza modifiche.","image":"assets/definitivi/persuasion-mere-exposure-original.png","original":"assets/definitivi/persuasion-mere-exposure-original.png","thumb":"assets/definitivi/persuasion-mere-exposure-thumb.webp","variants":[],"bookTitle":"Psiche & Thanatos","bookUrl":"https://www.amazon.it/dp/B0DVCC1HY6","topic":"Altri processi d’influenza"},{"id":"mindfulness","name":"Mindfulness · Presenza consapevole","english":"Mindfulness","sourceName":"90849.png","animal":"Panda","animals":["Panda","Scimmia","Uccello"],"slogan":"La relazione osserva ciò che accade senza farsi trascinare. Il limite reagisce a ogni pensiero come se fosse realtà.","closing":"Anteprima consapevolmente presente del prossimo libro.","description":"La mindfulness coltiva un’attenzione intenzionale all’esperienza presente, con apertura e senza giudizio immediato. Sensazioni, emozioni e pensieri vengono riconosciuti mentre emergono, lasciando spazio per scegliere come rispondere. Il richiamo al «qui e ora» riguarda questo rapporto con l’esperienza: anche accorgersi di essersi distratti e tornare all’attenzione fa parte della pratica.","example":"Il panda siede tra i bambù con la scritta «hic et nunc» sull’indumento, mentre scimmie e uccelli animano la scena. Nella metafora del poster, le distrazioni continuano a esserci e il panda mantiene un atteggiamento di presenza. Un pensiero come «andrà tutto male» può essere riconosciuto come un pensiero, prima di decidere che cosa fare nella situazione concreta.","question":"Che cosa sto osservando adesso, e che cosa sto aggiungendo con i miei pensieri?","aliases":["presenza consapevole","consapevolezza","attenzione al presente","qui e ora","hic et nunc","meditazione","Kabat-Zinn","MBSR","mindfulness-based stress reduction","consapevolmente presente"],"family":"Gestione dello Stress","section":"Gestione dello Stress","authors":["Jon Kabat-Zinn","Scott R. Bishop","Mark Lau","Shauna Shapiro","Linda Carlson","Nicole D. Anderson","James Carmody","Zindel V. Segal","Susan Abbey","Michael Speca","Drew Velting","Gerald Devins"],"references":[{"label":"Jon Kabat-Zinn (2003) · Mindfulness-Based Interventions in Context: Past, Present, and Future","citation":"Kabat-Zinn, J. (2003). Mindfulness-based interventions in context: Past, present, and future. Clinical Psychology: Science and Practice, 10(2), 144–156. Definizione della presenza consapevole e inquadramento delle applicazioni basate sulla mindfulness.","url":"https://onlinelibrary.wiley.com/doi/full/10.1093/clipsy.bpg016"},{"label":"Scott R. Bishop e colleghi (2004) · Mindfulness: A Proposed Operational Definition","citation":"Bishop, S. R., Lau, M., Shapiro, S., Carlson, L., Anderson, N. D., Carmody, J., Segal, Z. V., Abbey, S., Speca, M., Velting, D., & Devins, G. (2004). Mindfulness: A proposed operational definition. Clinical Psychology: Science and Practice, 11(3), 230–241. Proposta di definizione operativa; il link conduce alla pagina dell’editore.","url":"https://doi.org/10.1093/clipsy.bph077"}],"referenceHeading":"MINDFULNESS · DEFINIZIONI E RIFERIMENTI","referenceOrigin":"Il poster non indica uno studioso. Kabat-Zinn e Bishop e colleghi sono riferimenti bibliografici aggiunti alla scheda per inquadrare la presenza consapevole. Animali, scena e slogan appartengono alla lettura editoriale della serie. La tavola è collocata in Gestione dello Stress; il richiamo a Psiche & Thanatos segue l’indicazione dell’autore per gli argomenti di questa sezione.","status":"definitive","order":111,"seriesNumber":114,"approvalBatch":31,"note":"Poster definitivo fornito dall’autore nel trentunesimo gruppo di allegati, 23 ottobre 2026. Titolo, slogan e chiusura trascritti dall’originale. Soggetto centrale: panda con «hic et nunc» sull’indumento; presenti anche scimmie e uccelli. Il PNG originale 2305×4096 è conservato senza modifiche.","image":"assets/definitivi/mindfulness-original.png","original":"assets/definitivi/mindfulness-original.png","thumb":"assets/definitivi/mindfulness-thumb.webp","variants":[],"bookTitle":"Psiche & Thanatos","bookUrl":"https://www.amazon.it/dp/B0DVCC1HY6","topic":"Consapevolezza e regolazione"},{"id":"ocean-big-five","sourceName":"90994.png","name":"Big Five · I cinque tratti di personalità","english":"Big Five · OCEAN","animal":"Colibrì · Ape · Lemure · Quokka · Pangolino","animals":["Colibrì","Ape","Lemure","Quokka","Pangolino"],"slogan":"La relazione riconosce che ogni tratto può diventare una risorsa quando resta in dialogo con gli altri. Il limite emerge quando uno solo prende il sopravvento e smette di ascoltare il contesto.","closing":"Anteprima dei cinque tratti del prossimo libro.","description":"Il modello Big Five descrive la personalità attraverso cinque dimensioni: apertura all’esperienza, coscienziosità, estroversione, gradevolezza e nevroticismo. L’acronimo OCEAN riprende i nomi inglesi. Ogni persona presenta un profilo che le combina in gradi diversi. Costa e McCrae hanno contribuito allo sviluppo e alla validazione del modello; i cinque animali ne offrono una lettura visiva nella serie.","example":"La tavola riunisce il colibrì che esplora, l’ape che pianifica, il lemure con il megafono, il quokka disponibile e il pangolino preoccupato. Lo slogan invita a osservare come queste tendenze si esprimono nelle relazioni e nel contesto: il loro dialogo è la proposta editoriale del poster.","question":"Quale combinazione di tendenze riconosco nel mio modo di esplorare, organizzarmi, partecipare, collaborare e reagire alle difficoltà?","aliases":["OCEAN","Big Five","Five-Factor Model","FFM","cinque fattori","cinque tratti","Openness","Conscientiousness","Extraversion","Agreeableness","Neuroticism","profilo di personalità","cinque animali"],"family":"Tratti di personalità","section":"Tratti di personalità (OCEAN)","authors":["Paul T. Costa Jr.","Robert R. McCrae","Oliver P. John","Sanjay Srivastava"],"references":[{"label":"McCrae e Costa (1987) · Validazione del modello a cinque fattori","citation":"McCrae, R. R., & Costa, P. T., Jr. (1987). Validation of the five-factor model of personality across instruments and observers. Journal of Personality and Social Psychology, 52(1), 81–90. Studio con autovalutazioni e valutazioni di osservatori; abstract e collegamenti in PubMed.","url":"https://pubmed.ncbi.nlm.nih.gov/3820081/"},{"label":"Costa e McCrae (1992) · Four ways five factors are basic","citation":"Costa, P. T., Jr., & McCrae, R. R. (1992). Four ways five factors are basic. Personality and Individual Differences, 13(6), 653–665. Inquadramento teorico ed empirico delle cinque dimensioni. Il link conduce alla pagina dell’editore.","url":"https://doi.org/10.1016/0191-8869(92)90236-I"},{"label":"John e Srivastava (1999) · Tassonomia e definizioni dei Big Five","citation":"John, O. P., & Srivastava, S. (1999). The Big Five trait taxonomy: History, measurement, and theoretical perspectives. In L. A. Pervin & O. P. John (Eds.), Handbook of personality: Theory and research (2nd ed., pp. 102–138). Guilford Press. Capitolo consultabile in PDF nell’archivio universitario.","url":"https://jenni.uchicago.edu/econ-psych-traits/John_Srivastava_1995_big5.pdf"}],"referenceHeading":"BIG FIVE · STUDI E RIFERIMENTI","referenceOrigin":"Costa e McCrae per lo sviluppo e la validazione del modello, John e Srivastava per la tassonomia dei tratti: riferimenti bibliografici aggiunti alla scheda. Gli animali sono quelli scelti dall’autore della serie. Scene e slogan esprimono una lettura editoriale del rapporto fra tratti, relazione e contesto. L’argomento è approfondito in Psiche & Thanatos, come indicato dall’autore.","status":"definitive","order":112,"seriesNumber":115,"approvalBatch":32,"note":"Poster definitivo fornito dall’autore nel trentaduesimo gruppo di allegati, 23 ottobre 2026. Titolo, slogan e chiusura trascritti dall’originale. Soggetto: Colibrì · Ape · Lemure · Quokka · Pangolino. Il PNG originale 2305×4096 è conservato senza modifiche.","image":"assets/definitivi/ocean-big-five-original.png","original":"assets/definitivi/ocean-big-five-original.png","thumb":"assets/definitivi/ocean-big-five-thumb.webp","variants":[],"bookTitle":"Psiche & Thanatos","bookUrl":"https://www.amazon.it/dp/B0DVCC1HY6","topic":"Il modello"},{"id":"ocean-openness","sourceName":"90989.png","name":"Apertura all’esperienza","english":"Openness to experience","animal":"Colibrì","animals":["Colibrì"],"oceanLetter":"O","slogan":"La relazione esplora possibilità nuove senza perdere il contatto con la realtà. Il limite cerca continuamente qualcosa di diverso, anche quando sarebbe utile fermarsi e scegliere.","closing":"Anteprima curiosamente inesplorata del prossimo libro.","description":"L’apertura all’esperienza riguarda curiosità, immaginazione, sensibilità estetica e disponibilità verso idee ed esperienze diverse. Nella lettura editoriale del poster, l’esplorazione diventa una risorsa quando si accompagna alla capacità di scegliere e di considerare la situazione concreta.","example":"Il colibrì attraversa un giardino ricco di fiori e sentieri. I cartelli indicano idee nuove, mondi diversi, emozioni nuove, esperienze insolite, prospettive inattese e persone diverse. La scena rappresenta la curiosità; lo slogan richiama anche il momento in cui occorre fermarsi e decidere.","question":"Quale possibilità nuova merita di essere esplorata, e quando è utile scegliere una direzione?","aliases":["OCEAN","Big Five","O","openness","apertura","curiosità","immaginazione","idee nuove","esperienze insolite","prospettive inattese"],"family":"Tratti di personalità","section":"Tratti di personalità (OCEAN)","authors":["Paul T. Costa Jr.","Robert R. McCrae","Oliver P. John","Sanjay Srivastava"],"references":[{"label":"McCrae e Costa (1987) · Validazione del modello a cinque fattori","citation":"McCrae, R. R., & Costa, P. T., Jr. (1987). Validation of the five-factor model of personality across instruments and observers. Journal of Personality and Social Psychology, 52(1), 81–90. Studio con autovalutazioni e valutazioni di osservatori; abstract e collegamenti in PubMed.","url":"https://pubmed.ncbi.nlm.nih.gov/3820081/"},{"label":"Costa e McCrae (1992) · Four ways five factors are basic","citation":"Costa, P. T., Jr., & McCrae, R. R. (1992). Four ways five factors are basic. Personality and Individual Differences, 13(6), 653–665. Inquadramento teorico ed empirico delle cinque dimensioni. Il link conduce alla pagina dell’editore.","url":"https://doi.org/10.1016/0191-8869(92)90236-I"},{"label":"John e Srivastava (1999) · Tassonomia e definizioni dei Big Five","citation":"John, O. P., & Srivastava, S. (1999). The Big Five trait taxonomy: History, measurement, and theoretical perspectives. In L. A. Pervin & O. P. John (Eds.), Handbook of personality: Theory and research (2nd ed., pp. 102–138). Guilford Press. Capitolo consultabile in PDF nell’archivio universitario.","url":"https://jenni.uchicago.edu/econ-psych-traits/John_Srivastava_1995_big5.pdf"}],"referenceHeading":"BIG FIVE · STUDI E RIFERIMENTI","referenceOrigin":"Costa e McCrae per lo sviluppo e la validazione del modello, John e Srivastava per la tassonomia dei tratti: riferimenti bibliografici aggiunti alla scheda. Gli animali sono quelli scelti dall’autore della serie. Scene e slogan esprimono una lettura editoriale del rapporto fra tratti, relazione e contesto. L’argomento è approfondito in Psiche & Thanatos, come indicato dall’autore.","status":"definitive","order":113,"seriesNumber":116,"approvalBatch":32,"note":"Poster definitivo fornito dall’autore nel trentaduesimo gruppo di allegati, 23 ottobre 2026. Titolo, slogan e chiusura trascritti dall’originale. Soggetto: Colibrì. Il PNG originale 2305×4096 è conservato senza modifiche.","image":"assets/definitivi/ocean-openness-original.png","original":"assets/definitivi/ocean-openness-original.png","thumb":"assets/definitivi/ocean-openness-thumb.webp","variants":[],"bookTitle":"Psiche & Thanatos","bookUrl":"https://www.amazon.it/dp/B0DVCC1HY6","topic":"I cinque tratti"},{"id":"ocean-conscientiousness","sourceName":"90990.png","name":"Coscienziosità","english":"Conscientiousness","animal":"Ape","animals":["Ape"],"oceanLetter":"C","slogan":"La relazione usa metodo e disciplina senza perdere la capacità di adattarsi. Il limite continua a seguire il piano anche quando la realtà è cambiata.","closing":"Anteprima meticolosamente pianificata del prossimo libro.","description":"La coscienziosità comprende organizzazione, affidabilità, perseveranza e orientamento agli obiettivi. Il poster ne illustra il valore nel pianificare un lavoro e propone di affiancare al metodo la capacità di aggiornare il piano quando cambiano le condizioni.","example":"L’ape lavora nell’alveare con disegni, compasso, righello e attrezzi, mentre la struttura intorno è danneggiata. Il cartello «Ma era tutto previsto!» rende visibile la distanza tra un progetto accurato e una situazione che richiede un adattamento.","question":"Il piano mi sta ancora aiutando a raggiungere l’obiettivo, oppure va aggiornato alla situazione attuale?","aliases":["OCEAN","Big Five","C","conscientiousness","coscienziosità","metodo","disciplina","pianificazione","affidabilità","perseveranza","ma era tutto previsto"],"family":"Tratti di personalità","section":"Tratti di personalità (OCEAN)","authors":["Paul T. Costa Jr.","Robert R. McCrae","Oliver P. John","Sanjay Srivastava"],"references":[{"label":"McCrae e Costa (1987) · Validazione del modello a cinque fattori","citation":"McCrae, R. R., & Costa, P. T., Jr. (1987). Validation of the five-factor model of personality across instruments and observers. Journal of Personality and Social Psychology, 52(1), 81–90. Studio con autovalutazioni e valutazioni di osservatori; abstract e collegamenti in PubMed.","url":"https://pubmed.ncbi.nlm.nih.gov/3820081/"},{"label":"Costa e McCrae (1992) · Four ways five factors are basic","citation":"Costa, P. T., Jr., & McCrae, R. R. (1992). Four ways five factors are basic. Personality and Individual Differences, 13(6), 653–665. Inquadramento teorico ed empirico delle cinque dimensioni. Il link conduce alla pagina dell’editore.","url":"https://doi.org/10.1016/0191-8869(92)90236-I"},{"label":"John e Srivastava (1999) · Tassonomia e definizioni dei Big Five","citation":"John, O. P., & Srivastava, S. (1999). The Big Five trait taxonomy: History, measurement, and theoretical perspectives. In L. A. Pervin & O. P. John (Eds.), Handbook of personality: Theory and research (2nd ed., pp. 102–138). Guilford Press. Capitolo consultabile in PDF nell’archivio universitario.","url":"https://jenni.uchicago.edu/econ-psych-traits/John_Srivastava_1995_big5.pdf"}],"referenceHeading":"BIG FIVE · STUDI E RIFERIMENTI","referenceOrigin":"Costa e McCrae per lo sviluppo e la validazione del modello, John e Srivastava per la tassonomia dei tratti: riferimenti bibliografici aggiunti alla scheda. Gli animali sono quelli scelti dall’autore della serie. Scene e slogan esprimono una lettura editoriale del rapporto fra tratti, relazione e contesto. L’argomento è approfondito in Psiche & Thanatos, come indicato dall’autore.","status":"definitive","order":114,"seriesNumber":117,"approvalBatch":32,"note":"Poster definitivo fornito dall’autore nel trentaduesimo gruppo di allegati, 23 ottobre 2026. Titolo, slogan e chiusura trascritti dall’originale. Soggetto: Ape. Il PNG originale 2305×4096 è conservato senza modifiche.","image":"assets/definitivi/ocean-conscientiousness-original.png","original":"assets/definitivi/ocean-conscientiousness-original.png","thumb":"assets/definitivi/ocean-conscientiousness-thumb.webp","variants":[],"bookTitle":"Psiche & Thanatos","bookUrl":"https://www.amazon.it/dp/B0DVCC1HY6","topic":"I cinque tratti"},{"id":"ocean-extraversion","sourceName":"90991.png","name":"Estroversione","english":"Extraversion","animal":"Lemure","animals":["Lemure"],"oceanLetter":"E","slogan":"La relazione trova energia nello scambio e lascia spazio anche agli altri. Il limite confonde il piacere di partecipare con il bisogno di essere sempre al centro.","closing":"Anteprima irresistibilmente socievole del prossimo libro.","description":"L’estroversione riguarda socievolezza, attività, assertività ed emozioni positive. Nella scena del poster, l’energia della partecipazione si accompagna al tema dell’ascolto e dello spazio lasciato agli altri. È una dimensione espressa in gradi diversi, insieme agli altri tratti.","example":"Il lemure con il megafono anima una riunione tra gli animali e annuncia «Ragazzi, ho un’altra idea!». Il cartello «La parola a tutti!» richiama il contributo di ciascuno e il rischio, nella metafora, che una sola voce occupi tutto lo spazio.","question":"La mia partecipazione sta favorendo lo scambio e lascia agli altri il tempo di esprimersi?","aliases":["OCEAN","Big Five","E","extraversion","extroversion","estroversione","socievolezza","assertività","partecipazione","megafono","la parola a tutti"],"family":"Tratti di personalità","section":"Tratti di personalità (OCEAN)","authors":["Paul T. Costa Jr.","Robert R. McCrae","Oliver P. John","Sanjay Srivastava"],"references":[{"label":"McCrae e Costa (1987) · Validazione del modello a cinque fattori","citation":"McCrae, R. R., & Costa, P. T., Jr. (1987). Validation of the five-factor model of personality across instruments and observers. Journal of Personality and Social Psychology, 52(1), 81–90. Studio con autovalutazioni e valutazioni di osservatori; abstract e collegamenti in PubMed.","url":"https://pubmed.ncbi.nlm.nih.gov/3820081/"},{"label":"Costa e McCrae (1992) · Four ways five factors are basic","citation":"Costa, P. T., Jr., & McCrae, R. R. (1992). Four ways five factors are basic. Personality and Individual Differences, 13(6), 653–665. Inquadramento teorico ed empirico delle cinque dimensioni. Il link conduce alla pagina dell’editore.","url":"https://doi.org/10.1016/0191-8869(92)90236-I"},{"label":"John e Srivastava (1999) · Tassonomia e definizioni dei Big Five","citation":"John, O. P., & Srivastava, S. (1999). The Big Five trait taxonomy: History, measurement, and theoretical perspectives. In L. A. Pervin & O. P. John (Eds.), Handbook of personality: Theory and research (2nd ed., pp. 102–138). Guilford Press. Capitolo consultabile in PDF nell’archivio universitario.","url":"https://jenni.uchicago.edu/econ-psych-traits/John_Srivastava_1995_big5.pdf"}],"referenceHeading":"BIG FIVE · STUDI E RIFERIMENTI","referenceOrigin":"Costa e McCrae per lo sviluppo e la validazione del modello, John e Srivastava per la tassonomia dei tratti: riferimenti bibliografici aggiunti alla scheda. Gli animali sono quelli scelti dall’autore della serie. Scene e slogan esprimono una lettura editoriale del rapporto fra tratti, relazione e contesto. L’argomento è approfondito in Psiche & Thanatos, come indicato dall’autore.","status":"definitive","order":115,"seriesNumber":118,"approvalBatch":32,"note":"Poster definitivo fornito dall’autore nel trentaduesimo gruppo di allegati, 23 ottobre 2026. Titolo, slogan e chiusura trascritti dall’originale. Soggetto: Lemure. Il PNG originale 2305×4096 è conservato senza modifiche.","image":"assets/definitivi/ocean-extraversion-original.png","original":"assets/definitivi/ocean-extraversion-original.png","thumb":"assets/definitivi/ocean-extraversion-thumb.webp","variants":[],"bookTitle":"Psiche & Thanatos","bookUrl":"https://www.amazon.it/dp/B0DVCC1HY6","topic":"I cinque tratti"},{"id":"ocean-agreeableness","sourceName":"90992.png","name":"Gradevolezza","english":"Agreeableness","animal":"Quokka","animals":["Quokka"],"oceanLetter":"A","slogan":"La relazione riconosce i bisogni degli altri senza dimenticare i propri. Il limite continua a dire sì anche quando avrebbe bisogno di dire no.","closing":"Anteprima fin troppo gentilmente disponibile del prossimo libro.","description":"La gradevolezza comprende cooperazione, fiducia, altruismo e attenzione agli altri. Il poster collega la disponibilità alla possibilità di riconoscere anche i propri bisogni e limiti. Il sovraccarico del protagonista è una metafora editoriale della difficoltà a porre un confine.","example":"Il quokka accoglie le richieste degli altri e risponde «Certo! Nessun problema!», pur essendo già carico di pacchi, bagagli e oggetti. Il cartello «Lavori da fare a casa» ricorda gli impegni personali che restano da affrontare.","question":"Posso accogliere questa richiesta tenendo conto anche delle mie risorse e dei miei impegni?","aliases":["OCEAN","Big Five","A","agreeableness","gradevolezza","amicalità","cooperazione","fiducia","disponibilità","dire sì","dire no","confini personali","nessun problema"],"family":"Tratti di personalità","section":"Tratti di personalità (OCEAN)","authors":["Paul T. Costa Jr.","Robert R. McCrae","Oliver P. John","Sanjay Srivastava"],"references":[{"label":"McCrae e Costa (1987) · Validazione del modello a cinque fattori","citation":"McCrae, R. R., & Costa, P. T., Jr. (1987). Validation of the five-factor model of personality across instruments and observers. Journal of Personality and Social Psychology, 52(1), 81–90. Studio con autovalutazioni e valutazioni di osservatori; abstract e collegamenti in PubMed.","url":"https://pubmed.ncbi.nlm.nih.gov/3820081/"},{"label":"Costa e McCrae (1992) · Four ways five factors are basic","citation":"Costa, P. T., Jr., & McCrae, R. R. (1992). Four ways five factors are basic. Personality and Individual Differences, 13(6), 653–665. Inquadramento teorico ed empirico delle cinque dimensioni. Il link conduce alla pagina dell’editore.","url":"https://doi.org/10.1016/0191-8869(92)90236-I"},{"label":"John e Srivastava (1999) · Tassonomia e definizioni dei Big Five","citation":"John, O. P., & Srivastava, S. (1999). The Big Five trait taxonomy: History, measurement, and theoretical perspectives. In L. A. Pervin & O. P. John (Eds.), Handbook of personality: Theory and research (2nd ed., pp. 102–138). Guilford Press. Capitolo consultabile in PDF nell’archivio universitario.","url":"https://jenni.uchicago.edu/econ-psych-traits/John_Srivastava_1995_big5.pdf"}],"referenceHeading":"BIG FIVE · STUDI E RIFERIMENTI","referenceOrigin":"Costa e McCrae per lo sviluppo e la validazione del modello, John e Srivastava per la tassonomia dei tratti: riferimenti bibliografici aggiunti alla scheda. Gli animali sono quelli scelti dall’autore della serie. Scene e slogan esprimono una lettura editoriale del rapporto fra tratti, relazione e contesto. L’argomento è approfondito in Psiche & Thanatos, come indicato dall’autore.","status":"definitive","order":116,"seriesNumber":119,"approvalBatch":32,"note":"Poster definitivo fornito dall’autore nel trentaduesimo gruppo di allegati, 23 ottobre 2026. Titolo, slogan e chiusura trascritti dall’originale. Soggetto: Quokka. Il PNG originale 2305×4096 è conservato senza modifiche.","image":"assets/definitivi/ocean-agreeableness-original.png","original":"assets/definitivi/ocean-agreeableness-original.png","thumb":"assets/definitivi/ocean-agreeableness-thumb.webp","variants":[],"bookTitle":"Psiche & Thanatos","bookUrl":"https://www.amazon.it/dp/B0DVCC1HY6","topic":"I cinque tratti"},{"id":"ocean-neuroticism","sourceName":"90993.png","name":"Nevroticismo","english":"Neuroticism","animal":"Pangolino","animals":["Pangolino"],"oceanLetter":"N","slogan":"La relazione riconosce i segnali di allarme e ne valuta il significato. Il limite lascia che la preoccupazione trasformi ogni incertezza in una possibile minaccia.","closing":"Anteprima prudentemente preoccupata del prossimo libro.","description":"Il nevroticismo descrive la tendenza a sperimentare emozioni negative, come preoccupazione, tensione e vulnerabilità allo stress; all’altro polo si parla di stabilità emotiva. Nel modello indica un tratto di personalità. Il poster richiama la distinzione tra segnali presenti e scenari temuti.","example":"Il pangolino immagina pioggia, caduta di un ramo e altri pericoli, mentre gli altri animali proseguono le loro attività. Le nuvole di pensiero «E se…?» mostrano l’anticipazione di possibili minacce; la scena invita a valutarle alla luce di ciò che sta accadendo.","question":"Quali segnali sto osservando e quali scenari sto anticipando senza averli ancora verificati?","aliases":["OCEAN","Big Five","N","neuroticism","nevroticismo","stabilità emotiva","emotività negativa","preoccupazione","vulnerabilità allo stress","e se piovesse","e se cadesse"],"family":"Tratti di personalità","section":"Tratti di personalità (OCEAN)","authors":["Paul T. Costa Jr.","Robert R. McCrae","Oliver P. John","Sanjay Srivastava"],"references":[{"label":"McCrae e Costa (1987) · Validazione del modello a cinque fattori","citation":"McCrae, R. R., & Costa, P. T., Jr. (1987). Validation of the five-factor model of personality across instruments and observers. Journal of Personality and Social Psychology, 52(1), 81–90. Studio con autovalutazioni e valutazioni di osservatori; abstract e collegamenti in PubMed.","url":"https://pubmed.ncbi.nlm.nih.gov/3820081/"},{"label":"Costa e McCrae (1992) · Four ways five factors are basic","citation":"Costa, P. T., Jr., & McCrae, R. R. (1992). Four ways five factors are basic. Personality and Individual Differences, 13(6), 653–665. Inquadramento teorico ed empirico delle cinque dimensioni. Il link conduce alla pagina dell’editore.","url":"https://doi.org/10.1016/0191-8869(92)90236-I"},{"label":"John e Srivastava (1999) · Tassonomia e definizioni dei Big Five","citation":"John, O. P., & Srivastava, S. (1999). The Big Five trait taxonomy: History, measurement, and theoretical perspectives. In L. A. Pervin & O. P. John (Eds.), Handbook of personality: Theory and research (2nd ed., pp. 102–138). Guilford Press. Capitolo consultabile in PDF nell’archivio universitario.","url":"https://jenni.uchicago.edu/econ-psych-traits/John_Srivastava_1995_big5.pdf"}],"referenceHeading":"BIG FIVE · STUDI E RIFERIMENTI","referenceOrigin":"Costa e McCrae per lo sviluppo e la validazione del modello, John e Srivastava per la tassonomia dei tratti: riferimenti bibliografici aggiunti alla scheda. Gli animali sono quelli scelti dall’autore della serie. Scene e slogan esprimono una lettura editoriale del rapporto fra tratti, relazione e contesto. L’argomento è approfondito in Psiche & Thanatos, come indicato dall’autore.","status":"definitive","order":117,"seriesNumber":120,"approvalBatch":32,"note":"Poster definitivo fornito dall’autore nel trentaduesimo gruppo di allegati, 23 ottobre 2026. Titolo, slogan e chiusura trascritti dall’originale. Soggetto: Pangolino. Il PNG originale 2305×4096 è conservato senza modifiche.","image":"assets/definitivi/ocean-neuroticism-original.png","original":"assets/definitivi/ocean-neuroticism-original.png","thumb":"assets/definitivi/ocean-neuroticism-thumb.webp","variants":[],"bookTitle":"Psiche & Thanatos","bookUrl":"https://www.amazon.it/dp/B0DVCC1HY6","topic":"I cinque tratti"},{"id":"strategic-double-bind","sourceName":"92623.png","name":"Doppio legame","english":"Double bind","animal":"Canide adulto · Cucciolo","animals":["Canide","Cane","Cucciolo"],"detailHeading":"IL CONCETTO","slogan":"La relazione permette di chiarire anche ciò che si contraddice. Il limite impone messaggi incompatibili senza lasciare spazio per discuterli.","closing":"Anteprima spaventosamente contraddittoria del prossimo libro.","description":"Il doppio legame implica messaggi incompatibili su livelli diversi, ripetuti in una relazione significativa, senza possibilità di chiarirli o sottrarsi. L’ordine di essere spontanei illustra un’ingiunzione paradossale: da solo non esaurisce queste condizioni.","example":"Alla porta di casa, il canide adulto dice al cucciolo travestito da fantasma: «Vai! e sii spontaneo!». Il cucciolo esita: come può essere spontaneo obbedendo a un ordine? Il poster invita a rendere discutibile la contraddizione.","question":"Posso chiedere di chiarire i messaggi incompatibili che ricevo?","aliases":["double bind","doppio vincolo","ingiunzione paradossale","sii spontaneo","metacomunicazione","Halloween"],"authors":["Gregory Bateson","Don D. Jackson","Jay Haley","John H. Weakland","Paul Watzlawick","Janet Helmick Beavin"],"references":[{"label":"Bateson e colleghi (1956) · Il doppio legame","citation":"Bateson, G., Jackson, D. D., Haley, J., & Weakland, J. (1956). Toward a theory of schizophrenia. Behavioral Science, 1(4), 251–264. Articolo storico che introduce il doppio legame; il link conduce alla pagina dell’editore. Qui è richiamato per il concetto comunicativo.","url":"https://onlinelibrary.wiley.com/doi/10.1002/bs.3830010402"},{"label":"Watzlawick, Beavin e Jackson (1967) · Pragmatics of Human Communication","citation":"Watzlawick, P., Beavin, J. H., & Jackson, D. D. (1967). Pragmatics of Human Communication: A Study of Interactional Patterns, Pathologies, and Paradoxes. W. W. Norton. Il collegamento conduce alla scheda editoriale della riedizione del 2014.","url":"https://wwnorton.co.uk/books/9780393710595-pragmatics-of-human-communication-60735b42-ed77-4386-aa44-146199ea5e9a"}],"posterTitle":"Doppio legame","family":"Psicologia strategica","section":"Psicologia Strategica","status":"definitive","order":118,"seriesNumber":121,"approvalBatch":33,"referenceHeading":"COMUNICAZIONE E SISTEMI · RIFERIMENTI","referenceOrigin":"Riferimenti bibliografici aggiunti alla scheda per inquadrare il concetto. Il poster, gli animali, gli slogan e la narrazione di Halloween appartengono alla serie dell’autore; non sono citazioni letterali degli studiosi.","note":"Poster definitivo fornito dall’autore il 31 ottobre 2026 per la sezione Psicologia Strategica. Titolo, slogan e chiusura trascritti dall’originale. Il PNG è conservato senza modifiche.","image":"assets/definitivi/strategic-double-bind-original.png","original":"assets/definitivi/strategic-double-bind-original.png","thumb":"assets/definitivi/strategic-double-bind-thumb.webp","variants":[],"topic":"Modelli e strategie"},{"id":"communication-axiom-1","sourceName":"92641.png","name":"Non si può non comunicare","english":"One cannot not communicate · First axiom","animal":"Cucciolo · Gatto nero","animals":["Cane","Cucciolo","Gatto"],"detailHeading":"L’ASSIOMA","axiomNumber":1,"slogan":"Anche il silenzio ha qualcosa da dire. Il limite pensa che tacere significhi non comunicare. La relazione riconosce che anche il comportamento comunica.","closing":"Anteprima spaventosamente eloquente del prossimo libro.","description":"In un’interazione anche silenzio, immobilità o allontanamento possono assumere valore comunicativo. Comunicare non richiede sempre parole o un’intenzione consapevole.","example":"Il gatto nero vestito da strega domanda: «Ehi, fantasmino... hai paura di me?». Il cucciolo resta in silenzio e trema. La scena mostra una risposta fatta di comportamento; il suo significato va compreso nella situazione.","question":"Che cosa comunica il mio modo di esserci, anche quando non parlo?","aliases":["primo assioma","1 assioma","silenzio","comportamento","Halloween"],"authors":["Paul Watzlawick","Janet Helmick Beavin","Don D. Jackson"],"references":[{"label":"Watzlawick, Beavin e Jackson (1967) · Pragmatics of Human Communication","citation":"Watzlawick, P., Beavin, J. H., & Jackson, D. D. (1967). Pragmatics of Human Communication: A Study of Interactional Patterns, Pathologies, and Paradoxes. W. W. Norton. Il collegamento conduce alla scheda editoriale della riedizione del 2014.","url":"https://wwnorton.co.uk/books/9780393710595-pragmatics-of-human-communication-60735b42-ed77-4386-aa44-146199ea5e9a"}],"posterTitle":"Non si può non comunicare","family":"Psicologia strategica","section":"Psicologia Strategica","status":"definitive","order":119,"seriesNumber":122,"approvalBatch":33,"referenceHeading":"COMUNICAZIONE E SISTEMI · RIFERIMENTI","referenceOrigin":"Riferimenti bibliografici aggiunti alla scheda per inquadrare il concetto. Il poster, gli animali, gli slogan e la narrazione di Halloween appartengono alla serie dell’autore; non sono citazioni letterali degli studiosi.","note":"Poster definitivo fornito dall’autore il 31 ottobre 2026 per la sezione Psicologia Strategica. Titolo, slogan e chiusura trascritti dall’originale. Il PNG è conservato senza modifiche.","image":"assets/definitivi/communication-axiom-1-original.png","original":"assets/definitivi/communication-axiom-1-original.png","thumb":"assets/definitivi/communication-axiom-1-thumb.webp","variants":[],"topic":"Assiomi della comunicazione"},{"id":"communication-axiom-2","sourceName":"92643.png","name":"Contenuto e relazione","english":"Content and relationship · Second axiom","animal":"Cucciolo · Gufo","animals":["Cane","Cucciolo","Gufo"],"detailHeading":"L’ASSIOMA","axiomNumber":2,"posterTitle":"Ogni comunicazione ha un contenuto e un aspetto di relazione","slogan":"Le parole non bastano. Il limite si concentra solo sul contenuto del messaggio. La relazione ne determina il significato.","closing":"Anteprima spaventosamente ambigua del prossimo libro.","description":"Ogni comunicazione presenta un contenuto e un aspetto di relazione, che orienta come interpretarlo. Tono, contesto e rapporto fra interlocutori contribuiscono al senso delle parole.","example":"Il gufo invita: «Vieni qui a prendere le caramelle!». Il cucciolo si chiede se sia gentile o se sia una trappola. Le stesse parole possono essere lette diversamente a seconda della relazione percepita.","question":"Oltre a ciò che viene detto, come viene definita la relazione?","aliases":["secondo assioma","2 assioma","ogni comunicazione ha un contenuto e un aspetto di relazione","caramelle","Halloween"],"authors":["Paul Watzlawick","Janet Helmick Beavin","Don D. Jackson"],"references":[{"label":"Watzlawick, Beavin e Jackson (1967) · Pragmatics of Human Communication","citation":"Watzlawick, P., Beavin, J. H., & Jackson, D. D. (1967). Pragmatics of Human Communication: A Study of Interactional Patterns, Pathologies, and Paradoxes. W. W. Norton. Il collegamento conduce alla scheda editoriale della riedizione del 2014.","url":"https://wwnorton.co.uk/books/9780393710595-pragmatics-of-human-communication-60735b42-ed77-4386-aa44-146199ea5e9a"}],"family":"Psicologia strategica","section":"Psicologia Strategica","status":"definitive","order":120,"seriesNumber":123,"approvalBatch":33,"referenceHeading":"COMUNICAZIONE E SISTEMI · RIFERIMENTI","referenceOrigin":"Riferimenti bibliografici aggiunti alla scheda per inquadrare il concetto. Il poster, gli animali, gli slogan e la narrazione di Halloween appartengono alla serie dell’autore; non sono citazioni letterali degli studiosi.","note":"Poster definitivo fornito dall’autore il 31 ottobre 2026 per la sezione Psicologia Strategica. Titolo, slogan e chiusura trascritti dall’originale. Il PNG è conservato senza modifiche.","image":"assets/definitivi/communication-axiom-2-original.png","original":"assets/definitivi/communication-axiom-2-original.png","thumb":"assets/definitivi/communication-axiom-2-thumb.webp","variants":[],"topic":"Assiomi della comunicazione"},{"id":"communication-axiom-3","sourceName":"92767.png","name":"Punteggiatura delle sequenze comunicative","english":"Punctuation of communication sequences · Third axiom","animal":"Cucciolo · Scheletro","animals":["Cane","Cucciolo","Scheletro"],"detailHeading":"L’ASSIOMA","axiomNumber":3,"posterTitle":"La natura di una relazione dipende dalla punteggiatura delle sequenze comunicative","slogan":"Ognuno vede nell’altro la causa della propria reazione. Il limite cerca chi ha cominciato. La relazione riconosce la circolarità delle reciproche reazioni.","closing":"Anteprima spaventosamente circolare del prossimo libro.","description":"Gli interlocutori possono individuare inizi diversi nella stessa sequenza di scambi. Ciascuno può vivere il proprio comportamento come risposta all’altro, alimentando un circuito di reciproche reazioni.","example":"Il cucciolo dice: «Scappo perché mi insegui!». Lo scheletro risponde: «Ti inseguo perché scappi!». Ognuno colloca nell’altro l’inizio della sequenza. Riconoscere il circuito permette di cercare un punto in cui modificarlo.","question":"Quale mia risposta contribuisce a mantenere lo scambio che vorrei cambiare?","aliases":["terzo assioma","3 assioma","circolarità","scappo perché mi insegui","ti inseguo perché scappi","Halloween"],"authors":["Paul Watzlawick","Janet Helmick Beavin","Don D. Jackson"],"references":[{"label":"Watzlawick, Beavin e Jackson (1967) · Pragmatics of Human Communication","citation":"Watzlawick, P., Beavin, J. H., & Jackson, D. D. (1967). Pragmatics of Human Communication: A Study of Interactional Patterns, Pathologies, and Paradoxes. W. W. Norton. Il collegamento conduce alla scheda editoriale della riedizione del 2014.","url":"https://wwnorton.co.uk/books/9780393710595-pragmatics-of-human-communication-60735b42-ed77-4386-aa44-146199ea5e9a"}],"family":"Psicologia strategica","section":"Psicologia Strategica","status":"definitive","order":121,"seriesNumber":124,"approvalBatch":33,"referenceHeading":"COMUNICAZIONE E SISTEMI · RIFERIMENTI","referenceOrigin":"Riferimenti bibliografici aggiunti alla scheda per inquadrare il concetto. Il poster, gli animali, gli slogan e la narrazione di Halloween appartengono alla serie dell’autore; non sono citazioni letterali degli studiosi.","note":"Poster definitivo fornito dall’autore il 31 ottobre 2026 per la sezione Psicologia Strategica. Titolo, slogan e chiusura trascritti dall’originale. Il PNG è conservato senza modifiche.","image":"assets/definitivi/communication-axiom-3-original.png","original":"assets/definitivi/communication-axiom-3-original.png","thumb":"assets/definitivi/communication-axiom-3-thumb.webp","variants":[],"topic":"Assiomi della comunicazione"},{"id":"communication-axiom-4","sourceName":"92668.png","name":"Comunicazione digitale e analogica","english":"Digital and analogic communication · Fourth axiom","animal":"Cucciolo · Lupo mannaro","animals":["Cane","Cucciolo","Lupo mannaro"],"detailHeading":"L’ASSIOMA","axiomNumber":4,"posterTitle":"La comunicazione è digitale e analogica","slogan":"Le parole possono negare ciò che il corpo mostra. Il limite si affida soltanto alle parole. La relazione riconosce il linguaggio digitale e quello analogico.","closing":"Anteprima spaventosamente discordante del prossimo libro.","description":"“Digitale” indica qui il linguaggio simbolico, come le parole; “analogico” comprende aspetti non verbali e contestuali. La loro discordanza richiede interpretazione, senza rendere il corpo una prova infallibile delle intenzioni.","example":"Il lupo mannaro trema mentre dice al cucciolo: «N-non ho paura dei fantasmi!». Nel racconto parole e comportamento appaiono discordanti. Il significato si comprende considerando insieme i canali e il contesto.","question":"Parole, tono e gesti sono concordi? Che cosa posso chiarire con l’altro?","aliases":["quarto assioma","4 assioma","linguaggio non verbale","verbale","digitale analogico","Halloween"],"authors":["Paul Watzlawick","Janet Helmick Beavin","Don D. Jackson"],"references":[{"label":"Watzlawick, Beavin e Jackson (1967) · Pragmatics of Human Communication","citation":"Watzlawick, P., Beavin, J. H., & Jackson, D. D. (1967). Pragmatics of Human Communication: A Study of Interactional Patterns, Pathologies, and Paradoxes. W. W. Norton. Il collegamento conduce alla scheda editoriale della riedizione del 2014.","url":"https://wwnorton.co.uk/books/9780393710595-pragmatics-of-human-communication-60735b42-ed77-4386-aa44-146199ea5e9a"}],"family":"Psicologia strategica","section":"Psicologia Strategica","status":"definitive","order":122,"seriesNumber":125,"approvalBatch":33,"referenceHeading":"COMUNICAZIONE E SISTEMI · RIFERIMENTI","referenceOrigin":"Riferimenti bibliografici aggiunti alla scheda per inquadrare il concetto. Il poster, gli animali, gli slogan e la narrazione di Halloween appartengono alla serie dell’autore; non sono citazioni letterali degli studiosi.","note":"Poster definitivo fornito dall’autore il 31 ottobre 2026 per la sezione Psicologia Strategica. Titolo, slogan e chiusura trascritti dall’originale. Il PNG è conservato senza modifiche.","image":"assets/definitivi/communication-axiom-4-original.png","original":"assets/definitivi/communication-axiom-4-original.png","thumb":"assets/definitivi/communication-axiom-4-thumb.webp","variants":[],"topic":"Assiomi della comunicazione"},{"id":"communication-axiom-5","sourceName":"92687.png","name":"Interazioni simmetriche e complementari","english":"Symmetrical and complementary interactions · Fifth axiom","animal":"Cucciolo · Mostro di Frankenstein","animals":["Cane","Cucciolo","Mostro di Frankenstein"],"detailHeading":"L’ASSIOMA","axiomNumber":5,"slogan":"A volte ci rispecchiamo. Altre volte ci completiamo. Il limite trasforma le differenze in una questione di superiorità. La relazione si costruisce attraverso posizioni simmetriche o complementari.","closing":"Anteprima spaventosamente complementare del prossimo libro.","description":"Gli scambi simmetrici si organizzano attorno all’uguaglianza delle posizioni; quelli complementari attorno alla loro differenza. Nessuna delle due configurazioni è di per sé migliore o indice del valore delle persone.","example":"All’ingresso della festa di Halloween, il mostro di Frankenstein offre dolci al cucciolo. Offrire e ricevere illustrano ruoli complementari nella scena: una differenza di posizione che non implica superiorità personale.","question":"Come si coordinano le nostre posizioni in questo scambio?","aliases":["quinto assioma","5 assioma","simmetria","complementarità","posizioni relazionali","Halloween"],"authors":["Paul Watzlawick","Janet Helmick Beavin","Don D. Jackson"],"references":[{"label":"Watzlawick, Beavin e Jackson (1967) · Pragmatics of Human Communication","citation":"Watzlawick, P., Beavin, J. H., & Jackson, D. D. (1967). Pragmatics of Human Communication: A Study of Interactional Patterns, Pathologies, and Paradoxes. W. W. Norton. Il collegamento conduce alla scheda editoriale della riedizione del 2014.","url":"https://wwnorton.co.uk/books/9780393710595-pragmatics-of-human-communication-60735b42-ed77-4386-aa44-146199ea5e9a"}],"posterTitle":"Interazioni simmetriche e complementari","family":"Psicologia strategica","section":"Psicologia Strategica","status":"definitive","order":123,"seriesNumber":126,"approvalBatch":33,"referenceHeading":"COMUNICAZIONE E SISTEMI · RIFERIMENTI","referenceOrigin":"Riferimenti bibliografici aggiunti alla scheda per inquadrare il concetto. Il poster, gli animali, gli slogan e la narrazione di Halloween appartengono alla serie dell’autore; non sono citazioni letterali degli studiosi.","note":"Poster definitivo fornito dall’autore il 31 ottobre 2026 per la sezione Psicologia Strategica. Titolo, slogan e chiusura trascritti dall’originale. Il PNG è conservato senza modifiche.","image":"assets/definitivi/communication-axiom-5-original.png","original":"assets/definitivi/communication-axiom-5-original.png","thumb":"assets/definitivi/communication-axiom-5-thumb.webp","variants":[],"topic":"Assiomi della comunicazione"},{"id":"strategic-feedback","sourceName":"92715.png","name":"Retroazione negativa","english":"Negative feedback","animal":"Cucciolo · Lupo mannaro · Gufo · Scheletro · Gatto nero · Mostro di Frankenstein","animals":["Cane","Cucciolo","Lupo mannaro","Gufo","Scheletro","Gatto","Mostro di Frankenstein"],"detailHeading":"IL MECCANISMO","slogan":"Quando la paura sale, qualcuno abbassa il volume. Il limite ignora il segnale e insiste. La relazione accoglie il feedback e corregge la risposta, ristabilendo l’equilibrio.","closing":"Anteprima spaventosamente equilibrata del prossimo libro.","description":"La retroazione negativa contrasta una deviazione e contribuisce alla stabilità di un sistema. “Negativa” indica il verso della correzione: non significa critica, punizione o giudizio sfavorevole.","example":"Alla festa il lupo mannaro regola il grammofono, mentre il cucciolo ritrova serenità fra gli invitati. Lo slogan usa l’abbassamento del volume come metafora di una risposta che accoglie il segnale di paura e riduce l’intensità dello stimolo.","question":"Quale segnale sto ricevendo e quale aggiustamento può ridurre lo squilibrio?","aliases":["feedback negativo","regolazione","equilibrio","cibernetica","grammofono","volume","Halloween"],"authors":["Norbert Wiener","Paul Watzlawick","Janet Helmick Beavin","Don D. Jackson"],"references":[{"label":"Wiener (1948/1961) · Cybernetics","citation":"Wiener, N. (1948; seconda edizione 1961). Cybernetics: or Control and Communication in the Animal and the Machine. Il link conduce alla riedizione MIT Press del 2019 della seconda edizione, con accesso all’edizione aperta.","url":"https://mitpress.mit.edu/9780262537841/cybernetics-or-control-and-communication-in-the-animal-and-the-machine/"},{"label":"Watzlawick, Beavin e Jackson (1967) · Pragmatics of Human Communication","citation":"Watzlawick, P., Beavin, J. H., & Jackson, D. D. (1967). Pragmatics of Human Communication: A Study of Interactional Patterns, Pathologies, and Paradoxes. W. W. Norton. Il collegamento conduce alla scheda editoriale della riedizione del 2014.","url":"https://wwnorton.co.uk/books/9780393710595-pragmatics-of-human-communication-60735b42-ed77-4386-aa44-146199ea5e9a"}],"posterTitle":"Retroazione negativa","family":"Psicologia strategica","section":"Psicologia Strategica","status":"definitive","order":124,"seriesNumber":127,"approvalBatch":33,"referenceHeading":"COMUNICAZIONE E SISTEMI · RIFERIMENTI","referenceOrigin":"Riferimenti bibliografici aggiunti alla scheda per inquadrare il concetto. Il poster, gli animali, gli slogan e la narrazione di Halloween appartengono alla serie dell’autore; non sono citazioni letterali degli studiosi.","note":"Poster definitivo fornito dall’autore il 31 ottobre 2026 per la sezione Psicologia Strategica. Titolo, slogan e chiusura trascritti dall’originale. Il PNG è conservato senza modifiche.","image":"assets/definitivi/strategic-feedback-original.png","original":"assets/definitivi/strategic-feedback-original.png","thumb":"assets/definitivi/strategic-feedback-thumb.webp","variants":[],"topic":"Modelli e strategie"},{"id":"continuing-bonds","sourceName":"93027.png","name":"Legami che continuano","english":"Continuing bonds","animal":"Cane nudo","animals":["Cane","Cane nudo"],"slogan":"La relazione trova nei ricordi un modo per continuare il legame. Il limite crede che andare avanti significhi dimenticare.","closing":"Anteprima affettuosamente ricordata del prossimo libro.","description":"L’espressione continuing bonds indica la possibilità che il rapporto con una persona morta continui in forma simbolica e interiore, attraverso ricordi, gesti e significati condivisi. Elaborare la perdita può comportare trasformare quel legame, senza dover cancellare il ricordo. Le forme e il significato di questa continuità variano fra persone e nel tempo.","example":"Un cane nudo si trova accanto a un’ofrenda, tra fotografie, fiori arancioni e candele, nell’ambientazione del Día de Muertos. Le figure luminose nel cielo richiamano le persone ritratte nelle cornici: una rappresentazione narrativa del ricordo e del legame affettivo che può trovare posto nella vita presente.","question":"Quale ricordo, gesto o valore può dare oggi un posto a questo legame nella mia vita?","aliases":["continuing bonds","legami che continuano","continuità del legame","legame affettivo","lutto","perdita","ricordi","memoria affettiva","ofrenda","Día de Muertos","Día de los Muertos","Giorno dei morti"],"family":"Relazione","section":"Mente, esperienza e relazione","detailHeading":"IL CONCETTO","authors":["Dennis Klass","Phyllis R. Silverman","Steven L. Nickman","Paul A. Boelen","Margaret S. Stroebe","Henk A. W. Schut","Annemieke M. Zijerveld"],"references":[{"label":"Klass, Silverman e Nickman (1996) · Continuing Bonds","citation":"Klass, D., Silverman, P. R., & Nickman, S. L. (Eds.). (1996). Continuing bonds: New understandings of grief. Taylor & Francis. Volume collettaneo di riferimento sulla continuità del legame con la persona morta. Il link conduce alla scheda editoriale del libro.","url":"https://www.routledge.com/Continuing-Bonds-New-Understandings-of-Grief/Klass-Silverman-Nickman/p/book/9781315800790"},{"label":"Boelen e colleghi (2006) · Continuing bonds and grief","citation":"Boelen, P. A., Stroebe, M. S., Schut, H. A. W., & Zijerveld, A. M. (2006). Continuing bonds and grief: A prospective analysis. Death Studies, 30(8), 767–776. Studio prospettico: diverse forme del legame mostrano associazioni differenti con il lutto successivo. Il link offre l’abstract in PubMed e i rimandi al testo dell’editore.","url":"https://pubmed.ncbi.nlm.nih.gov/16972374/"}],"referenceHeading":"LUTTO E CONTINUITÀ DEL LEGAME · RIFERIMENTI","referenceOrigin":"Riferimenti bibliografici aggiunti alla scheda per inquadrare il concetto. La scena, gli animali e gli slogan appartengono alla serie dell’autore. Il poster propone una lettura narrativa del ricordo, senza prescrivere un unico modo di vivere il lutto.","status":"definitive","note":"Poster definitivo fornito dall’autore il 1° novembre 2026 per la sezione Mente, esperienza e relazione. Soggetto: cane nudo accanto a un’ofrenda. Titolo, slogan e chiusura trascritti dall’originale. Il PNG originale 2305×4096 è conservato senza modifiche.","image":"assets/definitivi/continuing-bonds-original.png","original":"assets/definitivi/continuing-bonds-original.png","thumb":"assets/definitivi/continuing-bonds-thumb.webp","variants":[],"order":125,"seriesNumber":128,"approvalBatch":34,"topic":"Relazioni, legami e dinamiche sociali"},{"id":"resilience","sourceName":"93638.png","name":"Resilienza","english":"Resilience","animal":"Pettirossi","animals":["Pettirosso"],"slogan":"La relazione riconosce le ferite e accompagna la possibilità di ritrovare un equilibrio. Il limite confonde la resilienza con il dover essere sempre forti, come se nulla fosse accaduto.","closing":"Anteprima nonostante tutto ancora in cammino del prossimo libro.","description":"La resilienza riguarda la possibilità di mantenere o ritrovare un funzionamento adeguato di fronte ad avversità significative. Si sviluppa nel tempo attraverso risorse personali, relazioni e condizioni del contesto, e può convivere con dolore e vulnerabilità. Le singole strategie di coping contribuiscono all’adattamento, senza esaurire questo processo.","example":"Due pettirossi si trovano su un ramo spezzato, mentre la pioggia lascia spazio al sole. Uno porta una ferita e canta; l’altro gli rimane accanto. La scena richiama la possibilità di proseguire con le proprie ferite e con il sostegno di una relazione. Il canto è una metafora narrativa, non una richiesta di mostrarsi sempre sereni.","question":"Quali risorse e quali relazioni possono aiutarmi a ritrovare un equilibrio, riconoscendo quello che ho vissuto?","aliases":["resilience","resilienza","adattamento","avversità","vulnerabilità","ferite","sostegno relazionale","equilibrio","tempesta","pettirosso"],"family":"Relazione","section":"Mente, esperienza e relazione","detailHeading":"IL PROCESSO","authors":["Ann S. Masten","Steven M. Southwick","George A. Bonanno","Catherine Panter-Brick","Rachel Yehuda"],"references":[{"label":"Masten (2001) · Ordinary magic","citation":"Masten, A. S. (2001). Ordinary magic: Resilience processes in development. American Psychologist, 56(3), 227–238. Riferimento sui processi di adattamento e sui sistemi protettivi nello sviluppo. Il link offre l’abstract in PubMed e i rimandi al testo dell’editore.","url":"https://pubmed.ncbi.nlm.nih.gov/11315249/"},{"label":"Southwick e colleghi (2014) · Definizioni e prospettive sulla resilienza","citation":"Southwick, S. M., Bonanno, G. A., Masten, A. S., Panter-Brick, C., & Yehuda, R. (2014). Resilience definitions, theory, and challenges: Interdisciplinary perspectives. European Journal of Psychotraumatology, 5, 25338. Confronto multidisciplinare su resilienza, adattamento nel tempo e risorse del contesto. Testo integrale nell’archivio PubMed Central.","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC4185134/"}],"referenceHeading":"RESILIENZA · STUDI E RIFERIMENTI","referenceOrigin":"Riferimenti bibliografici aggiunti alla scheda per inquadrare il concetto. Animali, scena e slogan appartengono alla serie dell’autore. L’argomento è approfondito in Psiche & Thanatos, come indicato dall’autore.","status":"definitive","note":"Poster definitivo fornito dall’autore il 4 novembre 2026. Soggetto: due pettirossi su un ramo spezzato dopo la tempesta. Titolo, slogan e chiusura trascritti dall’originale. Il PNG originale 2305×4096 è conservato senza modifiche.","image":"assets/definitivi/resilience-original.png","original":"assets/definitivi/resilience-original.png","thumb":"assets/definitivi/resilience-thumb.webp","variants":[],"bookTitle":"Psiche & Thanatos","bookUrl":"https://www.amazon.it/dp/B0DVCC1HY6","order":126,"seriesNumber":129,"approvalBatch":35,"topic":"Relazioni, legami e dinamiche sociali"},{"id":"hebb-learning","name":"La legge di Hebb","english":"Hebbian learning","animal":"Volpe","animals":["Volpe"],"family":"Psicologia strategica","section":"Psicologia Strategica","topic":"Modelli e strategie","detailHeading":"IL PRINCIPIO","slogan":"Le esperienze ripetute plasmano il nostro modo di pensare, sentire e agire. Ciò che diventa abituale può facilitarci, ma anche limitarci. Le esperienze condivise consolidano legami, fiducia e aspettative.","description":"La ripetizione non rende necessariamente più efficace un comportamento: può semplicemente renderlo più abituale. Ciò che abbiamo imparato a fare può diventare una risorsa, ma anche un limite, quando continuiamo a riprodurre modalità di risposta che non risultano più funzionali. Il cambiamento richiede allora nuove esperienze, capaci di favorire apprendimenti alternativi e modificare le modalità consolidate con cui interpretiamo e affrontiamo la realtà.","example":"Una giovane volpe impara ad andare in bicicletta. Nei primi tentativi è incerta e il movimento richiede molta attenzione; con l’esercizio diventa più coordinato e fluido. Un’altra volpe la incoraggia: la scena richiama anche il ruolo delle esperienze condivise. L’apprendimento motorio coinvolge diversi meccanismi, non soltanto la plasticità hebbiana.","question":"Sto ripetendo questo comportamento perché è ancora utile o soprattutto perché mi è diventato familiare?","aliases":["Hebb","apprendimento hebbiano","plasticità sinaptica","neuroplasticità","ripetizione","abitudine","apprendimento motorio","cambiamento","tentate soluzioni","bicicletta"],"authors":["Donald O. Hebb","Giorgio Nardone","Paul Watzlawick"],"references":[{"label":"Donald O. Hebb (1949) · Plasticità e apprendimento","citation":"Hebb, D. O. (1949). The organization of behavior: A neuropsychological theory. Wiley.","url":"https://wellcomecollection.org/works/g4sfzum4"},{"label":"Giorgio Nardone e Paul Watzlawick (1990) · Cambiamento strategico","citation":"Nardone, G., & Watzlawick, P. (1990). L’arte del cambiamento: Manuale di terapia strategica e ipnoterapia senza trance. Ponte alle Grazie.","url":"https://www.centroditerapiastrategica.com/pubblicazione/larte-del-cambiamentola-soluzione-dei-problemi-psicologici-personali-e-interpersonali-in-tempi-brevi/"}],"referenceHeading":"APPRENDIMENTO E CAMBIAMENTO · RIFERIMENTI","referenceOrigin":"Hebb (1949) è il riferimento storico per la plasticità sinaptica e gli assemblaggi cellulari. Nardone e Watzlawick (1990) inquadrano il mantenimento dei problemi e il cambiamento nella prospettiva strategica. Il collegamento tra i due livelli è un’interpretazione divulgativa, non un’equivalenza teorica. La formula «i neuroni che si attivano insieme si collegano tra loro» presente nel poster è una sintesi divulgativa, non una citazione testuale di Hebb.","status":"definitive","note":"Poster originale fornito dall’autore il 18 novembre 2026. Formato verticale 2305 × 4096. Testo di riflessione fornito integralmente dall’autore.","image":"assets/definitivi/hebb-learning-original.webp","original":"assets/definitivi/hebb-learning-original.webp","sourceName":"96017.png","thumb":"assets/definitivi/hebb-learning-thumb.webp","variants":[],"closing":"","approvalBatch":36,"order":127,"seriesNumber":130},{"id":"gestione-del-dolore","name":"Gestione del dolore","english":"Coping with emotional pain","animal":"Elefante","animals":["Elefante"],"family":"Psicologia strategica","section":"Psicologia Strategica","topic":"Modelli e strategie","detailHeading":"IL DOLORE NELLA RELAZIONE","slogan":"La relazione attraversa il dolore, gli dà senso e lo trasforma. Il limite vede solo lacrime dove potrebbero nascere perle.","closing":"Anteprima dolorosamente preziosa del prossimo libro.","description":"Una lacrima scende lungo la guancia dell’elefante. Più in basso, nella ciotola, le gocce prendono la forma di perle. Anche dopo una perdita può cambiare il modo in cui viviamo un ricordo. A volte tacciamo per paura di rattristare chi ci è vicino. Se anche l’altro tace per proteggerci, finiamo per custodire in solitudine qualcosa di cui entrambi vorremmo parlare. La prospettiva strategica ci invita a osservare l’effetto di quel silenzio, nato dal desiderio di darci sollievo. La perla rappresenta il significato che un ricordo può assumere quando trova ascolto.","example":"A tavola, Marta comincia a raccontare come suo padre rubava la prima polpetta appena fritta. Le si incrina la voce. Il fratello, che altre volte avrebbe cambiato discorso, stavolta le chiede quale scusa inventasse il padre quando veniva scoperto. Marta sorride e finisce il racconto con le lacrime agli occhi. Per un momento hanno potuto ricordarlo insieme.","question":"Quando cambio discorso davanti alle lacrime di qualcuno, quale disagio sto cercando di alleviare?","aliases":["dolore emotivo","sofferenza","perdita","lutto","ascolto","silenzio","lacrime","perle","elefante","tentate soluzioni","Cavalcare la propria tigre"],"authors":["Giorgio Nardone"],"referenceHeading":"RIFERIMENTO BIBLIOGRAFICO","references":[{"label":"Giorgio Nardone (2003) · Cavalcare la propria tigre","citation":"Nardone, G. (2003). Cavalcare la propria tigre. Gli stratagemmi nelle arti marziali ovvero come risolvere problemi difficili attraverso soluzioni semplici. Ponte alle Grazie.","url":"https://www.centroditerapiastrategica.com/pubblicazione/cavalcare-la-propria-tigregli-stratagemmi-nelle-arti-marziali-ovvero-come-risolvere-problemi-difficili-attraverso-soluzioni-semplici/"}],"referenceOrigin":"Il libro di Nardone approfondisce l’uso degli stratagemmi per affrontare un problema. La metafora delle lacrime che diventano perle e lo slogan sono di Tommaso Corona.","status":"definitive","note":"Poster di Tommaso Corona per la serie Limite & Relazione. Titolo, slogan e frase finale riprendono il testo dell’illustrazione.","image":"assets/definitivi/gestione-del-dolore-original.png","original":"assets/definitivi/gestione-del-dolore-original.png","sourceName":"98227.png","thumb":"assets/definitivi/gestione-del-dolore-thumb.webp","variants":[],"approvalBatch":37,"order":128,"seriesNumber":131}];
